/* 統測選擇題：字彙、文法、情境對話，B1/B2 300 題（M001–M300），加上 A2 入門 40 題（M301–M340）、C1 挑戰 100 題（M341–M380、M421–M480）和 C2 頂尖 100 題（M381–M420、M481–M540），附中文解析。由第二位老師盲解審核。 */
window.MCQ_ITEMS = [{"id": "M001", "type": "vocab", "q": "If you want to return the shoes, you must bring the ______ that shows the date and price of your purchase.", "options": ["license", "receipt", "budget", "menu"], "answer": 1, "explain": "句意：如果你想退還這雙鞋，必須帶著顯示購買日期和價格的收據。receipt 收據，符合「顯示日期與價格」的描述。(A) license 執照 (C) budget 預算 (D) menu 菜單，皆不能證明購買紀錄。故選 (B)。", "level": "B1", "topic": "shopping"}, {"id": "M002", "type": "vocab", "q": "The manager decided to ______ the meeting until next Monday because many staff members were sick.", "options": ["attend", "prevent", "compare", "postpone"], "answer": 3, "explain": "句意：經理決定把會議延到下週一，因為許多員工生病了。postpone 延期，常與 until 連用表示延到某時。(A) attend 參加 (B) prevent 預防 (C) compare 比較，皆無法與 until next Monday 搭配表示延後。故選 (D)。", "level": "B1", "topic": "workplace meetings"}, {"id": "M003", "type": "vocab", "q": "Jenny is very ______; she always tells the truth, even when it gets her into trouble.", "options": ["honest", "jealous", "curious", "nervous"], "answer": 0, "explain": "句意：Jenny 很誠實，即使說實話會讓她惹上麻煩，她仍總是說實話。honest 誠實的。(B) jealous 嫉妒的 (C) curious 好奇的 (D) nervous 緊張的，皆與「總是說實話」無關。故選 (A)。", "level": "B1", "topic": "personality"}, {"id": "M004", "type": "vocab", "q": "Before signing the ______, you should read every page carefully to understand your rights and duties at your new job.", "options": ["complaint", "campaign", "contract", "conflict"], "answer": 2, "explain": "句意：在簽合約之前，你應該仔細閱讀每一頁，了解你在新工作中的權利和義務。contract 合約，可以「簽署」(sign) 並載明權利義務。(A) complaint 抱怨 (B) campaign 活動 (D) conflict 衝突，都不是載明工作權利和義務的文件。故選 (C)。", "level": "B1", "topic": "employment"}, {"id": "M005", "type": "vocab", "q": "To ______ energy, our school turns off the air conditioners in empty classrooms.", "options": ["consume", "produce", "conserve", "release"], "answer": 2, "explain": "句意：為了節約能源，我們學校會關掉空教室裡的冷氣。conserve energy 節約能源。(A) consume 消耗，與目的相反 (B) produce 生產 (D) release 釋放，皆不符合「關冷氣」的目的。故選 (C)。", "level": "B2", "topic": "energy saving"}, {"id": "M006", "type": "vocab", "q": "The road was covered with ice. ______, no one was hurt when the bus slid off the road.", "options": ["Luckily", "Carelessly", "Recently", "Exactly"], "answer": 0, "explain": "句意：路面結冰了。幸運的是，巴士滑出路面時沒有人受傷。Luckily 幸運地，用來表達慶幸的語氣。(B) Carelessly 粗心地 (C) Recently 最近 (D) Exactly 確切地，皆無法銜接「沒有人受傷」的慶幸語氣。故選 (A)。", "level": "B1", "topic": "traffic accident"}, {"id": "M007", "type": "vocab", "q": "This movie is not ______ for young children because it contains many violent scenes.", "options": ["similar", "famous", "polite", "suitable"], "answer": 3, "explain": "句意：這部電影不適合幼童觀看，因為裡面有很多暴力場面。be suitable for 適合……。(A) similar 相似的（應接 to）(B) famous 有名的 (C) polite 有禮貌的，語意皆不通。故選 (D)。", "level": "B1", "topic": "movies"}, {"id": "M008", "type": "vocab", "q": "The company's main ______ this year is to reduce plastic waste by 50 percent.", "options": ["admission", "objective", "occupation", "decoration"], "answer": 1, "explain": "句意：公司今年的主要目標是將塑膠廢棄物減少 50%。objective 目標，後接 to V 說明要達成的事。(A) admission 入場；入學許可 (C) occupation 職業 (D) decoration 裝飾，皆不符語意。故選 (B)。", "level": "B2", "topic": "business goals"}, {"id": "M009", "type": "vocab", "q": "Could you ______ me your umbrella? I left mine at home, and it's raining hard.", "options": ["lend", "borrow", "return", "owe"], "answer": 0, "explain": "句意：你可以借我你的雨傘嗎？我把我的留在家裡，而且雨下得很大。lend sb sth 借（出）某物給某人。(B) borrow 是「向別人借入」，用法為 borrow sth from sb (C) return 歸還，但雨傘本來就是對方的，談不上「還給我」(D) owe 欠，皆不符語意。故選 (A)。", "level": "B1", "topic": "everyday requests"}, {"id": "M010", "type": "vocab", "q": "The instructions for the new printer were so ______ that nobody in the office could figure out how to set it up.", "options": ["practical", "accurate", "convenient", "complicated"], "answer": 3, "explain": "句意：新印表機的說明書太複雜了，辦公室裡沒有人搞得懂要如何安裝。complicated 複雜的，與 so...that nobody could figure out 呼應。(A) practical 實用的 (B) accurate 準確的 (C) convenient 方便的，都是正面意思，與後半句矛盾。故選 (D)。", "level": "B2", "topic": "office equipment"}, {"id": "M011", "type": "vocab", "q": "After graduating from high school, Kevin plans to get a part-time job to gain some work ______.", "options": ["knowledge", "product", "experience", "success"], "answer": 2, "explain": "句意：高中畢業後，Kevin 打算找份兼職工作，累積一些工作經驗。gain work experience 累積工作經驗，為常見搭配。(A) knowledge 知識（不說 gain work knowledge）(B) product 產品 (D) success 成功，皆不符搭配。故選 (C)。", "level": "B1", "topic": "part-time jobs"}, {"id": "M012", "type": "vocab", "q": "The police are still trying to ______ the cause of the fire that destroyed the old warehouse.", "options": ["decorate", "determine", "delay", "deliver"], "answer": 1, "explain": "句意：警方仍在試圖查明燒毀舊倉庫的火災起因。determine the cause 查明原因。(A) decorate 裝飾 (C) delay 延遲 (D) deliver 遞送，皆無法與「起因」搭配。故選 (B)。", "level": "B2", "topic": "news"}, {"id": "M013", "type": "vocab", "q": "The night market is always ______ on Saturday nights; you can hardly move because there are so many people.", "options": ["empty", "silent", "peaceful", "crowded"], "answer": 3, "explain": "句意：夜市每到週六晚上總是很擁擠，人多到你幾乎動不了。crowded 擁擠的。(A) empty 空的 (B) silent 安靜的 (C) peaceful 寧靜的，皆與「人很多」矛盾。故選 (D)。", "level": "B1", "topic": "night markets"}, {"id": "M014", "type": "vocab", "q": "Studying abroad can broaden your ______ and help you understand different cultures.", "options": ["horizons", "obstacles", "statistics", "minorities"], "answer": 0, "explain": "句意：出國讀書可以開拓你的視野，幫助你了解不同的文化。broaden one's horizons 開拓視野，為固定搭配。(B) obstacles 障礙 (C) statistics 統計數字 (D) minorities 少數族群，皆不符語意。故選 (A)。", "level": "B2", "topic": "studying abroad"}, {"id": "M015", "type": "vocab", "q": "Please ______ the form with your name, address, and phone number, and then hand it to the front desk.", "options": ["complain", "complete", "compete", "compare"], "answer": 1, "explain": "句意：請在表格上填寫姓名、地址和電話，然後交給櫃台。complete the form 填寫（完成）表格。(A) complain 抱怨 (C) compete 競爭 (D) compare 比較，皆為字形相近的干擾選項，語意不通。故選 (B)。", "level": "B1", "topic": "forms"}, {"id": "M016", "type": "vocab", "q": "Mr. Lin speaks English slowly and ______, so even beginners can follow what he says.", "options": ["rudely", "rarely", "clearly", "nearly"], "answer": 2, "explain": "句意：林老師說英文說得又慢又清楚，所以連初學者都聽得懂。clearly 清楚地，與 slowly 並列，且能讓初學者聽懂。(A) rudely 無禮地 (B) rarely 很少 (D) nearly 幾乎，皆不合語意。故選 (C)。", "level": "B1", "topic": "teaching"}, {"id": "M017", "type": "vocab", "q": "The mountain trail is ______ only in summer; it is closed in winter because of heavy snow.", "options": ["accessible", "valuable", "flexible", "generous"], "answer": 0, "explain": "句意：這條山路只有夏天才能通行；冬天會因大雪而封閉。accessible 可進入的、可到達的，與 closed 形成對比。(B) valuable 有價值的 (C) flexible 有彈性的 (D) generous 慷慨的，皆無法與「封閉」對照。故選 (A)。", "level": "B2", "topic": "hiking"}, {"id": "M018", "type": "vocab", "q": "The school library has a large ______ of English novels, magazines, and comic books.", "options": ["direction", "reaction", "connection", "collection"], "answer": 3, "explain": "句意：學校圖書館收藏了大量的英文小說、雜誌和漫畫。a large collection of 大量的收藏。(A) direction 方向 (B) reaction 反應 (C) connection 連結，皆不能表示書籍的收藏。故選 (D)。", "level": "B1", "topic": "library"}, {"id": "M019", "type": "vocab", "q": "The new law will ______ drivers from using mobile phones while driving.", "options": ["encourage", "prohibit", "permit", "persuade"], "answer": 1, "explain": "句意：新法將禁止駕駛人在開車時使用手機。prohibit sb from V-ing 禁止某人做某事。(A) encourage 鼓勵 (C) permit 允許 (D) persuade 說服，用法皆為 sb to V，不接 from V-ing，且語意也不合理。故選 (B)。", "level": "B2", "topic": "traffic laws"}, {"id": "M020", "type": "vocab", "q": "I'm ______ of spiders, so I always ask my brother to get them out of my room.", "options": ["proud", "jealous", "afraid", "fond"], "answer": 2, "explain": "句意：我很怕蜘蛛，所以總是請哥哥把牠們弄出我的房間。be afraid of 害怕。(A) be proud of 以……為傲 (B) be jealous of 嫉妒 (D) be fond of 喜愛，皆與「請哥哥把蜘蛛弄走」不符。故選 (C)。", "level": "B1", "topic": "fears"}, {"id": "M021", "type": "vocab", "q": "The travel agency made all the ______ for our trip, including hotel rooms and train tickets.", "options": ["achievements", "appointments", "advertisements", "arrangements"], "answer": 3, "explain": "句意：旅行社為我們的旅程做好了所有安排，包括飯店房間和火車票。make arrangements for 為……做安排。(A) achievements 成就 (B) appointments 約會、預約（指與人約定見面的時間）(C) advertisements 廣告，皆不符語意。故選 (D)。", "level": "B2", "topic": "travel planning"}, {"id": "M022", "type": "vocab", "q": "My mother ______ me to take an umbrella because the weather report said it would rain.", "options": ["reminded", "remembered", "recorded", "repeated"], "answer": 0, "explain": "句意：媽媽提醒我帶雨傘，因為氣象報告說會下雨。remind sb to V 提醒某人做某事。(B) remember 記得，不接 sb to V (C) record 記錄 (D) repeat 重複，皆不合用法與語意。故選 (A)。", "level": "B1", "topic": "family life"}, {"id": "M023", "type": "vocab", "q": "Smoking is ______ banned in all public buildings, and anyone who breaks the rule will be fined.", "options": ["frankly", "slightly", "strictly", "privately"], "answer": 2, "explain": "句意：所有公共建築都嚴格禁菸，違規者將被罰款。strictly banned 嚴格禁止。(A) frankly 坦白地 (B) slightly 稍微地，與罰款的嚴厲語氣矛盾 (D) privately 私下地，皆不合語意。故選 (C)。", "level": "B2", "topic": "public rules"}, {"id": "M024", "type": "vocab", "q": "Taiwan's night markets attract many foreign ______ who come to try local snacks during their vacations.", "options": ["residents", "tourists", "citizens", "employees"], "answer": 1, "explain": "句意：台灣的夜市吸引許多外國觀光客，他們在假期中前來品嚐當地小吃。tourists 觀光客，與 during their vacations 呼應。(A) residents 居民 (C) citizens 公民 (D) employees 員工，皆與「趁假期來品嚐小吃」不符。故選 (B)。", "level": "B1", "topic": "tourism"}, {"id": "M025", "type": "vocab", "q": "The factory was forced to ______ more than 200 workers after its sales dropped sharply.", "options": ["dismiss", "hire", "promote", "reward"], "answer": 0, "explain": "句意：銷售額大幅下滑後，這家工廠被迫解僱兩百多名工人。dismiss 解僱。(B) hire 僱用 (C) promote 升遷 (D) reward 獎勵，皆與「銷售下滑、被迫」的情境矛盾。故選 (A)。", "level": "B2", "topic": "business"}, {"id": "M026", "type": "vocab", "q": "Drinking enough water is ______ for good health, especially on hot summer days.", "options": ["harmful", "useless", "terrible", "essential"], "answer": 3, "explain": "句意：喝足夠的水對健康是不可或缺的，尤其在炎熱的夏天。essential 必要的、不可或缺的。(A) harmful 有害的 (B) useless 無用的 (C) terrible 糟糕的，皆與語意相反。故選 (D)。", "level": "B2", "topic": "health"}, {"id": "M027", "type": "vocab", "q": "The scientist won an award for her important ______ to cancer research.", "options": ["contest", "contribution", "constitution", "consumption"], "answer": 1, "explain": "句意：這位科學家因對癌症研究的重要貢獻而獲獎。contribution to 對……的貢獻。(A) contest 比賽 (C) constitution 憲法 (D) consumption 消耗，皆為字形相近的干擾選項，語意不通。故選 (B)。", "level": "B2", "topic": "science"}, {"id": "M028", "type": "vocab", "q": "Please ______ your seat belt. The plane is about to take off.", "options": ["loosen", "unlock", "fasten", "button"], "answer": 2, "explain": "句意：請繫好安全帶，飛機即將起飛。fasten one's seat belt 繫好安全帶。(A) loosen 鬆開，與語意相反 (B) unlock 解鎖 (D) button 扣（鈕扣），不與 seat belt 搭配。故選 (C)。", "level": "B1", "topic": "air travel"}, {"id": "M029", "type": "vocab", "q": "The restaurant's location is very ______; it's just a five-minute walk from the MRT station.", "options": ["convenient", "delicious", "expensive", "comfortable"], "answer": 0, "explain": "句意：這家餐廳的位置非常便利，從捷運站走路只要五分鐘。convenient 方便的。(B) delicious 美味的 (C) expensive 昂貴的 (D) comfortable 舒適的，皆不能用來形容「位置靠近捷運站」。故選 (A)。", "level": "B1", "topic": "restaurants"}, {"id": "M030", "type": "vocab", "q": "The company has a strict ______ against using personal phones during working hours.", "options": ["habit", "theory", "survey", "policy"], "answer": 3, "explain": "句意：公司有嚴格的規定，禁止員工在上班時間使用私人手機。policy 政策、規定，常與 strict 及 against 搭配。(A) habit 習慣 (B) theory 理論 (C) survey 調查，皆不能表示公司規定。故選 (D)。", "level": "B2", "topic": "company policy"}, {"id": "M031", "type": "vocab", "q": "After the earthquake, volunteers worked day and night to ______ food and water to the victims.", "options": ["estimate", "attract", "distribute", "observe"], "answer": 2, "explain": "句意：地震過後，志工們日以繼夜地發放食物和飲水給災民。distribute sth to sb 分發某物給某人。(A) estimate 估計 (B) attract 吸引 (D) observe 觀察，皆不合語意。故選 (C)。", "level": "B2", "topic": "disaster relief"}, {"id": "M032", "type": "vocab", "q": "There is a big ______ between the prices in the city and those in the countryside.", "options": ["difference", "distance", "decision", "discussion"], "answer": 0, "explain": "句意：城市和鄉村的物價有很大的差異。difference between A and B 指 A 與 B 之間的差異。(B) distance 距離，不用於比較價格 (C) decision 決定 (D) discussion 討論，皆不合語意。故選 (A)。", "level": "B1", "topic": "cost of living"}, {"id": "M033", "type": "vocab", "q": "Our class leader is very ______; she always plans ahead and never misses a deadline.", "options": ["aggressive", "organized", "stubborn", "anxious"], "answer": 1, "explain": "句意：我們的班長做事很有條理，她總是事先計畫，從不錯過截止期限。organized 有條理的。(A) aggressive 好鬥的 (C) stubborn 固執的 (D) anxious 焦慮的，皆與「事先計畫、準時完成」的描述不符。故選 (B)。", "level": "B1", "topic": "school life"}, {"id": "M034", "type": "vocab", "q": "If you don't ______ the flowers every day, they will dry up and die in this hot weather.", "options": ["pick", "cut", "wash", "water"], "answer": 3, "explain": "句意：如果你不每天幫這些花澆水，它們在這種炎熱的天氣裡會乾枯死掉。water 當動詞為「澆水」。(A) pick 摘 (B) cut 剪 (C) wash 清洗，皆無法避免花朵乾枯。故選 (D)。", "level": "B1", "topic": "gardening"}, {"id": "M035", "type": "vocab", "q": "Regular exercise can improve your blood ______ and lower your risk of heart disease.", "options": ["population", "celebration", "circulation", "pollution"], "answer": 2, "explain": "句意：規律運動可以促進血液循環，並降低罹患心臟病的風險。blood circulation 血液循環。(A) population 人口 (B) celebration 慶祝 (D) pollution 污染，皆不能與 blood 搭配。故選 (C)。", "level": "B2", "topic": "exercise"}, {"id": "M036", "type": "vocab", "q": "I ______ go to the movies; I only go once or twice a year.", "options": ["usually", "rarely", "always", "often"], "answer": 1, "explain": "句意：我很少去看電影，一年只去一、兩次。rarely 很少，與「一年一兩次」相符。(A) usually 通常 (C) always 總是 (D) often 經常，皆與很低的頻率矛盾。故選 (B)。", "level": "B1", "topic": "hobbies"}, {"id": "M037", "type": "vocab", "q": "The new manager quickly ______ the trust of her team by listening carefully to everyone's ideas.", "options": ["earned", "wasted", "owed", "refused"], "answer": 0, "explain": "句意：新經理認真傾聽每個人的想法，很快就贏得了團隊的信任。earn sb's trust 贏得某人的信任。(B) wasted 浪費 (C) owed 欠 (D) refused 拒絕，皆與「認真傾聽」帶來的正面結果不符。故選 (A)。", "level": "B2", "topic": "leadership"}, {"id": "M038", "type": "vocab", "q": "It was very ______ of you to help that old woman carry her heavy bags upstairs.", "options": ["rude", "lazy", "kind", "selfish"], "answer": 2, "explain": "句意：你真好心，幫那位老太太把沉重的袋子提上樓。It is kind of sb to V 表示「某人做某事真好心」。(A) rude 無禮的 (B) lazy 懶惰的 (D) selfish 自私的，皆與幫助他人的行為矛盾。故選 (C)。", "level": "B1", "topic": "manners"}, {"id": "M039", "type": "vocab", "q": "The ______ of the new shopping mall took three years and created hundreds of jobs for local workers.", "options": ["destruction", "instruction", "introduction", "construction"], "answer": 3, "explain": "句意：新購物中心的興建花了三年，為當地勞工創造了數百個工作機會。construction 建造、興建。(A) destruction 破壞 (B) instruction 指示 (C) introduction 介紹，皆不符語意。故選 (D)。", "level": "B2", "topic": "urban development"}, {"id": "M040", "type": "vocab", "q": "Tom ______ his leg while playing basketball, so he had to stay in the hospital for a week.", "options": ["stretched", "broke", "shook", "folded"], "answer": 1, "explain": "句意：Tom 打籃球時摔斷了腿，所以必須住院一週。break one's leg 摔斷腿。(A) stretched 伸展 (C) shook 搖動 (D) folded 摺疊，皆不會導致住院。故選 (B)。", "level": "B1", "topic": "sports injuries"}, {"id": "M041", "type": "vocab", "q": "The sales report shows a ______ increase in online orders, from 2,000 to 8,000 in just one year.", "options": ["significant", "slight", "previous", "ordinary"], "answer": 0, "explain": "句意：銷售報告顯示網路訂單大幅增加，一年內從兩千筆成長到八千筆。significant 顯著的、大幅的。(B) slight 輕微的，與四倍成長矛盾 (C) previous 先前的 (D) ordinary 普通的，皆不合語意。故選 (A)。", "level": "B2", "topic": "sales reports"}, {"id": "M042", "type": "vocab", "q": "Excuse me, could you give me ______ to the train station? I think I'm lost.", "options": ["decisions", "suggestions", "directions", "descriptions"], "answer": 2, "explain": "句意：不好意思，可以告訴我去火車站怎麼走嗎？我好像迷路了。directions to + 地點，指路、方向指引。(A) decisions 決定 (B) suggestions 建議 (D) descriptions 描述，皆不能與 to the train station 搭配表示問路。故選 (C)。", "level": "B1", "topic": "asking directions"}, {"id": "M043", "type": "vocab", "q": "Hundreds of workers gathered outside the factory to ______ against low pay and long working hours.", "options": ["promote", "preserve", "predict", "protest"], "answer": 3, "explain": "句意：數百名工人聚集在工廠外，抗議低薪和過長的工時。protest against 抗議……。(A) promote 推廣 (B) preserve 保存 (C) predict 預測，皆不能接 against 表示反對。故選 (D)。", "level": "B2", "topic": "labor issues"}, {"id": "M044", "type": "vocab", "q": "The weather was so ______ that we decided to stay home and watch movies instead of going to the beach.", "options": ["sunny", "terrible", "pleasant", "warm"], "answer": 1, "explain": "句意：天氣太糟了，所以我們決定待在家看電影，而不去海邊。terrible 糟糕的。(A) sunny 晴朗的 (C) pleasant 宜人的 (D) warm 溫暖的，都是適合去海邊的好天氣，與後半句矛盾。故選 (B)。", "level": "B1", "topic": "weather"}, {"id": "M045", "type": "vocab", "q": "Online shopping has gained great ______ among teenagers because it is fast and convenient.", "options": ["popularity", "possibility", "personality", "publicity"], "answer": 0, "explain": "句意：網路購物因為快速又方便，在青少年之間大受歡迎。gain popularity among 在……之間受歡迎。(B) possibility 可能性 (C) personality 個性 (D) publicity 宣傳、媒體關注，皆不符「因方便而受青睞」的語意。故選 (A)。", "level": "B2", "topic": "online shopping"}, {"id": "M046", "type": "vocab", "q": "We need to ______ a table at the restaurant because it's always full on Friday nights.", "options": ["order", "serve", "reserve", "prepare"], "answer": 2, "explain": "句意：我們需要先訂位，因為那家餐廳週五晚上總是客滿。reserve a table 預約餐桌、訂位。(A) order 點（餐）(B) serve 供應 (D) prepare 準備，皆不能與 a table 搭配表示訂位。故選 (C)。", "level": "B1", "topic": "restaurant booking"}, {"id": "M047", "type": "vocab", "q": "The final exam was ______ difficult; most students couldn't finish it in time.", "options": ["hardly", "extremely", "slightly", "rarely"], "answer": 1, "explain": "句意：期末考非常難，大部分學生都無法及時寫完。extremely 極度地。(A) hardly 幾乎不 (C) slightly 稍微 (D) rarely 很少，皆與「大部分學生寫不完」矛盾。故選 (B)。", "level": "B1", "topic": "exams"}, {"id": "M048", "type": "vocab", "q": "The weather in the mountains is ______; it can be sunny one minute and rainy the next.", "options": ["constant", "reliable", "steady", "unpredictable"], "answer": 3, "explain": "句意：山上的天氣難以預測，可能這一分鐘是晴天，下一分鐘就下雨。unpredictable 無法預測的。(A) constant 不變的 (B) reliable 可靠的 (C) steady 穩定的，皆與「變化快速」相反。故選 (D)。", "level": "B2", "topic": "mountain weather"}, {"id": "M049", "type": "vocab", "q": "I have an ______ with the dentist at 3 p.m., so I need to leave school early today.", "options": ["appointment", "agreement", "assignment", "environment"], "answer": 0, "explain": "句意：我下午三點跟牙醫有約診，所以今天要提早離開學校。have an appointment with sb 與某人有約（看診、會面）。(B) agreement 協議 (C) assignment 作業、任務 (D) environment 環境，皆不符語意。故選 (A)。", "level": "B1", "topic": "appointments"}, {"id": "M050", "type": "vocab", "q": "This medicine can ______ your headache quickly, but it may make you feel sleepy.", "options": ["increase", "release", "relieve", "receive"], "answer": 2, "explain": "句意：這種藥能迅速緩解頭痛，但可能會讓你想睡。relieve 減輕、緩解（疼痛）。(A) increase 增加，與藥效相反 (B) release 釋放 (D) receive 收到，皆為字形相近的干擾選項。故選 (C)。", "level": "B2", "topic": "medicine"}, {"id": "M051", "type": "vocab", "q": "Before boarding an international flight, all passengers must show their ______ and boarding pass at the gate.", "options": ["receipt", "brochure", "passport", "coupon"], "answer": 2, "explain": "句意：搭乘國際航班登機前，所有乘客都必須在登機門出示______和登機證。(A) receipt 收據 (B) brochure 小冊子 (C) passport 護照 (D) coupon 優惠券。搭國際線須出示「護照」與登機證，passport 符合語意；receipt、brochure、coupon 都不是登機時查驗的證件。故選 (C)。", "level": "B1", "topic": "travel"}, {"id": "M052", "type": "vocab", "q": "Mr. Lin asked the students to ______ their essays before Friday so that he could grade them over the weekend.", "options": ["submit", "admit", "permit", "commit"], "answer": 0, "explain": "句意：林老師要學生在星期五前______作文，好讓他週末批改。(A) submit 繳交、提交 (B) admit 承認；准許進入 (C) permit 允許 (D) commit 犯（錯、罪）；承諾。submit an essay 指「繳交作文」，符合老師要批改的語境；其餘三字雖同為 -mit 結尾，意思都不合。故選 (A)。", "level": "B2", "topic": "school"}, {"id": "M053", "type": "vocab", "q": "It was so ______ on the highway this morning that drivers had to slow down and turn on their lights because they could not see far ahead.", "options": ["sunny", "chilly", "windy", "foggy"], "answer": 3, "explain": "句意：今天早上高速公路上______到駕駛人必須減速並打開車燈，因為他們看不清前方。(A) sunny 晴朗的 (B) chilly 寒冷的 (C) windy 風大的 (D) foggy 有霧的。「看不清前方、要開燈」表示能見度很低，只有 foggy（起霧）會造成這種情況；晴朗、寒冷或風大的天氣都不會讓人看不見前方。故選 (D)。", "level": "B1", "topic": "weather"}, {"id": "M054", "type": "vocab", "q": "After working at the company for ten years, Ms. Chen finally got a ______ to sales manager.", "options": ["pension", "promotion", "permission", "profession"], "answer": 1, "explain": "句意：在公司工作十年後，陳小姐終於獲得______，成為業務經理。(A) pension 退休金 (B) promotion 升遷 (C) permission 許可 (D) profession 職業。get a promotion to + 職位 表「升為某職位」；pension 是退休後領的錢，permission、profession 都無法接 to sales manager 表示升職。故選 (B)。", "level": "B1", "topic": "workplace"}, {"id": "M055", "type": "vocab", "q": "Eating too much sugar is ______ to your teeth, so try to cut down on sweets and soft drinks.", "options": ["harmful", "grateful", "faithful", "peaceful"], "answer": 0, "explain": "句意：吃太多糖對牙齒______，所以要試著少吃甜食、少喝汽水。(A) harmful 有害的 (B) grateful 感激的 (C) faithful 忠實的 (D) peaceful 和平的。be harmful to 表「對……有害」，符合要少吃甜食的建議；grateful、faithful、peaceful 皆與健康無關，語意不通。故選 (A)。", "level": "B1", "topic": "health"}, {"id": "M056", "type": "vocab", "q": "Factories that ______ waste into rivers will have to pay heavy fines, since this seriously harms the fish and the water we drink.", "options": ["donate", "inspire", "dump", "attract"], "answer": 2, "explain": "句意：將廢棄物______到河川裡的工廠將被處以高額罰款，因為這會嚴重傷害魚類和我們的飲用水。(A) donate 捐贈 (B) inspire 啟發 (C) dump 傾倒、丟棄 (D) attract 吸引。dump waste into rivers 表「把廢棄物倒入河川」，正是會被罰款的污染行為；捐贈、啟發、吸引廢棄物到河裡都不合語意，也不會因此被罰。故選 (C)。", "level": "B2", "topic": "environment"}, {"id": "M057", "type": "vocab", "q": "The baby was sleeping, so Kevin closed the door ______ to avoid waking her up.", "options": ["loudly", "rapidly", "angrily", "quietly"], "answer": 3, "explain": "句意：寶寶正在睡覺，所以 Kevin ______關上門，以免吵醒她。(A) loudly 大聲地 (B) rapidly 快速地 (C) angrily 生氣地 (D) quietly 安靜地、輕聲地。為了不吵醒寶寶，應「輕輕地、安靜地」關門；大聲、快速、生氣地關門反而容易吵醒她。故選 (D)。", "level": "B1", "topic": "family"}, {"id": "M058", "type": "vocab", "q": "If you are not satisfied with the product, you can return it within seven days and get a full ______.", "options": ["reward", "refund", "record", "report"], "answer": 1, "explain": "句意：如果您對產品不滿意，可以在七天內退貨並獲得全額______。(A) reward 報酬、獎賞 (B) refund 退款 (C) record 紀錄 (D) report 報告。get a full refund 是「獲得全額退款」的固定搭配，與退貨語境相符；reward 是因表現好而得到的獎賞，record、report 與退貨無關。故選 (B)。", "level": "B2", "topic": "shopping"}, {"id": "M059", "type": "vocab", "q": "Many students use apps on their phones to ______ new English words while they are waiting for the bus.", "options": ["criticize", "apologize", "memorize", "realize"], "answer": 2, "explain": "句意：許多學生在等公車時，用手機上的應用程式來______新的英文單字。(A) criticize 批評 (B) apologize 道歉 (C) memorize 記住、背誦 (D) realize 了解；實現。memorize new words 表「背單字」，符合語意；批評單字、realize 單字皆不合理，apologize 為不及物動詞，也不能直接接受詞。故選 (C)。", "level": "B1", "topic": "technology"}, {"id": "M060", "type": "vocab", "q": "The job requires someone who is ______ in both English and Japanese, since the company deals with clients from both countries.", "options": ["fluent", "fragile", "frequent", "furious"], "answer": 0, "explain": "句意：這份工作需要英語和日語都______的人，因為公司要和這兩個國家的客戶往來。(A) fluent 流利的 (B) fragile 易碎的 (C) frequent 頻繁的 (D) furious 狂怒的。be fluent in + 語言 表「某語言很流利」；fragile 形容物品易碎，frequent 指次數頻繁，furious 指非常生氣，都無法形容語言能力。故選 (A)。", "level": "B2", "topic": "workplace"}, {"id": "M061", "type": "vocab", "q": "The school nurse took my ______ and told me that I had a slight fever, so I should go home and rest.", "options": ["attitude", "temperature", "signature", "furniture"], "answer": 1, "explain": "句意：學校護理師幫我量了______，告訴我有點發燒，要我回家休息。(A) attitude 態度 (B) temperature 體溫、溫度 (C) signature 簽名 (D) furniture 家具。take one's temperature 表「量某人的體溫」，量完才知道「有點發燒」；attitude、signature、furniture 雖然字尾相似，但都無法「量」出是否發燒。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M062", "type": "vocab", "q": "Scientists are trying to ______ a vaccine that can protect people from the new virus.", "options": ["describe", "destroy", "deserve", "develop"], "answer": 3, "explain": "句意：科學家正努力______一種能保護人們免受新病毒感染的疫苗。(A) describe 描述 (B) destroy 摧毀 (C) deserve 應得 (D) develop 研發、發展。develop a vaccine 表「研發疫苗」；描述或摧毀疫苗與「保護人們」的目的不符，deserve 意思也不通。故選 (D)。", "level": "B1", "topic": "science"}, {"id": "M063", "type": "vocab", "q": "A passerby called an ambulance and stayed with the ______ of the car accident until help arrived.", "options": ["victims", "critics", "rivals", "hosts"], "answer": 0, "explain": "句意：一位路人叫了救護車，並陪著這場車禍的______直到救援抵達。(A) victims 受害者、傷者 (B) critics 批評者 (C) rivals 對手 (D) hosts 主人；主持人。the victims of the accident 表「事故的受害者」，需要救護車的正是車禍中受傷的人；批評者、對手、主人都不是車禍中需要救助的對象。故選 (A)。", "level": "B2", "topic": "accident"}, {"id": "M064", "type": "vocab", "q": "David is very ______; he always does his share of the work in group projects and never forgets his duties.", "options": ["talkative", "cheerful", "responsible", "humorous"], "answer": 2, "explain": "句意：David 非常______，他在小組作業中總是做好自己分內的工作，也從不忘記自己的職責。(A) talkative 健談的 (B) cheerful 開朗的 (C) responsible 負責任的 (D) humorous 幽默的。做好分內工作、不忘職責是「負責任」的表現；健談、開朗、幽默描述的是個性或說話方式，無法說明分號後的行為。故選 (C)。", "level": "B1", "topic": "personality"}, {"id": "M065", "type": "vocab", "q": "Our flight was ______ for three hours because of the heavy storm, so we had to wait at the airport.", "options": ["invited", "delayed", "rescued", "allowed"], "answer": 1, "explain": "句意：因為強烈暴風雨，我們的班機______了三個小時，只好在機場等候。(A) invited 邀請 (B) delayed 延誤 (C) rescued 救援 (D) allowed 允許。be delayed for three hours 表「延誤三小時」，與「在機場等候」相符；班機被邀請、被救援、被允許三小時都不合邏輯。故選 (B)。", "level": "B1", "topic": "travel"}, {"id": "M066", "type": "vocab", "q": "The new smartphone was so popular that the company could not keep up with the ______; stores ran out of it within hours.", "options": ["supply", "budget", "status", "demand"], "answer": 3, "explain": "句意：這款新手機非常熱門，公司根本趕不上______，商店在幾小時內就賣光了。(A) supply 供應 (B) budget 預算 (C) status 地位 (D) demand 需求。keep up with demand 表「跟上需求、滿足需求」；產品熱賣代表市場「需求」大，公司本身就是供應的一方，所以不是 supply；budget、status 與賣光無關。故選 (D)。", "level": "B2", "topic": "business"}, {"id": "M067", "type": "vocab", "q": "Tom ______ dropped his phone into the swimming pool while he was taking a selfie.", "options": ["proudly", "honestly", "accidentally", "patiently"], "answer": 2, "explain": "句意：Tom 在自拍時______把手機掉進了游泳池。(A) proudly 驕傲地 (B) honestly 誠實地 (C) accidentally 意外地、不小心地 (D) patiently 耐心地。手機掉進泳池是「不小心」造成的，accidentally 最合理；驕傲地、誠實地、耐心地把手機掉進水裡都不合常理。故選 (C)。", "level": "B1", "topic": "daily life"}, {"id": "M068", "type": "vocab", "q": "To ______ cheating, teachers make sure that all students' phones are turned off and put in their bags before the exam begins.", "options": ["prevent", "promote", "predict", "permit"], "answer": 0, "explain": "句意：為了______作弊，老師在考試開始前會確認所有學生的手機都已關機並收進書包。(A) prevent 預防、防止 (B) promote 促進；升遷 (C) predict 預測 (D) permit 允許。收走手機是為了「防止」作弊，prevent cheating 合理；promote、permit 意思與目的相反，predict 作弊也不合邏輯。故選 (A)。", "level": "B2", "topic": "school"}, {"id": "M069", "type": "vocab", "q": "This milk smells ______; it must have been left out of the fridge for too long.", "options": ["fresh", "spicy", "crispy", "sour"], "answer": 3, "explain": "句意：這瓶牛奶聞起來______，一定是放在冰箱外太久了。(A) fresh 新鮮的 (B) spicy 辣的 (C) crispy 酥脆的 (D) sour 酸的。牛奶放在室溫太久會變質發酸，smell sour 合理；fresh 與「放太久」矛盾，spicy、crispy 不適合形容牛奶的氣味。故選 (D)。", "level": "B1", "topic": "food"}, {"id": "M070", "type": "vocab", "q": "Going to bed late every night has become a bad ______ for many students, and it affects their health.", "options": ["hobby", "habit", "chance", "gift"], "answer": 1, "explain": "句意：每天晚睡已成為許多學生的壞______，而且影響了他們的健康。(A) hobby 嗜好 (B) habit 習慣 (C) chance 機會 (D) gift 禮物；天賦。a bad habit 表「壞習慣」，每天晚睡是日常養成的行為；hobby 指休閒時喜愛從事的活動，不是作息習慣；chance、gift 語意不通。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M071", "type": "vocab", "q": "The hotel guest decided to ______ to the manager because his room was dirty and the air conditioner did not work.", "options": ["complain", "compete", "concern", "consist"], "answer": 0, "explain": "句意：這位飯店房客決定向經理______，因為他的房間很髒，冷氣也壞了。(A) complain 抱怨、投訴 (B) compete 競爭 (C) concern 使擔心；與……有關 (D) consist 組成。complain to sb. 表「向某人投訴」，符合房間髒亂的情境；compete、concern 與投訴無關，consist 須接 of 表示「由……組成」。故選 (A)。", "level": "B1", "topic": "customer service"}, {"id": "M072", "type": "vocab", "q": "This laptop is light and ______, so you can easily carry it around in your backpack.", "options": ["visible", "audible", "portable", "edible"], "answer": 2, "explain": "句意：這台筆電又輕又______，所以你可以輕鬆地把它放在背包裡帶著走。(A) visible 看得見的 (B) audible 聽得見的 (C) portable 可攜帶的、輕便的 (D) edible 可食用的。portable 由 port（攜帶）+ -able 組成，表「便於攜帶的」，與「放背包帶著走」相符；其餘三字皆與攜帶無關。故選 (C)。", "level": "B2", "topic": "technology"}, {"id": "M073", "type": "vocab", "q": "Air ______ in the city has become worse because of the growing number of cars and factories.", "options": ["population", "pollution", "position", "portion"], "answer": 1, "explain": "句意：由於汽車和工廠的數量不斷增加，市區的空氣______變得更嚴重了。(A) population 人口 (B) pollution 污染 (C) position 位置 (D) portion 部分。air pollution 表「空氣污染」，與汽車、工廠增加的原因相符；population 字形相近但意思是人口，position、portion 也無法與 air 搭配。故選 (B)。", "level": "B1", "topic": "environment"}, {"id": "M074", "type": "vocab", "q": "When you ride a scooter, you must ______ a helmet to protect your head.", "options": ["dress", "put", "carry", "wear"], "answer": 3, "explain": "句意：騎機車時，你必須______安全帽來保護頭部。(A) dress 給……穿衣 (B) put 放置 (C) carry 攜帶 (D) wear 穿戴。wear a helmet 表「戴著安全帽」的狀態；dress 的受詞是人（dress the baby），不能接 helmet；put 須用 put on 才表示「戴上」；只是 carry（攜帶）安全帽無法保護頭部。故選 (D)。", "level": "B1", "topic": "safety"}, {"id": "M075", "type": "vocab", "q": "Before the job interview, Amy did some research on the company and practiced answering common questions. Her careful ______ helped her get the job.", "options": ["preparation", "imagination", "invitation", "population"], "answer": 0, "explain": "句意：面試前，Amy 研究了這家公司並練習回答常見問題，她細心的______幫助她得到了這份工作。(A) preparation 準備 (B) imagination 想像力 (C) invitation 邀請 (D) population 人口。研究公司、練習回答問題都屬於面試前的「準備」，careful preparation 表「細心的準備」；imagination、invitation、population 都與前文描述的行為不符。故選 (A)。", "level": "B2", "topic": "career"}, {"id": "M076", "type": "vocab", "q": "Vegetable prices have risen ______ since the typhoon hit; some have even doubled.", "options": ["slightly", "barely", "sharply", "rarely"], "answer": 2, "explain": "句意：颱風過後，蔬菜價格______上漲，有些甚至翻了一倍。(A) slightly 稍微地 (B) barely 幾乎沒有 (C) sharply 急遽地、大幅地 (D) rarely 很少。價格「翻倍」表示漲幅很大，rise sharply 表「急遽上升」；slightly 與翻倍矛盾，barely、rarely 也不能形容大幅上漲。故選 (C)。", "level": "B2", "topic": "economy"}, {"id": "M077", "type": "vocab", "q": "Although Ben is very ______ and rarely talks in class, he is quite friendly once you get to know him.", "options": ["generous", "honest", "brave", "shy"], "answer": 3, "explain": "句意：雖然 Ben 很______，在課堂上很少說話，但只要你跟他熟了，就會發現他相當友善。(A) generous 慷慨的 (B) honest 誠實的 (C) brave 勇敢的 (D) shy 害羞的。由 although 可知前後語意相對，「很少說話」對比「熟了之後很友善」，shy 最合理；慷慨、誠實、勇敢都與「很少說話」無關。故選 (D)。", "level": "B1", "topic": "personality"}, {"id": "M078", "type": "vocab", "q": "The two companies agreed to ______ on a new project to build electric scooters.", "options": ["compete", "cooperate", "complain", "consume"], "answer": 1, "explain": "句意：這兩家公司同意在一項製造電動機車的新計畫上______。(A) compete 競爭 (B) cooperate 合作 (C) complain 抱怨 (D) consume 消耗。cooperate on a project 表「在計畫上合作」，兩家公司「同意」一起進行新計畫，應為合作；同意互相競爭、抱怨或消耗都不合邏輯。故選 (B)。", "level": "B2", "topic": "business"}, {"id": "M079", "type": "vocab", "q": "The tour ______ explained the history of the old temple to our group in both Chinese and English.", "options": ["guide", "judge", "pilot", "clerk"], "answer": 0, "explain": "句意：這位 tour ______ 用中文和英文向我們這團解說這座古廟的歷史。(A) guide 嚮導、導遊 (B) judge 法官；裁判 (C) pilot 飛行員 (D) clerk 店員、職員。tour guide 表「導遊」，負責帶團並解說景點；judge、pilot、clerk 都不是帶團解說古蹟的人，也不能與 tour 搭配。故選 (A)。", "level": "B1", "topic": "travel"}, {"id": "M080", "type": "vocab", "q": "I forgot to ______ my alarm clock last night, so I woke up late and missed the school bus.", "options": ["raise", "ring", "set", "hold"], "answer": 2, "explain": "句意：我昨晚忘了______鬧鐘，所以睡過頭，錯過了校車。(A) raise 舉起；養育 (B) ring （鈴）響；打電話 (C) set 設定 (D) hold 握住。set an alarm (clock) 表「設定鬧鐘」，忘了設定才會睡過頭；ring 指鈴聲響起，是鬧鐘自己響，不是人睡前要做的動作；raise、hold 鬧鐘也無法說明為何睡過頭。故選 (C)。", "level": "B1", "topic": "daily life"}, {"id": "M081", "type": "vocab", "q": "Glass is ______, so light can pass through it easily and we can see what is on the other side.", "options": ["flexible", "transparent", "magnetic", "poisonous"], "answer": 1, "explain": "句意：玻璃是______的，所以光線能輕易穿過，我們也能看見另一邊的東西。(A) flexible 有彈性的、可彎曲的 (B) transparent 透明的 (C) magnetic 有磁性的 (D) poisonous 有毒的。光線能穿過、看得見另一邊，正是「透明」的特性；flexible、magnetic、poisonous 都與「光線能穿過、看得見另一邊」沒有因果關係。故選 (B)。", "level": "B2", "topic": "science"}, {"id": "M082", "type": "vocab", "q": "Because sales had been excellent, the company gave each employee a ______ of NT$20,000 at the end of the year.", "options": ["bonus", "fine", "loan", "tax"], "answer": 0, "explain": "句意：由於業績非常好，公司在年底發給每位員工兩萬元的______。(A) bonus 獎金、紅利 (B) fine 罰款 (C) loan 貸款 (D) tax 稅。因業績好而在年底發給員工的錢是「年終獎金」（year-end bonus）；fine 是罰款，loan 需要歸還，tax 是繳給政府的錢，皆不合語意。故選 (A)。", "level": "B1", "topic": "workplace"}, {"id": "M083", "type": "vocab", "q": "It took Mark two months to fully ______ from his knee injury before he could play basketball again.", "options": ["remove", "retire", "reduce", "recover"], "answer": 3, "explain": "句意：Mark 花了兩個月才從膝傷中完全______，之後才能再打籃球。(A) remove 移除 (B) retire 退休 (C) reduce 減少 (D) recover 康復。recover from an injury 表「從傷勢中康復」；remove、reduce 為及物動詞且語意不符；retire from 是「從……退休」，與傷癒後重返球場的語意矛盾。故選 (D)。", "level": "B2", "topic": "sports"}, {"id": "M084", "type": "vocab", "q": "Please turn off your cell phone during the ______; it's rude to let it ring while the actors are on stage.", "options": ["receipt", "harvest", "performance", "departure"], "answer": 2, "explain": "句意：______進行中請關閉手機；演員在台上時讓手機響是很不禮貌的。(A) receipt 收據 (B) harvest 收成 (C) performance 演出、表演 (D) departure 出發、離開。由「演員在台上」可知是在看「表演」，during the performance 合理；收據、收成、出發都與演員演出無關。故選 (C)。", "level": "B1", "topic": "entertainment"}, {"id": "M085", "type": "vocab", "q": "Lucy ______ her mother; they both have big eyes and curly hair.", "options": ["takes", "resembles", "raises", "respects"], "answer": 1, "explain": "句意：Lucy ______她的母親，她們都有大眼睛和捲髮。(A) takes 拿 (B) resembles 長得像 (C) raises 撫養；舉起 (D) respects 尊敬。resemble sb. 表「與某人相像」，後句「都有大眼睛和捲髮」正是外表相似的說明；take 須用 take after 才表示「像（父母）」，raise、respect 都不能解釋兩人外貌相同。故選 (B)。", "level": "B2", "topic": "family"}, {"id": "M086", "type": "vocab", "q": "These shoes are too ______ for me. Do you have them in a bigger size?", "options": ["tight", "loose", "cheap", "light"], "answer": 0, "explain": "句意：這雙鞋對我來說太______了，有大一點的尺寸嗎？(A) tight 緊的 (B) loose 鬆的 (C) cheap 便宜的 (D) light 輕的。想換「大一點的尺寸」，表示鞋子太緊；loose 意思相反（太鬆應換小一號），cheap、light 都不是換大尺寸的理由。故選 (A)。", "level": "B1", "topic": "shopping"}, {"id": "M087", "type": "vocab", "q": "According to a recent ______, more than 70 percent of teenagers in Taiwan spend over three hours a day on their phones.", "options": ["rumor", "tradition", "ceremony", "survey"], "answer": 3, "explain": "句意：根據最近的一項______，台灣超過百分之七十的青少年每天花三小時以上在手機上。(A) rumor 謠言 (B) tradition 傳統 (C) ceremony 典禮 (D) survey 調查。according to a survey 表「根據調查」，後面接統計數據合理；謠言不能作為數據來源，tradition、ceremony 與統計結果無關。故選 (D)。", "level": "B2", "topic": "society"}, {"id": "M088", "type": "vocab", "q": "We should ______ paper, glass, and plastic bottles instead of throwing them away with the general trash.", "options": ["replace", "repeat", "recycle", "refuse"], "answer": 2, "explain": "句意：我們應該______紙類、玻璃和塑膠瓶，而不是把它們和一般垃圾一起丟掉。(A) replace 取代 (B) repeat 重複 (C) recycle 回收 (D) refuse 拒絕。由「而不是和一般垃圾一起丟掉」可知應做資源「回收」；replace、repeat、refuse 皆不合語意。故選 (C)。", "level": "B1", "topic": "environment"}, {"id": "M089", "type": "vocab", "q": "The fire spread so ______ that the firefighters could not stop it from reaching the nearby buildings.", "options": ["rapidly", "politely", "properly", "slightly"], "answer": 0, "explain": "句意：火勢蔓延得非常______，消防員無法阻止它延燒到附近的建築物。(A) rapidly 快速地 (B) politely 有禮貌地 (C) properly 適當地 (D) slightly 稍微地。so...that 表結果：火勢蔓延「快」到無法阻止，spread rapidly 合理；politely 不能形容火，properly、slightly 也無法說明消防員為何擋不住。故選 (A)。", "level": "B2", "topic": "news"}, {"id": "M090", "type": "vocab", "q": "Thanks to the ______ of many local businesses, the community was able to build a new playground for the children.", "options": ["complaints", "donations", "competitions", "inventions"], "answer": 1, "explain": "句意：多虧許多在地商家的______，社區才得以為孩子們蓋一座新的遊樂場。(A) complaints 抱怨、投訴 (B) donations 捐款、捐贈 (C) competitions 比賽、競爭 (D) inventions 發明。thanks to 表「多虧、由於」，社區能蓋遊樂場是因為商家「捐款」；抱怨、比賽、發明都無法提供蓋遊樂場所需的資金。故選 (B)。", "level": "B2", "topic": "community"}, {"id": "M091", "type": "vocab", "q": "The museum is ______ to the public every day except Monday, from 9 a.m. to 5 p.m.", "options": ["equal", "similar", "open", "familiar"], "answer": 2, "explain": "句意：這間博物館除了星期一以外，每天上午九點到下午五點對大眾______。(A) equal 相等的 (B) similar 相似的 (C) open 開放的 (D) familiar 熟悉的。be open to the public 表「對大眾開放」，後面接開放時間合理；equal to、similar to、familiar to 雖也都接 to，但都無法搭配開放時間。故選 (C)。", "level": "B1", "topic": "travel"}, {"id": "M092", "type": "vocab", "q": "Our company plans to ______ twenty new employees next year to help with the growing business.", "options": ["fire", "quit", "retire", "hire"], "answer": 3, "explain": "句意：我們公司計畫明年______二十名新員工，以因應日益成長的業務。(A) fire 開除 (B) quit 辭職 (C) retire 退休 (D) hire 雇用。業務成長需要更多人手，hire new employees 表「雇用新員工」；fire 意思相反（且不會開除「新」員工來幫忙業務），quit、retire 是離職、退休，與「因應業務成長而增加人手」的語意不合。故選 (D)。", "level": "B1", "topic": "workplace"}, {"id": "M093", "type": "vocab", "q": "Many volunteers spend their weekends at the animal ______, feeding and walking dogs that have no homes.", "options": ["shelter", "factory", "harbor", "studio"], "answer": 0, "explain": "句意：許多志工利用週末到動物______幫忙，餵食並帶無家可歸的狗散步。(A) shelter 收容所、庇護所 (B) factory 工廠 (C) harbor 港口 (D) studio 工作室。animal shelter 表「動物收容所」，收容流浪動物；factory、harbor、studio 都不是照顧無家可歸狗兒的地方。故選 (A)。", "level": "B2", "topic": "volunteering"}, {"id": "M094", "type": "vocab", "q": "Dinosaurs became ______ about 66 million years ago, possibly because a huge asteroid hit the Earth.", "options": ["ancient", "extinct", "evident", "efficient"], "answer": 1, "explain": "句意：恐龍大約在六千六百萬年前______，可能是因為一顆巨大的小行星撞擊地球。(A) ancient 古老的 (B) extinct 滅絕的 (C) evident 明顯的 (D) efficient 有效率的。become extinct 表「滅絕」，與小行星撞擊的原因相符；ancient 雖與年代久遠有關，但 become ancient 不能表示物種消失；evident、efficient 語意不通。故選 (B)。", "level": "B2", "topic": "science"}, {"id": "M095", "type": "vocab", "q": "The teacher asked us to ______ the two poems and find out how they are similar and how they are different.", "options": ["arrange", "invent", "compare", "repair"], "answer": 2, "explain": "句意：老師要我們______這兩首詩，找出它們有哪些相同和不同之處。(A) arrange 安排 (B) invent 發明 (C) compare 比較 (D) repair 修理。找出相同與相異之處就是「比較」，compare 符合語意；安排、發明、修理這兩首詩都不合理。故選 (C)。", "level": "B1", "topic": "school"}, {"id": "M096", "type": "vocab", "q": "Our ______ to Japan included visits to Tokyo, Kyoto, and Osaka, and we enjoyed every part of it.", "options": ["luggage", "currency", "souvenir", "journey"], "answer": 3, "explain": "句意：我們的日本______包括參訪東京、京都和大阪，而且我們很享受其中的每一段。(A) luggage 行李 (B) currency 貨幣 (C) souvenir 紀念品 (D) journey 旅程。能「包括參訪三個城市」的是「旅程」，journey to Japan 合理；行李、貨幣、紀念品都不能包含參訪行程。故選 (D)。", "level": "B1", "topic": "travel"}, {"id": "M097", "type": "vocab", "q": "Many college students shop at this store because its prices are ______; most items cost less than NT$100.", "options": ["affordable", "remarkable", "comfortable", "available"], "answer": 0, "explain": "句意：許多大學生在這家店購物，因為它的價格很______，大部分商品不到一百元。(A) affordable 負擔得起的、平價的 (B) remarkable 非凡的 (C) comfortable 舒適的 (D) available 可取得的。商品多不到一百元，表示價格「平價、負擔得起」，affordable prices 合理；remarkable、comfortable 不能形容便宜的價格，available 指可買到、可取得，與便宜無關。故選 (A)。", "level": "B2", "topic": "shopping"}, {"id": "M098", "type": "vocab", "q": "If your headache doesn't go away, you should see a doctor and get a ______ for stronger medicine.", "options": ["recipe", "receipt", "prescription", "reception"], "answer": 2, "explain": "句意：如果你的頭痛一直沒好，應該去看醫生並取得______，才能拿到較強效的藥。(A) recipe 食譜 (B) receipt 收據 (C) prescription 處方箋 (D) reception 接待處；歡迎會。醫生開立、讓病人領取藥物的是「處方箋」，a prescription for medicine 為常見搭配；recipe、receipt、reception 拼字相近但意思皆不符。故選 (C)。", "level": "B2", "topic": "health"}, {"id": "M099", "type": "vocab", "q": "Our school basketball team practiced hard every day and finally ______ the championship.", "options": ["beat", "won", "gained", "lost"], "answer": 1, "explain": "句意：我們學校的籃球隊每天努力練習，終於______了冠軍。(A) beat 打敗 (B) won 贏得 (C) gained 獲得 (D) lost 輸掉。win the championship 表「贏得冠軍」；beat 的受詞應為對手（如 beat the other team），gain 多接經驗、體重等，不與 championship 搭配；lost 與「努力練習、終於」的語意矛盾。故選 (B)。", "level": "B1", "topic": "sports"}, {"id": "M100", "type": "vocab", "q": "The new employee was ______ about her first day at work, so she arrived thirty minutes early.", "options": ["ashamed", "bored", "disappointed", "anxious"], "answer": 3, "explain": "句意：這位新員工對上班第一天感到很______，所以提早三十分鐘到。(A) ashamed 羞愧的 (B) bored 無聊的 (C) disappointed 失望的 (D) anxious 焦慮的、擔心的。be anxious about 表「對……感到焦慮、擔心」，因為擔心才會提早到；第一天還沒開始上班，談不上羞愧、無聊或失望。故選 (D)。", "level": "B2", "topic": "workplace"}, {"id": "M101", "type": "grammar", "q": "My cousin ______ in Kaohsiung since she was ten years old.", "options": ["has lived", "lives", "is living", "lived"], "answer": 0, "explain": "句意：我表姊從十歲起就住在高雄。since + 過去時間點（she was ten）表示從過去持續到現在的狀態，主要子句須用現在完成式 has lived。(B) lives 為現在簡單式、(C) is living 為現在進行式，都不能搭配 since 表持續；(D) lived 為過去式，表示已結束，與 since 不合。故選 (A)。", "level": "B1", "topic": "present perfect"}, {"id": "M102", "type": "grammar", "q": "When we arrived at the theater, the movie ______, so we missed the opening scene.", "options": ["has already started", "already starts", "had already started", "will already start"], "answer": 2, "explain": "句意：我們到達戲院時，電影已經開始了，所以錯過了開場。「電影開始」發生在「我們到達（過去）」之前，屬於「過去的過去」，用過去完成式 had already started。(A) 現在完成式不能與過去時間 arrived 搭配；(B) 現在式時態不符；(D) 未來式與句意不合。故選 (C)。", "level": "B2", "topic": "past perfect"}, {"id": "M103", "type": "grammar", "q": "The new library ______ by more than 5,000 students since it opened last year.", "options": ["has visited", "has been visited", "was visited", "is visiting"], "answer": 1, "explain": "句意：新圖書館自去年開館以來，已有超過五千名學生造訪。since 表示持續到現在，須用現在完成式；圖書館是「被」學生造訪，且後有 by，故用被動 has been visited。(A) has visited 為主動，語意變成圖書館去拜訪學生；(C) was visited 為過去式，不能搭配 since；(D) is visiting 為主動進行式，時態與語態皆錯。故選 (B)。", "level": "B1", "topic": "passive voice"}, {"id": "M104", "type": "grammar", "q": "I have a classmate ______ father is a famous chef in Tainan.", "options": ["who", "which", "whom", "whose"], "answer": 3, "explain": "句意：我有一位同學，他的父親是台南的知名主廚。空格後直接接名詞 father，表示「同學的父親」，須用所有格關係代名詞 whose。(A) who 與 (C) whom 後面不可直接接名詞表所屬；(B) which 指事物，也不表所有格。故選 (D)。", "level": "B1", "topic": "relative pronoun whose"}, {"id": "M105", "type": "grammar", "q": "This is the small village ______ my grandparents grew up.", "options": ["which", "what", "where", "when"], "answer": 2, "explain": "句意：這就是我祖父母長大的小村莊。先行詞 village 為地點，且關係子句 my grandparents grew up 結構完整（grow up 為不及物動詞），須用關係副詞 where（= in which）。(A) which 須在子句中當主詞或受詞，或寫成 in which；(B) what 前面不可有先行詞；(D) when 用於表時間的先行詞。故選 (C)。", "level": "B1", "topic": "relative adverb where"}, {"id": "M106", "type": "grammar", "q": "______ his homework, Kevin went out to play basketball with his friends.", "options": ["Having finished", "Finished", "To finish", "Being finished"], "answer": 0, "explain": "句意：寫完功課後，Kevin 出去和朋友打籃球。主詞 Kevin 主動「完成」功課，且此動作發生在「出去打球」之前，用完成式分詞構句 Having finished（= After he had finished）。(B) Finished 為過去分詞，表被動，語意變成 Kevin 被完成；(C) To finish 表目的「為了完成功課」，與出去打球矛盾；(D) Being finished 也是被動。故選 (A)。", "level": "B2", "topic": "participle clause"}, {"id": "M107", "type": "grammar", "q": "All the students are looking forward to ______ the science museum next Friday.", "options": ["visit", "visited", "be visiting", "visiting"], "answer": 3, "explain": "句意：所有學生都很期待下週五參觀科學博物館。look forward to「期待」中的 to 是介系詞，後面須接名詞或動名詞，故用 visiting。(A) visit 為原形動詞；(B) visited 為過去式／過去分詞；(C) be visiting 不能接在介系詞之後。故選 (D)。", "level": "B1", "topic": "gerund after preposition"}, {"id": "M108", "type": "grammar", "q": "I clearly remember ______ the door before I left, but now it is open. Someone must have opened it.", "options": ["to lock", "locking", "lock", "to have been locked"], "answer": 1, "explain": "句意：我清楚記得出門前有鎖門，但現在門卻開著，一定有人打開過。remember + V-ing 表示「記得做過某事」（已發生）；remember + to V 表示「記得要去做某事」（尚未做）。本句指已鎖過門，故用 locking。(A) to lock 表「記得要去鎖」，與句意不符；(C) lock 原形不能直接接在 remember 後；(D) 為被動，主詞 I 不是被鎖的對象。故選 (B)。", "level": "B2", "topic": "gerund vs infinitive"}, {"id": "M109", "type": "grammar", "q": "______ it was raining heavily, the baseball game was not canceled.", "options": ["Although", "Despite", "Because", "In spite of"], "answer": 0, "explain": "句意：雖然雨下得很大，棒球比賽並沒有取消。空格後接完整子句 it was raining heavily，且前後語意相反，須用讓步連接詞 Although。(B) Despite 與 (D) In spite of 為介系詞（片語），後面要接名詞或動名詞，不能接子句；(C) Because 表原因，語意不合。故選 (A)。", "level": "B1", "topic": "although vs despite"}, {"id": "M110", "type": "grammar", "q": "You won't be allowed to take the exam ______ you bring your student ID card.", "options": ["if", "because", "unless", "so that"], "answer": 2, "explain": "句意：除非你帶學生證，否則不能參加考試。unless「除非」= if...not。(A) if 語意變成「如果帶了學生證就不能考試」，不合理；(B) because「因為帶了學生證所以不能考」，不合理；(D) so that 表目的「以便」，語意不合。故選 (C)。", "level": "B1", "topic": "conjunction unless"}, {"id": "M111", "type": "grammar", "q": "Nobody knows ______ the typhoon will hit Taiwan or turn north.", "options": ["that", "what", "which", "whether"], "answer": 3, "explain": "句意：沒有人知道颱風會侵襲台灣還是轉向北方。名詞子句表「是否」，且後面有 or 搭配，用 whether...or「是……還是……」。(A) that 引導的名詞子句表陳述事實，沒有「是否」之意，不合句意；(B) what 與 (C) which 須在子句中當主詞或受詞，但 the typhoon will hit Taiwan 已是完整子句。故選 (D)。", "level": "B2", "topic": "conjunction whether"}, {"id": "M112", "type": "grammar", "q": "The math test was ______ difficult that only three students passed it.", "options": ["such", "so", "very", "too"], "answer": 1, "explain": "句意：數學考試難到只有三位學生及格。so + 形容詞／副詞 + that 子句「如此……以致於……」。(A) such 後面須接名詞（如 such a difficult test that...）；(C) very 不能與 that 子句形成結果句型；(D) too 須搭配 to V（too...to...），不接 that 子句。故選 (B)。", "level": "B1", "topic": "so...that"}, {"id": "M113", "type": "grammar", "q": "Each of the students in my class ______ a different hobby.", "options": ["have", "are having", "has", "having"], "answer": 2, "explain": "句意：我們班上每位學生都有不同的嗜好。Each of + 複數名詞作主詞時，真正主詞是 each，視為單數，動詞用 has。(A) have 為複數動詞；(B) are having 為複數且 have 表「擁有」時不用進行式；(D) having 不是限定動詞，句子會缺少主要動詞。故選 (C)。", "level": "B1", "topic": "subject-verb agreement"}, {"id": "M114", "type": "grammar", "q": "The more you practice speaking English, ______ you will become.", "options": ["the more confident", "more confident", "the most confident", "most confident"], "answer": 0, "explain": "句意：你越常練習說英文，就會變得越有自信。「the + 比較級..., the + 比較級...」表「越……就越……」，後半句也須用 the + 比較級，故為 the more confident。(B) 少了 the；(C) 與 (D) 為最高級，不符合此句型。故選 (A)。", "level": "B2", "topic": "double comparative"}, {"id": "M115", "type": "grammar", "q": "If I ______ a million dollars, I would travel around the world with my family.", "options": ["have", "will have", "had had", "had"], "answer": 3, "explain": "句意：如果我有一百萬美元，我會和家人環遊世界。主要子句為 would + 原形動詞，表示與現在事實相反的假設，if 子句用過去式 had。(A) have 用於可能成真的條件句（主句配 will）；(B) will have 不能用在 if 條件子句中；(C) had had 用於與過去事實相反的假設，主句須為 would have p.p.。故選 (D)。", "level": "B1", "topic": "second conditional"}, {"id": "M116", "type": "grammar", "q": "If Amy had left home earlier, she ______ the bus to school.", "options": ["would not miss", "would not have missed", "will not miss", "did not miss"], "answer": 1, "explain": "句意：如果 Amy 早點出門，她就不會錯過上學的公車了。if 子句用過去完成式 had left，表示與過去事實相反，主要子句用 would + have + p.p.，故為 would not have missed。(A) would not miss 用於與現在事實相反；(C) will not miss 用於可能成真的條件句；(D) did not miss 為一般過去式，不構成假設語氣。故選 (B)。", "level": "B2", "topic": "third conditional"}, {"id": "M117", "type": "grammar", "q": "I failed the English test yesterday. I wish I ______ harder last week.", "options": ["had studied", "studied", "would study", "have studied"], "answer": 0, "explain": "句意：我昨天英文考試不及格，真希望上週有更用功。wish 後接與過去事實相反的願望（last week 已過去，事實上沒有用功），子句用過去完成式 had studied。(B) studied 表與現在事實相反；(C) would study 表希望未來情況改變；(D) have studied 現在完成式不能用於 wish 的假設語氣。故選 (A)。", "level": "B2", "topic": "wish"}, {"id": "M118", "type": "grammar", "q": "You look really tired. You ______ to bed so late last night.", "options": ["must not go", "should not go", "should not have gone", "cannot have gone"], "answer": 2, "explain": "句意：你看起來好累，昨晚不應該那麼晚睡的。should not have + p.p. 表示「過去不該做某事（但卻做了）」，帶有責備或後悔之意。(A) must not go 與 (B) should not go 指現在或未來，不能搭配 last night；(D) cannot have gone 表「不可能已經……」的推測，與「你看起來很累」矛盾。故選 (C)。", "level": "B2", "topic": "modal + have p.p."}, {"id": "M119", "type": "grammar", "q": "Not until the teacher came into the classroom ______ talking.", "options": ["the students stopped", "the students did stop", "stopped the students", "did the students stop"], "answer": 3, "explain": "句意：直到老師走進教室，學生們才停止講話。Not until... 置於句首時，主要子句須倒裝，形式為「助動詞 + 主詞 + 原形動詞」，即 did the students stop。(A) 與 (B) 都是一般語序，沒有倒裝；(C) stopped the students 語序錯誤，語意也變成「使學生停下」。故選 (D)。", "level": "B2", "topic": "inversion not until"}, {"id": "M120", "type": "grammar", "q": "Hardly ______ the house when it started to rain.", "options": ["we had left", "had we left", "we left", "did we leave"], "answer": 1, "explain": "句意：我們一離開家就開始下雨了。Hardly... when...「一……就……」，Hardly 置於句首時須倒裝，且 Hardly 子句用過去完成式、when 子句用過去式，故為 had we left。(A) we had left 與 (C) we left 沒有倒裝；(D) did we leave 雖倒裝但時態錯誤，此句型 Hardly 子句須用過去完成式。故選 (B)。", "level": "B2", "topic": "inversion hardly...when"}, {"id": "M121", "type": "grammar", "q": "My little brother is very interested ______ collecting old coins.", "options": ["on", "at", "in", "with"], "answer": 2, "explain": "句意：我弟弟對收集舊硬幣很有興趣。be interested in + N／V-ing「對……有興趣」為固定搭配。(A) on、(B) at、(D) with 都不是此片語所用的介系詞。故選 (C)。", "level": "B1", "topic": "prepositions"}, {"id": "M122", "type": "grammar", "q": "I asked two of my friends to help me with my science project, but ______ of them was free on Sunday.", "options": ["neither", "none", "both", "either"], "answer": 0, "explain": "句意：我請兩位朋友幫忙做科展，但他們兩個週日都沒空。對象是「兩個」人，表示「兩者都不」用 neither，neither of + 複數名詞後接單數動詞 was。(B) none 用於三者以上；(C) both 須接複數動詞 were，且與 but 的轉折語意不合；(D) either 表「兩者之一（有空）」，與 but 的語意矛盾。故選 (A)。", "level": "B1", "topic": "determiners"}, {"id": "M123", "type": "grammar", "q": "Let's take a short break and get something to drink, ______?", "options": ["will you", "shall we", "don't we", "won't you"], "answer": 1, "explain": "句意：我們休息一下，去買點喝的，好嗎？以 Let's 開頭的祈使句（包含說話者自己），附加問句用 shall we。(A) will you 與 (D) won't you 用於一般祈使句（如 Close the door, will you?）；(C) don't we 不能用於 Let's 句型。故選 (B)。", "level": "B1", "topic": "question tags"}, {"id": "M124", "type": "grammar", "q": "Jason hardly ever eats breakfast before school, ______?", "options": ["doesn't he", "isn't he", "is he", "does he"], "answer": 3, "explain": "句意：Jason 上學前幾乎從不吃早餐，對吧？hardly ever「幾乎從不」為否定副詞，主要子句視為否定，附加問句須用肯定；eats 為一般動詞現在式，助動詞用 does，故為 does he。(A) doesn't he 為否定，誤把主句當成肯定；(B) isn't he 與 (C) is he 助動詞錯誤，主句沒有 be 動詞。故選 (D)。", "level": "B2", "topic": "question tags"}, {"id": "M125", "type": "grammar", "q": "By the time you get to the station tomorrow morning, the first train ______.", "options": ["will have left", "has left", "had left", "leaves"], "answer": 0, "explain": "句意：等你明天早上到車站時，第一班火車早已開走了。By the time + 現在式（表未來），主要子句用未來完成式 will have p.p.，表示「到未來某時之前某事已經完成」。(B) has left 現在完成式不能表示未來某時已完成；(C) had left 用於 By the time + 過去式；(D) leaves 現在式無法表達「在你到之前就已開走」。故選 (A)。", "level": "B2", "topic": "future perfect"}, {"id": "M126", "type": "grammar", "q": "While I ______ dinner, the lights suddenly went out.", "options": ["cook", "have cooked", "was cooking", "am cooking"], "answer": 2, "explain": "句意：我正在煮晚餐時，燈突然熄了。while 引導的子句表示過去某時「正在進行」的動作，被另一個過去的短暫動作（燈熄了）打斷，用過去進行式 was cooking。(A) cook 與 (D) am cooking 為現在時態，與 went out 不符；(B) have cooked 現在完成式不能描述過去特定事件。故選 (C)。", "level": "B1", "topic": "past continuous"}, {"id": "M127", "type": "grammar", "q": "All reports ______ to the teacher by this Friday.", "options": ["must hand in", "must handing in", "must be handing in", "must be handed in"], "answer": 3, "explain": "句意：所有報告必須在本週五前交給老師。報告是「被繳交」的，須用被動語態；情態助動詞的被動形式為 must + be + p.p.，故為 must be handed in。(A) must hand in 為主動，語意變成報告自己去繳交；(B) 情態助動詞後不能接 V-ing；(C) must be handing in 為主動進行式，語意不合。故選 (D)。", "level": "B1", "topic": "modal passive"}, {"id": "M128", "type": "grammar", "q": "Lisa's bike was broken, so she had it ______ at the shop near her house.", "options": ["repair", "repaired", "repairing", "to repair"], "answer": 1, "explain": "句意：Lisa 的腳踏車壞了，所以她拿到家附近的店去修理。使役動詞 have + 物 + p.p. 表示「請人把某物……」，腳踏車是「被修理」的，用過去分詞 repaired。(A) repair 原形用於受詞是「人」的主動結構（have someone repair it）；(C) repairing 表示受詞主動進行動作；(D) 使役動詞 have 後不接 to V。故選 (B)。", "level": "B2", "topic": "causative have"}, {"id": "M129", "type": "grammar", "q": "Having lived in Taipei for five years, Emma is used to ______ the MRT every day.", "options": ["take", "took", "taking", "be taken"], "answer": 2, "explain": "句意：在台北住了五年，Emma 已經習慣每天搭捷運。be used to + V-ing／N「習慣於……」，其中 to 是介系詞，後接動名詞 taking。(A) take 原形用於 used to V「過去常常」或 be used to V「被用來……」，皆不合句意；(B) took 為過去式；(D) be taken 為被動，語意不合。故選 (C)。", "level": "B2", "topic": "be used to"}, {"id": "M130", "type": "grammar", "q": "Tom forgot his mother's birthday, ______ made her very upset.", "options": ["which", "that", "what", "it"], "answer": 0, "explain": "句意：Tom 忘了媽媽的生日，這讓她很難過。逗點後的非限定關係子句可用 which 代替前面整個句子（忘了生日這件事），並在子句中當主詞。(B) that 不能用於逗點後的非限定關係子句；(C) what 前面不可有先行詞；(D) it 是代名詞，用逗點連接兩個獨立子句會形成錯誤句（run-on sentence）。故選 (A)。", "level": "B2", "topic": "non-defining which"}, {"id": "M131", "type": "grammar", "q": "Peter is not old ______ to get a driver's license yet.", "options": ["too", "enough", "so", "very"], "answer": 1, "explain": "句意：Peter 年紀還不夠大，還不能考駕照。形容詞 + enough + to V「夠……可以……」，enough 放在形容詞 old 之後。(A) too 須放在形容詞之前（too young to...）；(C) so 須搭配 that 子句；(D) very 不能與 to V 形成此句型。故選 (B)。", "level": "B1", "topic": "adjective + enough"}, {"id": "M132", "type": "grammar", "q": "Taipei 101 is one of the ______ in the world.", "options": ["tallest building", "taller buildings", "most tall buildings", "tallest buildings"], "answer": 3, "explain": "句意：台北101是世界上最高的建築之一。one of the + 最高級 + 複數名詞「最……的……之一」，tall 的最高級為 tallest，名詞須用複數 buildings。(A) tallest building 的名詞為單數；(B) taller 為比較級；(C) most tall 為錯誤的最高級形式。故選 (D)。", "level": "B1", "topic": "superlatives"}, {"id": "M133", "type": "grammar", "q": "It's already eleven o'clock. It's high time you ______ to bed.", "options": ["went", "go", "will go", "have gone"], "answer": 0, "explain": "句意：已經十一點了，你早該去睡覺了。It is (high) time + 主詞 + 過去式動詞，表示「早該做某事了（但還沒做）」，屬假設語氣，用過去式 went（也可說 It's time for you to go to bed）。(B) go 原形、(C) will go 未來式、(D) have gone 現在完成式都不合此句型。故選 (A)。", "level": "B2", "topic": "it's time + past"}, {"id": "M134", "type": "grammar", "q": "My sister spends at least two hours ______ online games every weekend.", "options": ["play", "to play", "playing", "played"], "answer": 2, "explain": "句意：我姊姊每個週末至少花兩小時玩線上遊戲。spend + 時間／金錢 + (in) V-ing「花時間或金錢做某事」，故用 playing。(A) play 原形、(B) to play 不定詞、(D) played 過去式都不合此句型。故選 (C)。", "level": "B1", "topic": "spend + V-ing"}, {"id": "M135", "type": "grammar", "q": "The students were made ______ the classroom after the party.", "options": ["clean", "to clean", "cleaning", "cleaned"], "answer": 1, "explain": "句意：派對結束後，學生們被要求打掃教室。使役動詞 make 主動時為 make + 人 + 原形動詞，但改成被動 be made 時須還原 to，成為 be made + to V，故用 to clean。(A) clean 原形只用於主動句（made the students clean...）；(C) cleaning 與 (D) cleaned 都不合此句型。故選 (B)。", "level": "B2", "topic": "passive of make"}, {"id": "M136", "type": "grammar", "q": "Not only ______ the piano, but she also writes her own songs.", "options": ["she plays", "plays she", "she does play", "does she play"], "answer": 3, "explain": "句意：她不僅會彈鋼琴，還會自己寫歌。Not only 置於句首時，該子句須倒裝：助動詞 + 主詞 + 原形動詞；現在式一般動詞借助 does，故為 does she play。(A) she plays 與 (C) she does play 沒有倒裝；(B) 一般動詞不能直接移到主詞前面倒裝。故選 (D)。", "level": "B2", "topic": "inversion not only"}, {"id": "M137", "type": "grammar", "q": "I will call you as soon as I ______ at the airport.", "options": ["arrive", "will arrive", "arrived", "am going to arrive"], "answer": 0, "explain": "句意：我一到機場就會打電話給你。表時間的副詞子句（as soon as、when、before、after 等）以現在式代替未來式，故用 arrive。(B) will arrive 與 (D) am going to arrive 不可用於時間副詞子句表未來；(C) arrived 為過去式，與主要子句 will call 不符。故選 (A)。", "level": "B1", "topic": "time clauses"}, {"id": "M138", "type": "grammar", "q": "The lecture was so long that many students in the hall felt ______.", "options": ["boring", "bored", "bore", "to bore"], "answer": 1, "explain": "句意：演講太長了，禮堂裡很多學生都覺得很無聊。描述「人」的感受用 -ed 形容詞，bored 表「感到無聊的」。(A) boring 表「令人無聊的」，用來描述事物（如 The lecture was boring）；(C) bore 為動詞或名詞；(D) to bore 不能接在 felt 後當補語。故選 (B)。", "level": "B1", "topic": "-ed/-ing adjectives"}, {"id": "M139", "type": "grammar", "q": "Hurry up! We have very ______ time before the concert begins.", "options": ["few", "many", "a few", "little"], "answer": 3, "explain": "句意：快一點！演唱會開始前我們只剩很少的時間了。time 為不可數名詞，表示「很少、幾乎沒有」用 little（very little）。(A) few、(B) many、(C) a few 都只能修飾可數名詞，且 Hurry up 暗示時間不夠，語意偏否定，須用 little。故選 (D)。", "level": "B1", "topic": "quantifiers"}, {"id": "M140", "type": "grammar", "q": "Either you or your brother ______ to wash the dishes tonight.", "options": ["have", "are", "has", "were"], "answer": 2, "explain": "句意：今晚不是你就是你弟弟要洗碗。Either A or B 作主詞時，動詞與最靠近的主詞 B 一致（就近原則）；B 為 your brother（第三人稱單數），故用 has to。(A) have 與 (B) are 為配合 you 或複數主詞的形式；(D) were 為過去式且不是第三人稱單數的形式，也與 tonight 不合。故選 (C)。", "level": "B2", "topic": "subject-verb agreement"}, {"id": "M141", "type": "grammar", "q": "Many teenagers prefer texting ______ talking on the phone.", "options": ["to", "than", "from", "for"], "answer": 0, "explain": "句意：許多青少年比較喜歡傳訊息，而不是講電話。prefer A to B「喜歡 A 勝過 B」，A、B 為名詞或動名詞，介系詞用 to。(B) than 用於比較級；prefer 若要接 than，須寫成 prefer to V rather than (V)，不能用在 prefer A ___ B 的句型；(C) from 與 (D) for 都不是此句型的搭配。故選 (A)。", "level": "B1", "topic": "prefer A to B"}, {"id": "M142", "type": "grammar", "q": "It looks like it's going to rain. You'd better ______ an umbrella with you.", "options": ["to take", "taking", "took", "take"], "answer": 3, "explain": "句意：看起來快下雨了，你最好帶把傘。had better（'d better）「最好……」後面接原形動詞，故為 take。(A) to take、(B) taking、(C) took 都不能接在 had better 之後。故選 (D)。", "level": "B1", "topic": "had better"}, {"id": "M143", "type": "grammar", "q": "When the clown fell off his chair, the audience couldn't help ______.", "options": ["to laugh", "laugh", "laughing", "laughed"], "answer": 2, "explain": "句意：小丑從椅子上摔下來時，觀眾忍不住大笑。can't／couldn't help + V-ing「忍不住……」，help 在此意為「避免」，後接動名詞 laughing。(A) to laugh 與 (B) laugh 不能直接接在 couldn't help 之後（另一種說法為 couldn't help but laugh）；(D) laughed 為過去式。故選 (C)。", "level": "B2", "topic": "can't help V-ing"}, {"id": "M144", "type": "grammar", "q": "I'm feeling a bit tired, so I would rather ______ home tonight than go to the party.", "options": ["to stay", "stay", "staying", "stayed"], "answer": 1, "explain": "句意：我有點累，所以今晚寧願待在家也不去派對。would rather + 原形動詞 + than + 原形動詞「寧願……而不願……」，與後面的 than go 對稱，故用 stay。(A) to stay 與 (C) staying 不能接在 would rather 之後；(D) stayed 用於 would rather + 另一個主詞 的假設語氣（如 I'd rather you stayed），此處主詞相同，不適用。故選 (B)。", "level": "B1", "topic": "would rather"}, {"id": "M145", "type": "grammar", "q": "Do you know the girl ______ next to the window? She is our new classmate.", "options": ["standing", "stood", "stands", "to stand"], "answer": 0, "explain": "句意：你認識站在窗邊的那個女孩嗎？她是我們的新同學。原句為 the girl who is standing next to the window，省略關係代名詞與 be 動詞後，主動用現在分詞 standing 修飾 girl。(B) stood 為過去分詞，表被動，且 stand 為不及物動詞；(C) stands 為限定動詞，句中已有主要動詞 know，不能再直接接；(D) to stand 表未來或目的，語意不合。故選 (A)。", "level": "B1", "topic": "reduced relative clause"}, {"id": "M146", "type": "grammar", "q": "Grandpa was sitting on the sofa with his arms ______, listening to his favorite music.", "options": ["folding", "fold", "folded", "to fold"], "answer": 2, "explain": "句意：爺爺雙臂交叉坐在沙發上，聽著他最喜歡的音樂。with + 受詞 + 分詞 表示附帶狀況；手臂是「被（爺爺）交叉起來」的，與 arms 為被動關係，用過去分詞 folded。(A) folding 表示手臂主動在摺疊，語意不合；(B) fold 原形與 (D) to fold 都不合此句型。故選 (C)。", "level": "B2", "topic": "with + O + participle"}, {"id": "M147", "type": "grammar", "q": "______ you need any help with your project, please feel free to contact me.", "options": ["Unless", "Had", "Were", "Should"], "answer": 3, "explain": "句意：如果你的專題需要任何幫忙，請隨時跟我聯絡。Should + 主詞 + 原形動詞 為省略 if 的倒裝條件句，= If you should need any help，表「萬一、如果需要」。(A) Unless「除非」語意相反；(B) Had 倒裝後須接 p.p.（Had you needed），表與過去事實相反；(C) Were 倒裝後須接名詞、形容詞或 to V（Were you to need），不能接原形動詞。故選 (D)。", "level": "B2", "topic": "inverted conditional"}, {"id": "M148", "type": "grammar", "q": "The number of students who walk to school ______ decreasing in recent years.", "options": ["have been", "has been", "are", "were"], "answer": 1, "explain": "句意：近年來走路上學的學生人數一直在減少。The number of + 複數名詞「……的數量」，主詞是 the number，視為單數；in recent years 表示從過去持續到現在，用現在完成進行式 has been decreasing。(A) have been 與 (C) are 為複數動詞（A number of + 複數名詞「許多」才接複數動詞）；(D) were 為過去式且為複數。故選 (B)。", "level": "B1", "topic": "subject-verb agreement"}, {"id": "M149", "type": "grammar", "q": "Ben ______ my email this afternoon. He has been on a plane without Internet access all day.", "options": ["can't have read", "must have read", "should have read", "needn't have read"], "answer": 0, "explain": "句意：Ben 今天下午不可能讀過我的電子郵件，他整天都在沒有網路的飛機上。can't have + p.p. 表示對過去的推測「不可能已經……」。(B) must have read 表「一定已經讀了」，與事實矛盾；(C) should have read 表「本來應該讀（卻沒讀）」，帶責備意味，但他無法上網，不合邏輯；(D) needn't have read 表「其實不必讀卻讀了」，表示他有讀，也與事實矛盾。故選 (A)。", "level": "B2", "topic": "modal deduction"}, {"id": "M150", "type": "grammar", "q": "Would you mind ______ the window? It's a little cold in here.", "options": ["close", "to close", "closing", "closed"], "answer": 2, "explain": "句意：你介意關一下窗戶嗎？這裡有點冷。mind 後面接動名詞，Would you mind + V-ing? 為禮貌的請求，故用 closing。(A) close 原形、(B) to close 不定詞、(D) closed 過去式都不能接在 mind 之後。故選 (C)。", "level": "B1", "topic": "mind + V-ing"}, {"id": "M151", "type": "grammar", "q": "My grandfather ______ his bike to work every day, but now he takes the MRT.", "options": ["rides", "used to ride", "is riding", "has ridden"], "answer": 1, "explain": "句意：我爺爺以前每天騎腳踏車上班，但現在他改搭捷運。used to + 原形動詞表示「過去常常…（現在已不再）」，與後句 but now 形成對比。(A) rides 現在式表示現在的習慣，與「現在搭捷運」矛盾；(C) is riding 現在進行式不合句意；(D) has ridden 現在完成式無法表達「過去的習慣，現在已改變」。故選 (B)。", "level": "B1", "topic": "used to"}, {"id": "M152", "type": "grammar", "q": "A new swimming pool ______ at our school next year, so students will be able to take swimming classes.", "options": ["builds", "is building", "has built", "will be built"], "answer": 3, "explain": "句意：我們學校明年將蓋一座新游泳池，屆時學生就能上游泳課了。游泳池是「被建造」，須用被動語態；next year 表示未來，故用未來式被動 will be built。(A) builds、(B) is building、(C) has built 都是主動語態，好像游泳池自己在蓋東西，不合理。故選 (D)。", "level": "B1", "topic": "future passive"}, {"id": "M153", "type": "grammar", "q": "I find ______ hard to wake up early on cold winter mornings.", "options": ["it", "that", "this", "what"], "answer": 0, "explain": "句意：我覺得在寒冷的冬天早上很難早起。「find + it + 形容詞 + to V」中，it 為虛受詞，代替後面真正的受詞 to wake up early...。(B) that、(C) this 不能當虛受詞來指後面的不定詞片語；(D) what 無法用在此句型。故選 (A)。", "level": "B2", "topic": "it as dummy object"}, {"id": "M154", "type": "grammar", "q": "To stay healthy, you should avoid ______ too many sugary drinks.", "options": ["drink", "to drink", "drinking", "to drinking"], "answer": 2, "explain": "句意：為了保持健康，你應該避免喝太多含糖飲料。avoid 後面須接動名詞 (V-ing)，即 avoid drinking。(A) drink 原形動詞、(B) to drink 不定詞都不能接在 avoid 之後；(D) to drinking 文法錯誤。故選 (C)。", "level": "B1", "topic": "avoid + V-ing"}, {"id": "M155", "type": "grammar", "q": "The streets are all wet this morning. It ______ heavily last night.", "options": ["must have rained", "should have rained", "can't have rained", "must rain"], "answer": 0, "explain": "句意：今天早上街道全都濕了，昨晚一定下了大雨。must have + p.p. 表示「對過去事情有把握的肯定推測」（過去一定…）。(B) should have rained 表示「過去本來應該…（卻沒有）」，語意不合；(C) can't have rained 表示「昨晚不可能下雨」，與街道濕了矛盾；(D) must rain 指現在或未來，無法搭配 last night。故選 (A)。", "level": "B2", "topic": "modal + have p.p."}, {"id": "M156", "type": "grammar", "q": "Write down my phone number ______ you get lost in the city.", "options": ["unless", "because", "although", "in case"], "answer": 3, "explain": "句意：把我的電話號碼寫下來，以防你在市區迷路。in case「以防萬一」，後接子句，表示預先做準備。(A) unless「除非」會變成「除非你迷路，否則把電話寫下來」，不合邏輯；(B) because「因為」用於已確定的原因，但迷路尚未發生；(C) although「雖然」表讓步，也不合語意。故選 (D)。", "level": "B1", "topic": "conjunction in case"}, {"id": "M157", "type": "grammar", "q": "______ that my friends were secretly planning a surprise party for me.", "options": ["Little I knew", "Little did I know", "Little I did know", "Little knew I"], "answer": 1, "explain": "句意：我完全不知道朋友們正偷偷幫我籌備一場驚喜派對。具否定意味的副詞 Little（完全不）放句首時，句子須倒裝，一般動詞用「助動詞 + 主詞 + 原形動詞」，即 Little did I know。(A) Little I knew、(C) Little I did know 都沒有倒裝；(D) Little knew I 直接把一般動詞移到主詞前，是錯誤的倒裝形式。故選 (B)。", "level": "B2", "topic": "inversion: little"}, {"id": "M158", "type": "grammar", "q": "Watching movies with friends ______ my favorite way to relax on weekends.", "options": ["are", "were", "is", "have"], "answer": 2, "explain": "句意：和朋友一起看電影是我週末最喜歡的放鬆方式。動名詞片語 Watching movies with friends 當主詞時，視為單數，動詞用 is。(A) are、(B) were 是複數動詞，誤把 movies 或 friends 當成主詞；(D) have 不合句意，此處須用 be 動詞連接主詞與補語。故選 (C)。", "level": "B1", "topic": "gerund subject agreement"}, {"id": "M159", "type": "grammar", "q": "______ what to say, Tina just smiled and nodded.", "options": ["Knowing not", "Not known", "Not to know", "Not knowing"], "answer": 3, "explain": "句意：因為不知道該說什麼，Tina 只是微笑點頭。此為分詞構句，原句為 Because she didn't know what to say...，主詞相同且為主動，否定的分詞構句要把 not 放在分詞前面，即 Not knowing。(A) Knowing not 否定詞位置錯誤；(B) Not known 為過去分詞，表被動，不合句意；(C) Not to know 為不定詞，不能表示原因。故選 (D)。", "level": "B2", "topic": "negative participle clause"}, {"id": "M160", "type": "grammar", "q": "Our new gym is twice ______ the old one, so the whole school can fit inside.", "options": ["as big as", "bigger as", "as bigger as", "the biggest of"], "answer": 0, "explain": "句意：我們新的體育館是舊的兩倍大，所以全校師生都容納得下。倍數比較用「倍數 + as + 形容詞原級 + as」，即 twice as big as。(B) bigger as 比較級不能接 as；(C) as bigger as 中間不能用比較級；(D) the biggest of 為最高級，不能接在倍數後比較兩者。故選 (A)。", "level": "B2", "topic": "multiples: twice as...as"}, {"id": "M161", "type": "grammar", "q": "Our school's sports day will be held ______ the morning of October 25.", "options": ["in", "at", "on", "by"], "answer": 2, "explain": "句意：我們學校的運動會將在 10 月 25 日早上舉行。一般說 in the morning，但指「特定某一天的早上」時要用 on，如 on the morning of October 25。(A) in 用於一般的早上、月份或年份；(B) at 用於時刻；(D) by 表「在…之前」，皆不合。故選 (C)。", "level": "B1", "topic": "prepositions of time"}, {"id": "M162", "type": "grammar", "q": "If I had gone to bed earlier last night, I ______ so sleepy now.", "options": ["won't feel", "wouldn't feel", "wouldn't have felt", "didn't feel"], "answer": 1, "explain": "句意：如果我昨晚早點睡，現在就不會這麼睏了。這是混合條件句：if 子句用 had + p.p. 表示與過去事實相反；主要子句有 now，表示與現在事實相反，須用 would + 原形動詞，即 wouldn't feel。(A) won't feel 為一般條件句的用法；(C) wouldn't have felt 表示與過去事實相反，與 now 衝突；(D) didn't feel 不能用在條件句的主要子句。故選 (B)。", "level": "B2", "topic": "mixed conditional"}, {"id": "M163", "type": "grammar", "q": "Your sister can speak Japanese, ______?", "options": ["doesn't she", "isn't she", "can she", "can't she"], "answer": 3, "explain": "句意：你姊姊會說日語，不是嗎？附加問句的助動詞須與前句一致，且「前肯後否」。前句用 can，故附加問句用 can't she。(A) doesn't she、(B) isn't she 助動詞錯誤；(C) can she 為肯定形式，不符合「前肯後否」。故選 (D)。", "level": "B1", "topic": "question tags"}, {"id": "M164", "type": "grammar", "q": "Many new students have difficulty ______ their way around the large campus.", "options": ["finding", "to find", "find", "found"], "answer": 0, "explain": "句意：許多新生在這個大校園裡很難找到路。have difficulty (in) + V-ing 表示「做…有困難」，故用 finding。(B) to find 不定詞、(C) find 原形動詞、(D) found 過去式都不能用在此句型。故選 (A)。", "level": "B1", "topic": "have difficulty + V-ing"}, {"id": "M165", "type": "grammar", "q": "I wish I ______ how to swim. Then I could join my friends at the beach.", "options": ["know", "have known", "knew", "will know"], "answer": 2, "explain": "句意：真希望我會游泳，那樣我就能和朋友一起去海邊玩了。wish 表示與現在事實相反的願望時，後面子句用過去式，故用 knew。(A) know 現在式不能表示與事實相反；(B) have known 時態錯誤；(D) will know 是未來式，wish 子句不用此形式。故選 (C)。", "level": "B2", "topic": "wish (present)"}, {"id": "M166", "type": "grammar", "q": "I still remember the day ______ I first met my best friend in junior high school.", "options": ["which", "when", "where", "what"], "answer": 1, "explain": "句意：我還記得在國中第一次遇見我最好朋友的那一天。先行詞 the day 表時間，且關係子句結構完整 (I first met my best friend)，須用關係副詞 when (= on which)。(A) which 須在子句中當主詞或受詞，但此子句不缺；(C) where 指地點；(D) what 不能接在先行詞之後。故選 (B)。", "level": "B1", "topic": "relative adverb when"}, {"id": "M167", "type": "grammar", "q": "It was ______ a hot day that my ice cream melted before I could finish it.", "options": ["such", "so", "too", "very"], "answer": 0, "explain": "句意：那天實在太熱了，我的冰淇淋還沒吃完就融化了。「such + a/an + 形容詞 + 名詞 + that 子句」表示「如此…以致於…」，空格後是名詞片語 a hot day，故用 such。(B) so 後面直接接形容詞，須寫成 so hot a day 才正確；(C) too 常與 to V 連用 (too...to...)；(D) very 無法與 that 子句搭配形成此句型。故選 (A)。", "level": "B1", "topic": "such...that"}, {"id": "M168", "type": "grammar", "q": "My parents won't let me ______ out after ten o'clock on school nights.", "options": ["going", "to go", "gone", "go"], "answer": 3, "explain": "句意：隔天要上學的晚上，我爸媽不准我十點後出門。使役動詞 let 的用法為「let + 受詞 + 原形動詞」，故用 go。(A) going 動名詞、(B) to go 不定詞、(C) gone 過去分詞都不能接在 let + 受詞之後。故選 (D)。", "level": "B1", "topic": "let + O + V"}, {"id": "M169", "type": "grammar", "q": "I have two brothers. One is a nurse, and ______ is a police officer.", "options": ["another", "other", "the other", "others"], "answer": 2, "explain": "句意：我有兩個兄弟，一個是護理師，另一個是警察。兩者之中，一個用 one，「另一個」用 the other。(A) another 用於三者以上中的「另一個」；(B) other 為形容詞，後面須接名詞；(D) others 為複數，指「其他的人／物」，與單數動詞 is 不合。故選 (C)。", "level": "B1", "topic": "one...the other"}, {"id": "M170", "type": "grammar", "q": "My family ______ to Yilan two years ago, and we really love living there.", "options": ["moves", "moved", "has moved", "have moved"], "answer": 1, "explain": "句意：我們家兩年前搬到宜蘭，我們真的很喜歡住在那裡。ago 表示過去的時間點，須用過去簡單式 moved。(A) moves 現在式不能搭配 two years ago；(C) has moved、(D) have moved 為現在完成式，不能與 ago 這類明確的過去時間連用。故選 (B)。", "level": "B1", "topic": "simple past with ago"}, {"id": "M171", "type": "grammar", "q": "Falling down on the stage in front of the whole school was really ______ for Amy.", "options": ["embarrassing", "embarrassed", "embarrass", "embarrassment"], "answer": 0, "explain": "句意：在全校面前跌倒在舞台上，對 Amy 來說真的很令人尷尬。主詞是「在台上跌倒」這件事，事物「令人感到…」用現在分詞 embarrassing。(B) embarrassed 表示「人感到尷尬」，主詞須為人；(C) embarrass 是動詞原形；(D) embarrassment 是名詞，不能被 really 修飾當補語。故選 (A)。", "level": "B1", "topic": "participial adjectives"}, {"id": "M172", "type": "grammar", "q": "Rarely ______ late for school; he usually arrives before seven-thirty.", "options": ["Ben is", "Ben was", "is Ben", "does Ben"], "answer": 2, "explain": "句意：Ben 很少上學遲到，他通常七點半前就到了。具否定意味的副詞 Rarely（很少）放句首時，句子須倒裝；句中動詞為 be 動詞，直接將 is 移到主詞前，即 is Ben。(A) Ben is、(B) Ben was 都沒有倒裝，且 (B) 的時態與 usually arrives 不符；(D) does Ben 後面缺少動詞，late 是形容詞，須搭配 be 動詞。故選 (C)。", "level": "B2", "topic": "inversion: rarely"}, {"id": "M173", "type": "grammar", "q": "______ the heavy traffic, we arrived at the concert hall on time.", "options": ["Although", "Because of", "Unless", "Despite"], "answer": 3, "explain": "句意：儘管交通很壅塞，我們還是準時抵達音樂廳。空格後是名詞片語 the heavy traffic，且前後語意相反，須用介系詞 Despite「儘管」。(A) Although 是連接詞，後面須接子句；(B) Because of「因為」語意不合；(C) Unless「除非」是連接詞，後接子句，語意也不合。故選 (D)。", "level": "B2", "topic": "despite vs although"}, {"id": "M174", "type": "grammar", "q": "Ten thousand dollars ______ a lot of money for a high school student.", "options": ["are", "is", "were", "have"], "answer": 1, "explain": "句意：一萬元對高中生來說是一大筆錢。表示金額、時間、距離的複數名詞被視為「一個整體」時，當單數，動詞用 is。(A) are、(C) were 為複數動詞；(D) have 不合句意，此處須用 be 動詞連接補語 a lot of money。故選 (B)。", "level": "B2", "topic": "agreement with amounts"}, {"id": "M175", "type": "grammar", "q": "The friend ______ I traveled to Japan last summer is moving to Canada next month.", "options": ["with whom", "whom", "with who", "which"], "answer": 0, "explain": "句意：去年夏天和我一起去日本旅行的那位朋友，下個月要搬去加拿大了。原句為 I traveled to Japan with the friend，介系詞 with 移到關係代名詞前時，須用受格 whom，即 with whom。(B) whom 單獨使用時，句中缺少介系詞 with；(C) 介系詞後面不能接主格 who；(D) which 用於事物，不能指人。故選 (A)。", "level": "B2", "topic": "preposition + whom"}, {"id": "M176", "type": "grammar", "q": "After a long discussion, the class decided ______ a food stand at the school fair.", "options": ["run", "running", "to run", "to running"], "answer": 2, "explain": "句意：經過長時間的討論，全班決定在校慶園遊會上擺一個小吃攤。decide 後面接不定詞 to V，表示「決定做某事」，故用 to run。(A) run 原形、(B) running 動名詞都不能接在 decide 之後；(D) to running 文法錯誤。故選 (C)。", "level": "B1", "topic": "decide + to V"}, {"id": "M177", "type": "grammar", "q": "This summer was not as ______ as last summer; we hardly needed to turn on the air conditioner.", "options": ["hotter", "hot", "hottest", "more hot"], "answer": 1, "explain": "句意：今年夏天沒有去年夏天那麼熱，我們幾乎不需要開冷氣。「not as + 形容詞原級 + as」表示「不如…」，as...as 中間須用原級 hot。(A) hotter 為比較級，(D) more hot 為錯誤的比較級形式；(C) hottest 為最高級，都不能放在 as...as 中間。故選 (B)。", "level": "B1", "topic": "as...as comparison"}, {"id": "M178", "type": "grammar", "q": "Why didn't you tell me you needed a ride yesterday? I ______ you to the station.", "options": ["could drive", "must have driven", "can't have driven", "could have driven"], "answer": 3, "explain": "句意：你昨天怎麼沒跟我說你需要人載？我本來可以開車載你去車站的。could have + p.p. 表示「過去本來可以做（但實際上沒做）」。(A) could drive 指現在或未來的能力、可能，不能用於昨天已過去的情境；(B) must have driven 表示「過去一定載過了」，與事實不符；(C) can't have driven 表示「過去不可能載」，是推測用法，不合句意。故選 (D)。", "level": "B2", "topic": "could have p.p."}, {"id": "M179", "type": "grammar", "q": "My sister is very proud ______ the photography award she won last month.", "options": ["of", "for", "with", "at"], "answer": 0, "explain": "句意：我姊姊對她上個月得到的攝影獎感到非常驕傲。be proud of「以…為榮」為固定搭配。(B) for、(C) with、(D) at 都不能與 proud 搭配表達此義。故選 (A)。", "level": "B1", "topic": "adjective + preposition"}, {"id": "M180", "type": "grammar", "q": "The smartphone ______ by this company last month has already sold over one million units.", "options": ["releasing", "releases", "released", "was released"], "answer": 2, "explain": "句意：這家公司上個月推出的智慧型手機已經賣出超過一百萬支。手機是「被推出」，用過去分詞 released 修飾前面的名詞 (= which was released)。(A) releasing 現在分詞表主動，不合句意；(B) releases、(D) was released 是動詞，但句子已有主要動詞 has sold，不能再出現另一個動詞。故選 (C)。", "level": "B2", "topic": "past participle modifier"}, {"id": "M181", "type": "grammar", "q": "______ you, I would apologize to her as soon as possible.", "options": ["If I am", "I were", "Was I", "Were I"], "answer": 3, "explain": "句意：如果我是你，我會盡快向她道歉。與現在事實相反的假設 If I were you 可省略 if，將 were 移到主詞前倒裝成 Were I you。(A) If I am 是一般條件句，不能表示「我是你」這種不可能的假設；(B) I were 缺少連接詞也未倒裝；(C) Was I 不是此句型的正確形式，須用 were。故選 (D)。", "level": "B2", "topic": "inverted conditional"}, {"id": "M182", "type": "grammar", "q": "Please speak louder ______ everyone in the back of the room can hear you.", "options": ["so that", "even if", "as if", "in case of"], "answer": 0, "explain": "句意：請說大聲一點，好讓教室後面的每個人都聽得到。so that + 子句表示目的「以便、好讓」，常與 can / could 連用。(B) even if「即使」表讓步；(C) as if「彷彿」表示狀態；(D) in case of 是介系詞片語，後面須接名詞，不能接子句。故選 (A)。", "level": "B1", "topic": "so that (purpose)"}, {"id": "M183", "type": "grammar", "q": "Kevin forgot his calculator, so I lent him ______.", "options": ["my", "mine", "me", "myself"], "answer": 1, "explain": "句意：Kevin 忘了帶計算機，所以我把我的借給他。空格是 lent him 後的直接受詞，指「我的計算機」，須用所有格代名詞 mine (= my calculator)。(A) my 是所有格形容詞，後面必須接名詞；(C) me 會變成「把我借給他」，不合理；(D) myself 反身代名詞也不合語意。故選 (B)。", "level": "B1", "topic": "possessive pronouns"}, {"id": "M184", "type": "grammar", "q": "______ surprised me most was that the little girl could play the violin so well.", "options": ["That", "Which", "What", "It"], "answer": 2, "explain": "句意：最讓我驚訝的是，那個小女孩小提琴拉得那麼好。空格引導名詞子句當整句主詞，且子句中缺主詞 (___ surprised me most)，須用複合關係代名詞 What (= the thing that)。(A) That 引導名詞子句時，子句必須完整，不能缺主詞；(B) Which 沒有先行詞，不能這樣使用；(D) It 會造成一句中有兩個動詞 (surprised, was)，文法錯誤。故選 (C)。", "level": "B2", "topic": "noun clause with what"}, {"id": "M185", "type": "grammar", "q": "It is no use ______ over spilt milk.", "options": ["cry", "crying", "to crying", "cried"], "answer": 1, "explain": "句意：為打翻的牛奶哭泣是沒有用的（覆水難收）。It is no use + V-ing 為固定句型，表示「做…是沒有用的」，故用 crying。(A) cry 原形、(D) cried 過去式不能用在此句型；(C) to crying 文法錯誤。故選 (B)。", "level": "B2", "topic": "it is no use + V-ing"}, {"id": "M186", "type": "grammar", "q": "The road in front of our school ______ right now, so we have to take a different way home.", "options": ["is repairing", "has repaired", "repairs", "is being repaired"], "answer": 3, "explain": "句意：學校前面的道路現在正在整修，所以我們得走別條路回家。道路是「被修理」，且 right now 表示動作正在進行，須用現在進行式被動「is being + p.p.」。(A) is repairing、(B) has repaired、(C) repairs 都是主動語態，好像道路自己在修東西，不合理。故選 (D)。", "level": "B2", "topic": "present continuous passive"}, {"id": "M187", "type": "grammar", "q": "You can borrow my notebook ______ you return it to me by Friday.", "options": ["unless", "though", "as long as", "whether"], "answer": 2, "explain": "句意：只要你在星期五前還我，就可以借我的筆記本。as long as「只要」表條件。(A) unless「除非」會變成「如果你不在星期五前還我，就可以借」，語意相反；(B) though「雖然」表讓步；(D) whether「是否」不能引導此條件子句。故選 (C)。", "level": "B1", "topic": "conjunction as long as"}, {"id": "M188", "type": "grammar", "q": "The new MRT line makes it ______ easier for people to travel between the two cities.", "options": ["much", "very", "more", "most"], "answer": 0, "explain": "句意：新的捷運線讓兩座城市之間的往來方便多了。修飾比較級 easier 要用 much、a lot、even、far 等副詞，表示「…得多」。(B) very 不能修飾比較級；(C) more easier 為雙重比較級，錯誤；(D) most 為最高級用字，不能修飾比較級。故選 (A)。", "level": "B1", "topic": "modifying comparatives"}, {"id": "M189", "type": "grammar", "q": "There's a math test tomorrow, ______?", "options": ["is it", "isn't there", "isn't it", "is there"], "answer": 1, "explain": "句意：明天有數學考試，對吧？There is 句型的附加問句要用 there 當主詞，且「前肯後否」，故用 isn't there。(A) is it、(C) isn't it 主詞錯誤，不能用 it；(D) is there 為肯定形式，不符合「前肯後否」。故選 (B)。", "level": "B1", "topic": "question tags"}, {"id": "M190", "type": "grammar", "q": "The teacher, as well as her students, ______ excited about the field trip to Tainan.", "options": ["are", "were", "have", "is"], "answer": 3, "explain": "句意：老師和她的學生們都對台南的校外教學感到很興奮。A as well as B 當主詞時，動詞須與前面的 A 一致；A 為 The teacher（單數），故用 is。(A) are、(B) were 為複數動詞，誤把 students 當成主詞；(C) have 不合句意，excited 為形容詞，須搭配 be 動詞。故選 (D)。", "level": "B2", "topic": "as well as agreement"}, {"id": "M191", "type": "grammar", "q": "The box is too heavy for me ______. Can you give me a hand?", "options": ["carry", "carrying", "to carry", "carried"], "answer": 2, "explain": "句意：這個箱子太重了，我搬不動，你可以幫我一下嗎？「too + 形容詞 + (for 人) + to V」表示「太…而不能…」，故用 to carry。(A) carry 原形、(B) carrying 動名詞、(D) carried 過去式／過去分詞都不能用在此句型。故選 (C)。", "level": "B1", "topic": "too...to"}, {"id": "M192", "type": "grammar", "q": "I ______ for the bus for forty minutes, and it still hasn't come.", "options": ["have been waiting", "was waiting", "wait", "had waited"], "answer": 0, "explain": "句意：我已經等公車等了四十分鐘，公車還是沒來。for + 一段時間，且動作從過去持續到現在、仍在進行 (still hasn't come)，用現在完成進行式 have been waiting。(B) was waiting 過去進行式只表示過去某時正在進行；(C) wait 現在式不能搭配 for forty minutes 表持續；(D) had waited 過去完成式與 still hasn't come 的現在時間不合。故選 (A)。", "level": "B2", "topic": "present perfect continuous"}, {"id": "M193", "type": "grammar", "q": "The girl ______ won first prize in the speech contest is my cousin.", "options": ["which", "whom", "whose", "who"], "answer": 3, "explain": "句意：在演講比賽中得到第一名的那個女孩是我表妹。先行詞 the girl 是人，且關係子句中缺主詞 (___ won first prize)，須用主格關係代名詞 who。(A) which 用於事物；(B) whom 是受格，不能當主詞；(C) whose 為所有格，後面須接名詞。故選 (D)。", "level": "B1", "topic": "relative pronoun who"}, {"id": "M194", "type": "grammar", "q": "______ in simple English, this novel is easy for beginners to read.", "options": ["Writing", "Written", "To write", "Having written"], "answer": 1, "explain": "句意：這本小說是用簡單的英文寫成的，對初學者來說很容易閱讀。主詞 this novel 是「被寫」，分詞構句表被動須用過去分詞 Written (= Because it is written...)。(A) Writing、(D) Having written 表主動，好像小說自己在寫作；(C) To write 表目的，不合句意。故選 (B)。", "level": "B2", "topic": "participle clause (passive)"}, {"id": "M195", "type": "grammar", "q": "Life in the countryside is quite different ______ life in the city.", "options": ["with", "for", "from", "of"], "answer": 2, "explain": "句意：鄉村的生活和城市的生活很不一樣。be different from「與…不同」為固定搭配。(A) with、(B) for、(D) of 都不能與 different 搭配表達此義。故選 (C)。", "level": "B1", "topic": "different from"}, {"id": "M196", "type": "grammar", "q": "Jenny and her sister often share clothes and help ______ with homework.", "options": ["each other", "themselves", "herself", "theirs"], "answer": 0, "explain": "句意：Jenny 和她妹妹常常共穿衣服，也會互相幫忙寫功課。each other 表示「彼此、互相」，符合兩人互相幫忙的語意。(B) themselves 為反身代名詞，help themselves 意為「自行取用」或「幫自己」，不合語意；(C) herself 為單數，與兩人的主詞不一致；(D) theirs 為所有格代名詞，不能這樣當 help 的受詞。故選 (A)。", "level": "B1", "topic": "reciprocal pronoun"}, {"id": "M197", "type": "grammar", "q": "Jack talks ______ he knew everything about computers, but he actually knows very little.", "options": ["even if", "as if", "so that", "unless"], "answer": 1, "explain": "句意：Jack 說起話來彷彿他對電腦無所不知，但其實他懂得很少。as if「彷彿、好像」，後接與事實相反的假設時用過去式 (knew)。(A) even if「即使」表讓步；(C) so that「以便」表目的；(D) unless「除非」表條件，都不合語意。故選 (B)。", "level": "B2", "topic": "as if"}, {"id": "M198", "type": "grammar", "q": "Don't forget ______ off the lights when you leave the classroom.", "options": ["turning", "turn", "to turn", "turned"], "answer": 2, "explain": "句意：離開教室時別忘了關燈。forget + to V 表示「忘記去做（尚未做的事）」，forget + V-ing 表示「忘記曾做過某事」。此處是提醒對方待會要關燈，故用 to turn。(A) turning 表示「忘記已經關過燈」，不合語意；(B) turn 原形、(D) turned 過去式都不能接在 forget 之後。故選 (C)。", "level": "B1", "topic": "forget to V vs V-ing"}, {"id": "M199", "type": "grammar", "q": "So excited ______ about the trip that she couldn't fall asleep.", "options": ["was she", "she was", "did she", "she did"], "answer": 0, "explain": "句意：她對這趟旅行太興奮了，以致於睡不著。原句為 She was so excited about the trip that...，「So + 形容詞」移到句首時須倒裝成「be 動詞 + 主詞」，即 was she。(B) she was 未倒裝；(C) did she、(D) she did 誤用助動詞 did，句中動詞應為 be 動詞 was。故選 (A)。", "level": "B2", "topic": "inversion: so...that"}, {"id": "M200", "type": "grammar", "q": "This is the best movie ______ I have ever seen.", "options": ["what", "whom", "who", "that"], "answer": 3, "explain": "句意：這是我看過最好看的電影。先行詞被最高級 (the best) 修飾時，關係代名詞通常用 that。(A) what 不能接在先行詞之後；(B) whom、(C) who 用於指人，不能指 movie。故選 (D)。", "level": "B1", "topic": "relative that after superlatives"}, {"id": "M201", "type": "dialogue", "q": "A: Excuse me, do you have this T-shirt in a larger size?\nB: ______\nA: Great. I'll try it on.", "options": ["Sorry, we don't accept credit cards.", "Let me check. Yes, here's a large.", "It's on the second floor, next to the elevator.", "You can return it within seven days."], "answer": 1, "explain": "A 詢問這件 T 恤有沒有大一點的尺寸，B 回答「我查一下，有，這件是 L 號」，A 接著說要試穿，前後連貫。(A) 抱歉，我們不收信用卡，與尺寸無關；(C) 在二樓電梯旁，答非所問；(D) 七天內可退貨，與詢問尺寸無關。故選 (B)。", "level": "B1", "topic": "shopping"}, {"id": "M202", "type": "dialogue", "q": "A: Are you ready to order, sir?\nB: ______\nA: Sure. Take your time. I'll come back in a few minutes.", "options": ["Yes, I'd like the beef noodles, please.", "The bill comes to 450 dollars.", "I'm afraid the kitchen is closed.", "Not yet. Could I have a few more minutes?"], "answer": 3, "explain": "服務生問是否準備好點餐，客人回答「還沒，可以再給我幾分鐘嗎？」，服務生才會說「沒問題，慢慢來，我幾分鐘後再過來」。(A) 已經點了牛肉麵，服務生不會說慢慢來；(B) 帳單金額是 450 元，應由服務生說；(C) 廚房已打烊，也應是店員的話。故選 (D)。", "level": "B1", "topic": "restaurant"}, {"id": "M203", "type": "dialogue", "q": "A: Hello. May I speak to Ms. Chen, please?\nB: ______\nA: Could you tell her that Kevin called? I'll call back later.", "options": ["I'm sorry, she's out at the moment.", "Speaking. How can I help you?", "I'm afraid you have the wrong number.", "Yes. I'll put you through right away."], "answer": 0, "explain": "A 要找陳小姐，B 說「抱歉，她現在不在」，所以 A 才請 B 轉告「Kevin 打過電話，我晚點再打」。(B) Speaking 表示「我就是」，A 不需再留言；(C) 打錯電話了，A 不會請對方轉告；(D) 我馬上幫你轉接，A 也不必留言。故選 (A)。", "level": "B1", "topic": "phone call"}, {"id": "M204", "type": "dialogue", "q": "A: I'm afraid I won't be able to finish the report by Friday.\nB: ______\nA: Thanks. I'll make sure you have it first thing Monday morning.", "options": ["Then you'd better hand it in on Thursday.", "Congratulations! You did a great job.", "That's all right. Monday will be fine.", "I've already read your report twice."], "answer": 2, "explain": "A 表示週五前無法完成報告，B 回答「沒關係，週一也可以」，A 才會道謝並保證週一一早交出。(A) 那你最好週四交，與 A 的回應「週一交」矛盾；(B) 恭喜，你做得很好，報告尚未完成，不合理；(D) 我已經讀了你的報告兩次，報告還沒寫完，前後矛盾。故選 (C)。", "level": "B2", "topic": "workplace"}, {"id": "M205", "type": "dialogue", "q": "A: You look pale. What's wrong?\nB: ______\nA: You should see a doctor and get some rest.", "options": ["I've had a terrible headache since this morning.", "I just won first prize in the speech contest.", "I'm going to the movies with my friends.", "Nothing much. I feel great today."], "answer": 0, "explain": "A 說 B 臉色蒼白、問怎麼了，B 回答「我從早上就頭痛得很厲害」，A 才會建議看醫生並休息。(B) 剛贏得演講比賽冠軍，是好消息，不會被建議看醫生；(C) 要和朋友去看電影，與身體不適無關；(D) 沒什麼，我今天感覺很好，A 不會叫他去看醫生。故選 (A)。", "level": "B1", "topic": "health"}, {"id": "M206", "type": "dialogue", "q": "A: Good morning. May I see your passport and ticket, please?\nB: Here you are.\nA: ______\nB: Just this one suitcase. I'll carry the backpack on board.", "options": ["How long will you be staying there?", "Do you have any bags to check in?", "Would you like chicken or fish for dinner?", "Have you been to Japan before?"], "answer": 1, "explain": "這是機場報到櫃台的對話。B 回答「只有這個行李箱，背包我會帶上飛機」，可知 A 問的是「有要托運的行李嗎？」check in 托運（行李）。(A) 你會停留多久，應回答時間長短；(C) 晚餐要雞肉還是魚，是機上空服員的問題；(D) 你去過日本嗎，應回答 Yes／No 與經驗。故選 (B)。", "level": "B2", "topic": "airport"}, {"id": "M207", "type": "dialogue", "q": "A: Can I borrow your notes from yesterday's history class?\nB: ______\nA: Thanks a lot. I'll give them back to you tomorrow.", "options": ["No, I've never taken history.", "I'd rather not go to the library.", "Sorry, I was absent yesterday, too.", "Sure. Here you go."], "answer": 3, "explain": "A 想借昨天歷史課的筆記，B 回答「當然，拿去吧」，A 才會道謝並說明天歸還。(A) 我從沒修過歷史，與「昨天的歷史課」矛盾；(B) 我寧可不去圖書館，答非所問；(C) 抱歉，我昨天也缺席，表示沒有筆記可借，A 不會道謝並說要歸還。故選 (D)。", "level": "B1", "topic": "school"}, {"id": "M208", "type": "dialogue", "q": "A: Would you like to go hiking this Saturday?\nB: ______\nA: No problem. How about Sunday, then?", "options": ["Sure. What time shall we meet?", "Yes, I love hiking in the mountains.", "I'd love to, but I have to work that day.", "It took us three hours to get there."], "answer": 2, "explain": "A 邀 B 週六去健行，B 婉拒「我很想去，但那天要上班」，A 才會說「沒關係，那改週日如何？」。I'd love to, but... 是委婉拒絕邀約的常用說法。(A)、(B) 都是答應邀約，A 不需要改期；(D) 我們花了三小時才到那裡，是談過去的事，答非所問。故選 (C)。", "level": "B2", "topic": "making plans"}, {"id": "M209", "type": "dialogue", "q": "A: How much is this backpack?\nB: ______\nA: That's a little expensive. Do you have anything cheaper?", "options": ["It's made of leather.", "It's 2,500 dollars.", "It comes in black and blue.", "You can pay at the counter."], "answer": 1, "explain": "A 問背包多少錢，B 回答「2,500 元」，A 才會說「有點貴，有沒有便宜一點的？」。(A) 是皮革做的，回答材質；(C) 有黑色和藍色，回答顏色；(D) 可以到櫃台結帳，回答付款地點，皆未回答價錢。故選 (B)。", "level": "B1", "topic": "shopping"}, {"id": "M210", "type": "dialogue", "q": "A: Front desk. How may I help you?\nB: ______\nA: I'm sorry about that. I'll send someone up to fix it right away.", "options": ["The air conditioner in my room isn't working.", "I'd like to book a table for two at seven.", "Could you tell me where the nearest bank is?", "I'd like to check out, please."], "answer": 0, "explain": "飯店櫃台問需要什麼協助，房客說「我房間的冷氣壞了」，櫃台才會道歉並說「馬上派人上去修理」。(B) 想訂七點兩人的位子，是餐廳訂位；(C) 詢問最近的銀行在哪；(D) 要辦理退房，三者都不需要派人修理東西。故選 (A)。", "level": "B2", "topic": "hotel"}, {"id": "M211", "type": "dialogue", "q": "A: Excuse me. Could we have the check, please?\nB: ______\nA: Thank you. Can I pay by credit card?", "options": ["Sorry, we don't have any tables available.", "Would you like something to drink first?", "Certainly. Here you are.", "The soup of the day is tomato."], "answer": 2, "explain": "客人要求結帳（check 帳單），服務生回答「當然，這是您的帳單」，客人接著問能否刷卡。(A) 抱歉沒有空位，是客人剛進門時的對話；(B) 要不要先喝點什麼，是點餐時的問題；(D) 今日例湯是番茄湯，與結帳無關。故選 (C)。", "level": "B1", "topic": "restaurant"}, {"id": "M212", "type": "dialogue", "q": "A: Do you think we could move the meeting to Thursday afternoon?\nB: ______\nA: Then let's make it Friday morning instead.", "options": ["Sure. Thursday afternoon works for me.", "The meeting lasted about two hours.", "I'll take notes during the meeting.", "I'm afraid I'll be visiting a client then."], "answer": 3, "explain": "A 提議把會議改到週四下午，B 回答「恐怕我那時要去拜訪客戶」，所以 A 才改提「那就改週五早上吧」。(A) 週四下午我可以，A 不需要再改時間；(B) 會議開了約兩小時，是談過去的會議；(C) 我會在會議中做筆記，未回應時間安排。故選 (D)。", "level": "B2", "topic": "workplace"}, {"id": "M213", "type": "dialogue", "q": "A: Excuse me. How can I get to the train station?\nB: ______\nA: Thank you very much.", "options": ["Go straight for two blocks and turn left. You can't miss it.", "The train leaves at 3:15.", "I usually take the train to work.", "No, I don't know when it opens."], "answer": 0, "explain": "A 問路「要怎麼去火車站？」，B 指路「直走兩個街區再左轉，你一定看得到」，A 道謝。You can't miss it. 表示「很好找」。(B) 火車三點十五分開，回答時間；(C) 我通常搭火車上班，答非所問；(D) 我不知道幾點開門，A 問的不是開放時間。故選 (A)。", "level": "B1", "topic": "directions"}, {"id": "M214", "type": "dialogue", "q": "A: I'm really sorry, but I spilled coffee on the book you lent me.\nB: ______\nA: That's very kind of you. I'll buy you a new one anyway.", "options": ["You should have been more careful. I want it back now.", "Don't worry about it. It's just an old book.", "I'd love a cup of coffee, thanks.", "I haven't finished reading it either."], "answer": 1, "explain": "A 道歉把咖啡灑在借來的書上，B 寬容地說「別擔心，只是一本舊書」，A 才會說「你人真好，我還是會買本新的給你」。(A) 你應該更小心，我現在就要拿回來，語氣是責備，A 不會說 That's very kind of you；(C) 我想喝杯咖啡，答非所問；(D) 我也還沒讀完，與道歉無關。故選 (B)。", "level": "B2", "topic": "apologizing"}, {"id": "M215", "type": "dialogue", "q": "A: Hello. Is this Lucky Pizza?\nB: ______\nA: Oh, I'm sorry. I must have dialed the wrong number.", "options": ["Yes. What would you like to order?", "Hold on. I'll get him for you.", "No, I'm afraid this is a private home.", "Sure. We deliver in 30 minutes."], "answer": 2, "explain": "A 問「這是幸運披薩嗎？」，B 回答「不是，這裡是住家」，A 才會道歉說「我一定是撥錯號碼了」。(A)、(D) 表示確實是披薩店，A 不會說打錯；(B) 稍等，我去叫他來，與詢問店名不符，A 也不會說撥錯號碼。故選 (C)。", "level": "B1", "topic": "phone call"}, {"id": "M216", "type": "dialogue", "q": "A: I'd like something for a sore throat.\nB: ______\nA: No, I don't. I'm not allergic to anything.", "options": ["Take one tablet after each meal.", "How long have you had a sore throat?", "You can find it in aisle five.", "Do you have any allergies to medicine?"], "answer": 3, "explain": "在藥局，A 想買治喉嚨痛的藥，藥師問「你對藥物有過敏嗎？」，A 回答「沒有，我對任何東西都不過敏」。(A) 每餐飯後吃一顆，是用藥指示，A 不會回答 No, I don't；(B) 喉嚨痛多久了，應回答一段時間；(C) 在第五排走道，與過敏無關。故選 (D)。", "level": "B2", "topic": "pharmacy"}, {"id": "M217", "type": "dialogue", "q": "A: Have you finished your science project yet?\nB: ______\nA: Me neither. Let's work on it together after school.", "options": ["Yes, I handed it in yesterday.", "Not yet. I still need to make the poster.", "Science is my favorite subject.", "I'll go to the science museum tomorrow."], "answer": 1, "explain": "A 問科學專題做完沒，B 回答「還沒，我還要做海報」，A 說「我也還沒（Me neither），放學後一起做吧」。Me neither 用來附和否定句。(A) 已經交了，與 Me neither 不符；(C) 自然是我最喜歡的科目，答非所問；(D) 明天要去科學博物館，未回答是否完成。故選 (B)。", "level": "B1", "topic": "school"}, {"id": "M218", "type": "dialogue", "q": "A: We're having a barbecue at our place on Sunday. Can you come?\nB: ______\nA: Great! See you then. Just bring yourself.", "options": ["I'd be glad to. Should I bring anything?", "Sorry, I've already made other plans.", "I had a barbecue with my family last week.", "That's very kind of you, but I'm busy that day."], "answer": 0, "explain": "A 邀請 B 週日來家裡烤肉，B 回答「我很樂意，需要帶什麼嗎？」，A 說「太好了，到時見，人來就好（Just bring yourself）」。(B)、(D) 都是婉拒邀請，A 不會說 Great! See you then；(C) 上週和家人烤過肉了，未回應邀約。故選 (A)。", "level": "B2", "topic": "invitation"}, {"id": "M219", "type": "dialogue", "q": "A: That'll be 380 dollars altogether.\nB: ______\nA: Sorry, we only take cash.", "options": ["Here's 400. Keep the change.", "Could you wrap it as a gift?", "Do you have it in red?", "Can I pay with my credit card?"], "answer": 3, "explain": "店員說總共 380 元，顧客問「可以刷信用卡嗎？」，店員回答「抱歉，我們只收現金」。(A) 這是 400 元，不用找了，已用現金付款，店員不會說只收現金；(B) 可以包裝成禮物嗎；(C) 有紅色的嗎，兩者都與付款方式無關。故選 (D)。", "level": "B1", "topic": "shopping"}, {"id": "M220", "type": "dialogue", "q": "A: I'd like to book a double room for this weekend.\nB: ______\nA: Two nights, Friday and Saturday.", "options": ["Would you like a window seat or an aisle seat?", "Breakfast is served from seven to ten.", "How many nights will you be staying?", "Your room is on the fifth floor."], "answer": 2, "explain": "A 要訂本週末的雙人房，櫃台問「您要住幾晚？」，A 回答「兩晚，週五和週六」。(A) 靠窗或靠走道座位，是訂機票或車票的問題；(B) 早餐供應時間是七點到十點；(D) 你的房間在五樓，是入住時的說明，皆無法接 Two nights。故選 (C)。", "level": "B2", "topic": "hotel"}, {"id": "M221", "type": "dialogue", "q": "A: Is that for here or to go?\nB: ______\nA: OK. Your order will be ready in five minutes.", "options": ["To go, please.", "I'll have a large coffee.", "It's too spicy for me.", "Yes, it's delicious."], "answer": 0, "explain": "店員問「內用還是外帶？」（for here or to go），顧客回答「外帶，謝謝」。(B) 我要一杯大杯咖啡，是點餐內容，沒有回答內用或外帶；(C) 對我來說太辣了；(D) 是的，很好吃，兩者都是吃過後的評價，不合情境。故選 (A)。", "level": "B1", "topic": "fast food"}, {"id": "M222", "type": "dialogue", "q": "A: The printer is jammed again. Do you know how to fix it?\nB: ______\nA: Never mind. I'll ask someone from the IT department.", "options": ["Sure. Just open this door and pull out the paper.", "I printed fifty copies this morning.", "Sorry, I have no idea how it works.", "Yes, it's a brand-new printer."], "answer": 2, "explain": "A 說印表機又卡紙了，問 B 會不會修，B 回答「抱歉，我完全不知道它怎麼運作」，A 才說「沒關係，我去問資訊部門的人」。jammed 卡住的。(A) 教 A 如何排除卡紙，A 不需再找資訊部門；(B) 我今早印了五十份，答非所問；(D) 是的，它是全新的印表機，未回答會不會修。故選 (C)。", "level": "B2", "topic": "workplace"}, {"id": "M223", "type": "dialogue", "q": "A: It looks like it's going to rain.\nB: ______\nA: Good idea. I'll grab mine, too.", "options": ["Let's go swimming at the beach.", "We'd better take our umbrellas.", "The weather was nice yesterday.", "I like rainy days the most."], "answer": 1, "explain": "A 說看起來快下雨了，B 建議「我們最好帶傘」，A 回答「好主意，我也去拿我的（傘）」，mine 指 my umbrella。(A) 去海邊游泳，與要下雨不合；(C) 昨天天氣很好，不是建議；(D) 我最喜歡雨天，不是建議，也無法對應 mine。故選 (B)。", "level": "B1", "topic": "weather"}, {"id": "M224", "type": "dialogue", "q": "A: Excuse me. Would you mind turning down the music? I'm trying to study.\nB: ______\nA: Thanks. I appreciate it.", "options": ["Yes, I'd love to listen to music.", "Sure. I'll turn it up for you.", "What kind of music do you like?", "Oh, sorry. I didn't realize it was so loud."], "answer": 3, "explain": "A 禮貌地請 B 把音樂關小聲（turn down），B 道歉說「抱歉，我沒發現這麼大聲」，表示會配合，A 才道謝。(A) 我很樂意聽音樂，答非所問；(B) turn up 是「調大聲」，與 A 的請求相反；(C) 你喜歡哪種音樂，未回應請求。故選 (D)。", "level": "B2", "topic": "polite request"}, {"id": "M225", "type": "dialogue", "q": "A: How did you do on the math test?\nB: ______\nA: Congratulations! All your hard work paid off.", "options": ["I got 95. I can't believe it!", "I failed it again.", "The test is next Monday.", "I didn't study at all."], "answer": 0, "explain": "A 問數學考得如何，B 回答「我考了 95 分，真不敢相信」，A 才會恭喜並說「你的努力有了回報（paid off）」。(B) 我又不及格了，A 不會說恭喜；(C) 考試在下週一，表示還沒考；(D) 我完全沒讀書，與「努力有回報」矛盾。故選 (A)。", "level": "B1", "topic": "school"}, {"id": "M226", "type": "dialogue", "q": "A: Good afternoon, Sunrise Travel. How can I help you?\nB: I'd like to change the date of my tour to Hualien.\nA: ______\nB: It's HT0825. I booked the tour last week.", "options": ["Hualien is famous for its beautiful scenery.", "What date would you like to change it to?", "Certainly. May I have your booking number, please?", "The tour bus leaves at eight in the morning."], "answer": 2, "explain": "B 打電話到旅行社想更改花蓮行程的日期，A 回答「當然，可以請您提供訂位編號嗎？」，B 才會報出編號 HT0825 並說明上週訂的。booking number 訂位編號。(A) 花蓮以美麗的風景聞名，答非所問；(B) 您想改到哪一天，B 應回答日期，而不是編號；(D) 遊覽車早上八點出發，未回應更改日期的需求，B 也不會接著報出編號。故選 (C)。", "level": "B2", "topic": "phone call"}, {"id": "M227", "type": "dialogue", "q": "A: I've gained five kilograms this year.\nB: ______\nA: You're right. I'll start jogging tomorrow.", "options": ["You should eat more snacks.", "Maybe you should exercise more.", "Congratulations on your new job.", "I've never been to the gym."], "answer": 1, "explain": "A 說今年胖了五公斤，B 建議「也許你該多運動」，A 回答「你說得對，我明天開始慢跑」。(A) 你應該多吃零食，與減重相反；(C) 恭喜你找到新工作，答非所問；(D) 我從沒去過健身房，不是建議，A 不會說 You're right。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M228", "type": "dialogue", "q": "A: I'd like to return this jacket. The zipper is broken.\nB: ______\nA: Yes, here it is. I bought it last Tuesday.", "options": ["Would you like to try a larger size?", "This jacket is on sale today.", "We close at nine on weekdays.", "Do you have the receipt with you?"], "answer": 3, "explain": "A 因拉鍊壞了要退外套，店員問「您有帶收據嗎？」，A 回答「有，在這裡，我上週二買的」。receipt 收據。(A) 要不要試大一號，與拉鍊壞掉無關；(B) 這件外套今天特價；(C) 我們平日九點打烊，三者都接不上 Yes, here it is。故選 (D)。", "level": "B2", "topic": "shopping"}, {"id": "M229", "type": "dialogue", "q": "A: Let's meet in front of the theater at 6:30.\nB: ______\nA: OK. Then let's make it seven.", "options": ["Could we make it a little later? I finish work at 6:30.", "Great. See you at 6:30.", "The movie was really boring.", "I don't like going to the theater alone."], "answer": 0, "explain": "A 約六點半在戲院前碰面，B 說「能晚一點嗎？我六點半才下班」，A 才改說「好，那就七點吧」。make it 在此指「約定（時間）」。(B) 好，六點半見，A 不需改時間；(C) 那部電影很無聊，是看完後的評論；(D) 我不喜歡一個人去戲院，與約時間無關。故選 (A)。", "level": "B1", "topic": "making plans"}, {"id": "M230", "type": "dialogue", "q": "A: Excuse me, waiter. This steak is overcooked. I asked for medium rare.\nB: ______\nA: Thank you. I'd appreciate that.", "options": ["Medium rare is our most popular choice.", "I'm terribly sorry. I'll have the chef cook you another one.", "Would you like some dessert after that?", "Our steaks come from Australia."], "answer": 1, "explain": "A 抱怨牛排煎過熟，他點的是三分熟（medium rare），服務生道歉並說「我請主廚再幫您煎一份」，A 才會說「謝謝，那就麻煩了」。(A) 三分熟是最受歡迎的選擇，未處理客訴；(C) 之後要甜點嗎，忽略抱怨；(D) 我們的牛排來自澳洲，答非所問。故選 (B)。", "level": "B2", "topic": "restaurant"}, {"id": "M231", "type": "dialogue", "q": "A: One ticket to Kaohsiung, please.\nB: ______\nA: One-way, please. I'm not coming back until next month.", "options": ["The train is leaving from Platform 3.", "It takes about two hours.", "Would you like a window seat?", "One-way or round-trip?"], "answer": 3, "explain": "A 要買一張到高雄的票，售票員問「單程還是來回？」，A 回答「單程，我下個月才回來」。(A) 火車從第三月台出發；(B) 車程大約兩小時；(C) 要靠窗座位嗎，三者都無法接 One-way, please。故選 (D)。", "level": "B1", "topic": "travel"}, {"id": "M232", "type": "dialogue", "q": "A: Why do you want to work for our company?\nB: ______\nA: I see. Your experience in design will be very useful here.", "options": ["I'd like to know how much I will be paid first.", "I'm not sure. My parents told me to apply.", "I've always admired your products, and I think my design skills would fit your team.", "I can start working next Monday."], "answer": 2, "explain": "面試官問為什麼想來公司工作，應徵者回答「我一直很欣賞貴公司的產品，也認為我的設計能力適合貴團隊」，面試官才會說「你的設計經驗在這裡會很有用」。(A) 我想先知道薪水多少，沒回答問題且不得體；(B) 不確定，是父母叫我應徵的，沒有提到設計；(D) 我下週一可以上班，回答的是到職日。故選 (C)。", "level": "B2", "topic": "job interview"}, {"id": "M233", "type": "dialogue", "q": "A: Excuse me. Is this seat taken?\nB: ______\nA: Thanks. I'll sit here, then.", "options": ["No, go ahead.", "Yes, my friend is sitting here.", "Sorry, I don't have the time.", "It's very comfortable."], "answer": 0, "explain": "A 問「這個位子有人坐嗎？」（Is this seat taken?），B 回答「沒有，請坐」，A 才會道謝並坐下。(B) 有，我朋友坐這裡，A 就不能坐；(C) 抱歉，我不知道現在幾點（I don't have the time），答非所問；(D) 它很舒服，沒有回答是否有人坐。故選 (A)。", "level": "B1", "topic": "polite request"}, {"id": "M234", "type": "dialogue", "q": "A: How long have you been coughing like this?\nB: ______\nA: I see. Let me listen to your chest.", "options": ["Three times a day, after meals.", "For about a week now.", "I'll take the medicine right away.", "I'll be fine in a few days."], "answer": 1, "explain": "醫生問「你像這樣咳嗽多久了？」（How long 問持續時間），病人回答「到現在大約一週了」，醫生接著要聽診胸部。(A) 一天三次、飯後，是回答頻率或服藥方式；(C) 我馬上吃藥，答非所問；(D) 我過幾天就會好，是推測未來，不是持續時間。故選 (B)。", "level": "B2", "topic": "health"}, {"id": "M235", "type": "dialogue", "q": "A: How many books can I borrow at a time?\nB: ______\nA: And how long can I keep them?", "options": ["The library opens at eight.", "You can't eat in the library.", "Up to five books.", "For two weeks."], "answer": 2, "explain": "A 問一次可以借幾本書，館員回答「最多五本」，A 再問可以借多久。(A) 圖書館八點開門，回答時間；(B) 圖書館內不能吃東西，答非所問；(D) 兩週，是回答「可以借多久」，應在 A 的下一個問題之後才出現。故選 (C)。", "level": "B1", "topic": "library"}, {"id": "M236", "type": "dialogue", "q": "A: I'm bored. What should we do this afternoon?\nB: ______\nA: Sounds good. I've wanted to see that exhibition for a while.", "options": ["Why don't we go to the art museum?", "Let's stay home and watch TV.", "I went to the museum last week.", "I'm too tired to go out."], "answer": 0, "explain": "A 說很無聊、問下午要做什麼，B 提議「我們何不去美術館？」，A 回答「好主意，我想看那個展覽很久了」。Why don't we...? 用來提出建議。(B) 待在家看電視，與「展覽」無關；(C) 我上週去過博物館，不是提議；(D) 我太累了不想出門，A 不會說 Sounds good。故選 (A)。", "level": "B1", "topic": "making plans"}, {"id": "M237", "type": "dialogue", "q": "A: Can I help you?\nB: ______\nA: All right. Let me know if you need anything.", "options": ["Yes, I'm looking for a pair of running shoes.", "Yes, please. How much is this?", "No, I can't help you.", "No, thanks. I'm just looking."], "answer": 3, "explain": "店員問「需要幫忙嗎？」，顧客回答「不用了，謝謝，我只是看看」，店員說「好的，需要什麼再告訴我」。(A)、(B) 都是提出需求，店員應會直接協助或報價，而不是說有需要再叫我；(C) 我不能幫你，誤解了店員的問題。故選 (D)。", "level": "B1", "topic": "shopping"}, {"id": "M238", "type": "dialogue", "q": "A: I heard Jenny is in the hospital.\nB: ______\nA: Me too. Let's visit her after work.", "options": ["Yes, she just got a promotion.", "Really? I hope she gets well soon.", "I'm glad to hear that.", "Yes, she's on vacation in Japan."], "answer": 1, "explain": "A 說聽說 Jenny 住院了，B 回答「真的嗎？希望她早日康復」，A 說「我也是（希望），下班後去探望她吧」。(A) 她剛升職，與住院無關；(C) 我很高興聽到這消息，對住院的壞消息不恰當；(D) 她在日本度假，與住院矛盾。故選 (B)。", "level": "B2", "topic": "workplace"}, {"id": "M239", "type": "dialogue", "q": "A: Good evening. Ocean Restaurant.\nB: ______\nA: Of course. For what time?", "options": ["Can I have the check, please?", "The food here is excellent.", "I'd like to reserve a table for four tomorrow night.", "I've been waiting for half an hour."], "answer": 2, "explain": "這是打電話到餐廳的對話，B 說「我想訂明晚四人的位子」，A 回答「當然，請問幾點？」。reserve a table 訂位。(A) 請給我帳單，是在店內用餐後說的；(B) 這裡的食物很棒，是評價；(D) 我已經等了半小時，是抱怨，三者都接不上 For what time?。故選 (C)。", "level": "B1", "topic": "restaurant"}, {"id": "M240", "type": "dialogue", "q": "A: Excuse me. I think I'm lost. Where are we on this map?\nB: ______\nA: Oh, I see. So the museum is just around the corner.", "options": ["We're right here, near the post office.", "You can buy a map at the bookstore.", "Sorry, I'm a stranger here myself.", "It's a beautiful city, isn't it?"], "answer": 0, "explain": "A 迷路了，問我們在地圖上的哪裡，B 指著地圖說「我們就在這裡，郵局附近」，A 才明白「所以博物館就在轉角」。(B) 可以在書店買地圖，A 已經有地圖；(C) 抱歉，我也不是本地人，A 不會說 Oh, I see；(D) 這城市很美，對吧，答非所問。故選 (A)。", "level": "B2", "topic": "travel"}, {"id": "M241", "type": "dialogue", "q": "A: Hello? Can you hear me?\nB: ______\nA: Sorry, I'm on the train. I'll call you back later.", "options": ["Yes, loud and clear.", "Thanks for calling.", "I'll be home at eight.", "You're breaking up. I can hardly hear you."], "answer": 3, "explain": "A 問「聽得到我說話嗎？」，B 回答「你的聲音斷斷續續，我幾乎聽不到」，A 才解釋自己在火車上、晚點再回電。breaking up 指通話訊號不穩、斷斷續續。(A) 聽得很清楚，A 不需要晚點再打；(B) 謝謝來電，通常用於結束通話；(C) 我八點會到家，答非所問。故選 (D)。", "level": "B2", "topic": "phone call"}, {"id": "M242", "type": "dialogue", "q": "A: Who's going to give the presentation for our group?\nB: ______\nA: Good. You're the best speaker among us.", "options": ["I don't think we need a presentation.", "I'll do it if nobody else wants to.", "The presentation was last Friday.", "I'm too nervous to speak in public."], "answer": 1, "explain": "A 問誰要代表小組上台報告，B 說「如果沒人想做，我來吧」，A 回答「很好，你是我們之中最會說話的人」。(A) 我覺得不需要報告，A 不會說 Good；(C) 報告是上週五，表示已經結束；(D) 我太緊張不敢公開演講，與 A 稱讚他是最佳講者矛盾。故選 (B)。", "level": "B1", "topic": "school"}, {"id": "M243", "type": "dialogue", "q": "A: These apples look fresh. How much are they?\nB: ______\nA: I'll take six, then.", "options": ["They come from Lishan.", "We've sold out of apples.", "Three for 100 dollars.", "They're not ripe yet."], "answer": 2, "explain": "A 問蘋果多少錢，老闆回答「三顆一百元」，A 說「那我買六顆」。(A) 產自梨山，回答產地不是價錢；(B) 蘋果賣完了，A 就買不到；(D) 還沒熟，沒回答價錢，A 也不會接著買。故選 (C)。", "level": "B1", "topic": "shopping"}, {"id": "M244", "type": "dialogue", "q": "A: Your bags look heavy. Would you like me to help you with them?\nB: ______\nA: No problem. Where should I put them?", "options": ["That's very kind of you. Thanks.", "No, thanks. I can manage.", "I bought them at the department store.", "Yes, they're very light."], "answer": 0, "explain": "A 主動表示要幫忙提重物，B 接受並道謝「你真好心，謝謝」，A 回答「不客氣，要放在哪裡？」。(B) 不用了，我自己可以，A 就不會問放哪裡；(C) 我在百貨公司買的，答非所問；(D) 是的，它們很輕，與 A 說袋子看起來很重矛盾，也沒有接受幫忙。故選 (A)。", "level": "B2", "topic": "offering help"}, {"id": "M245", "type": "dialogue", "q": "A: What happened to your leg?\nB: ______\nA: That's terrible. Does it still hurt?", "options": ["I bought new jeans yesterday.", "I hurt it while playing basketball.", "My legs are longer than yours.", "I'm going to the hospital to visit my aunt."], "answer": 1, "explain": "A 問 B 的腳怎麼了，B 回答「我打籃球時受傷了」，A 說「真糟糕，還會痛嗎？」。(A) 我昨天買了新牛仔褲；(C) 我的腿比你長；(D) 我要去醫院探望阿姨，三者都沒有說明腳受傷，A 不會問還痛不痛。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M246", "type": "dialogue", "q": "A: Could you lend me your laptop for the meeting this afternoon?\nB: ______\nA: That's OK. I'll ask Tom instead.", "options": ["Sure. Just bring it back by five.", "The meeting starts at two o'clock.", "I bought it two years ago.", "Sorry, I need it for my own presentation."], "answer": 3, "explain": "A 想借筆電開會，B 婉拒「抱歉，我自己的簡報要用」，A 才說「沒關係，我改問 Tom」。(A) 答應出借，A 不需改問別人；(B) 會議兩點開始，未回應借用請求；(C) 我兩年前買的，答非所問。故選 (D)。", "level": "B2", "topic": "workplace"}, {"id": "M247", "type": "dialogue", "q": "A: Tomorrow is Mom's birthday. What should we get her?\nB: ______\nA: Good idea. She spends hours in the garden every weekend.", "options": ["Her birthday was last month.", "She's 45 years old.", "How about a set of gardening tools?", "I've already eaten the cake."], "answer": 2, "explain": "A 問明天媽媽生日要送什麼，B 提議「送一套園藝工具如何？」，A 回答「好主意，她每個週末都在花園待好幾個小時」。How about...? 用來提出建議。(A) 她的生日是上個月，與 A 說「明天生日」矛盾；(B) 她 45 歲，沒有提出建議；(D) 我已經把蛋糕吃了，答非所問。故選 (C)。", "level": "B1", "topic": "family"}, {"id": "M248", "type": "dialogue", "q": "A: What's the purpose of your visit?\nB: ______\nA: Thank you. Enjoy your stay.", "options": ["I'm here on vacation.", "I'll be staying for ten days.", "I came by plane.", "I have nothing to declare."], "answer": 0, "explain": "入境審查時，官員問「您來訪的目的是什麼？」（purpose 目的），旅客回答「我來度假」。(B) 我會停留十天，回答停留時間；(C) 我搭飛機來，回答交通方式；(D) 我沒有東西要申報，是海關申報的用語，三者皆未回答目的。故選 (A)。", "level": "B1", "topic": "immigration"}, {"id": "M249", "type": "dialogue", "q": "A: Why are you late for class again?\nB: ______\nA: Then you should get up earlier tomorrow.", "options": ["I always come to school by bike.", "I'm sorry. I overslept this morning.", "Because the class is very interesting.", "I'll finish my homework tonight."], "answer": 1, "explain": "老師問 B 為什麼又遲到，B 回答「對不起，我今天早上睡過頭了（overslept）」，老師才說「那你明天應該早點起床」。(A) 我總是騎腳踏車上學，未說明遲到原因；(C) 因為這堂課很有趣，不是遲到的理由；(D) 我今晚會寫完作業，答非所問。故選 (B)。", "level": "B1", "topic": "school"}, {"id": "M250", "type": "dialogue", "q": "A: Everything on the menu looks good. What do you recommend?\nB: ______\nA: Hmm, I'm not a big fan of spicy food. Is there anything milder?", "options": ["Here's your change.", "The restrooms are over there.", "Would you like your coffee now or later?", "Our spicy chicken is very popular."], "answer": 3, "explain": "客人請服務生推薦菜色，服務生說「我們的辣子雞很受歡迎」，客人才說「我不太愛吃辣，有沒有比較不辣的？」。milder 較溫和的、較不辣的。(A) 這是找您的零錢，是結帳時說的；(B) 洗手間在那邊，答非所問；(C) 咖啡要現在上還是待會上，沒有推薦菜色，也與辣無關。故選 (D)。", "level": "B2", "topic": "restaurant"}, {"id": "M251", "type": "dialogue", "q": "A: That'll be 285 dollars. Would you like a plastic bag?\nB: ______ I brought my own.\nA: Great. Thank you for helping the environment.", "options": ["Yes, two bags, please.", "Here's your receipt.", "No, thanks.", "Sorry, I only have cash."], "answer": 2, "explain": "店員告知金額並詢問是否需要塑膠袋；B 接著說「我自己有帶（袋子）」，店員也感謝 B 愛護環境，可知 B 婉拒了塑膠袋。(C)「不用了，謝謝」最恰當。(A)「好，請給我兩個袋子」與自備購物袋矛盾；(B)「這是你的收據」應是店員說的話；(D)「抱歉，我只有現金」與要不要袋子無關。故選 (C)。", "level": "B1", "topic": "shopping"}, {"id": "M252", "type": "dialogue", "q": "A: Excuse me. Do you have Wi-Fi here?\nB: ______ The password is printed on your receipt.", "options": ["Yes, it's free for customers.", "No, we don't take credit cards.", "Sorry, we're out of milk.", "It's on the second floor."], "answer": 0, "explain": "顧客問店裡有沒有 Wi-Fi；店員接著說「密碼印在你的收據上」，可知店裡有提供 Wi-Fi。(A)「有，顧客可以免費使用」最合理。(B)「不，我們不收信用卡」答非所問；(C)「抱歉，牛奶賣完了」與 Wi-Fi 無關；(D)「在二樓」回答的是位置，與提供密碼不連貫。故選 (A)。", "level": "B1", "topic": "cafe"}, {"id": "M253", "type": "dialogue", "q": "A: Where to, miss?\nB: ______\nA: OK. It'll take about twenty minutes if the traffic is light.", "options": ["Keep the change.", "It's 300 dollars.", "I'm from Kaohsiung.", "Taipei Main Station, please."], "answer": 3, "explain": "「Where to?」是計程車司機問乘客「要去哪裡？」的常用說法，應回答目的地；司機接著說路況順暢的話約需二十分鐘。(D)「請到臺北車站」最恰當。(A)「不用找了」是下車付款時說的話；(B)「要 300 元」是司機告知車資的話；(C)「我來自高雄」回答的是出身地，不是目的地。故選 (D)。", "level": "B1", "topic": "taxi"}, {"id": "M254", "type": "dialogue", "q": "A: I'd like to send this package to Japan.\nB: ______\nA: By airmail, please. I want it to get there quickly.", "options": ["What's inside the box?", "How would you like to send it?", "Where is the post office?", "When did you receive it?"], "answer": 1, "explain": "A 在郵局要把包裹寄到日本；A 接著回答「寄航空，我希望快點寄到」，可知郵局人員問的是寄送方式。(B)「您想用什麼方式寄？」最合理。(A)「箱子裡裝什麼？」應回答物品內容；(C)「郵局在哪裡？」A 已經在郵局，答句也不符；(D)「你什麼時候收到的？」與寄件無關。故選 (B)。", "level": "B1", "topic": "post office"}, {"id": "M255", "type": "dialogue", "q": "A: Guess what? I passed my driving test!\nB: ______ You must be so happy.", "options": ["Congratulations!", "Better luck next time.", "Take care.", "That's too bad."], "answer": 0, "explain": "A 興奮地說自己通過了駕照考試；B 接著說「你一定很開心」，可知 B 在祝賀對方。(A)「恭喜！」最恰當。(B)「下次運氣會更好」用於安慰失敗的人；(C)「保重」是道別或叮嚀用語；(D)「那真糟糕」用於回應壞消息，皆不符合語境。故選 (A)。", "level": "B1", "topic": "good news"}, {"id": "M256", "type": "dialogue", "q": "A: Could you make thirty copies of this handout before the meeting?\nB: ______\nA: Yes, please. Staple them in the top left corner.", "options": ["The copy machine is on the third floor.", "I've already read it twice.", "Sure. Would you like them stapled?", "No, thanks. I don't need a copy."], "answer": 2, "explain": "A 請 B 在開會前把講義印三十份；A 接著說「好，麻煩釘在左上角」，可知 B 問了要不要裝訂。(C)「沒問題，要幫你釘起來嗎？」最合理，staple 意為「用釘書機釘」。(A)「影印機在三樓」無法用 Yes, please 回應；(B)「我已經讀過兩次了」答非所問；(D)「不用了，我不需要一份」誤以為對方要給自己講義，與請託不符。故選 (C)。", "level": "B2", "topic": "office tasks"}, {"id": "M257", "type": "dialogue", "q": "A: You look sad. What's wrong?\nB: My dog, Lucky, died last week. He was fourteen.\nA: ______ He was such a sweet dog.", "options": ["Good for you.", "I'm so sorry to hear that.", "Congratulations!", "No wonder you look happy."], "answer": 1, "explain": "B 說家裡的狗 Lucky 上週過世了；A 接著說「牠是隻很貼心的狗」，可知 A 在表達同情與安慰。(B)「聽到這件事我很難過」最恰當。(A)「真替你高興」、(C)「恭喜！」都用於回應好消息；(D)「難怪你看起來很開心」與 B 看起來很難過矛盾。故選 (B)。", "level": "B1", "topic": "sympathy"}, {"id": "M258", "type": "dialogue", "q": "A: Reception. What can I do for you?\nB: ______\nA: Certainly. We'll call your room at six.", "options": ["I'd like to check out now.", "Could you send someone to fix the TV?", "What time is breakfast served?", "Could I have a wake-up call at six tomorrow morning?"], "answer": 3, "explain": "B 打電話到飯店櫃檯；櫃檯人員回答「沒問題，我們六點會打電話到您房間」，可知 B 要求晨喚服務。(D)「明天早上六點可以打電話叫我起床嗎？」（wake-up call 晨喚電話）最合理。(A)「我現在要退房」不需要隔天早上打電話；(B)「可以派人來修電視嗎？」櫃檯應回答會派人上樓；(C)「早餐幾點供應？」應回答供餐時間，而不是打電話到房間。故選 (D)。", "level": "B2", "topic": "hotel"}, {"id": "M259", "type": "dialogue", "q": "A: Oops! Sorry, I didn't see you there.\nB: ______ It was my fault, too. I was looking at my phone.", "options": ["That's all right.", "You're welcome.", "Yes, you did.", "Nice to see you."], "answer": 0, "explain": "A 撞到 B 後道歉；B 接著說「我也有錯，我剛剛在看手機」，可知 B 並不介意。(A)「沒關係」最恰當。(B)「不客氣」用於回應道謝；(C)「對，你明明看到了」與 A 說的話不合，也與 B 承認自己有錯矛盾；(D)「很高興見到你」是寒暄用語，不適合回應道歉。故選 (A)。", "level": "B1", "topic": "apology"}, {"id": "M260", "type": "dialogue", "q": "A: Do you have a table for three?\nB: I'm afraid we're full right now. ______\nA: That's fine. We'll wait. Could you put our name on the list?", "options": ["Please come back tomorrow.", "Would you like to order now?", "There should be a table in about fifteen minutes.", "Enjoy your meal."], "answer": 2, "explain": "A 想要三人桌，但餐廳目前客滿；A 接著說「沒關係，我們等，請幫我們登記候位」，可知 B 告知了大約要等多久。(C)「大約十五分鐘後應該會有空位」最合理。(A)「請明天再來」表示今天沒辦法，A 不會說要等；(B)「現在要點餐嗎？」還沒入座無法點餐；(D)「請慢用」是上菜時的用語。故選 (C)。", "level": "B2", "topic": "restaurant"}, {"id": "M261", "type": "dialogue", "q": "A: Excuse me. Does this bus go to the zoo?\nB: ______ You need to take No. 5. The stop is across the street.", "options": ["Yes, it stops right in front of the zoo.", "Sure. Hop on.", "It costs 15 dollars.", "No, I'm afraid it doesn't."], "answer": 3, "explain": "A 問這班公車有沒有到動物園；B 接著說「你要搭 5 號，站牌在對街」，可知這班車不到動物園。(D)「不，恐怕沒有」最合理。(A)「有，它就停在動物園門口」、(B)「當然，上車吧」都表示這班車會到，與後文矛盾；(C)「車資 15 元」答非所問。故選 (D)。", "level": "B1", "topic": "public transport"}, {"id": "M262", "type": "dialogue", "q": "A: Can everyone see my screen?\nB: Yes, we can see it. ______\nA: Oh, sorry. I forgot to turn on my microphone. Can you hear me now?", "options": ["Your voice is too loud.", "But I'm afraid we can't hear you.", "Could you turn off your microphone?", "Your camera is broken."], "answer": 1, "explain": "線上課程中 A 問大家看不看得到螢幕；A 接著說「抱歉，我忘了開麥克風，現在聽得到嗎？」，可知 B 反映聽不到聲音。(B)「不過我們好像聽不到你的聲音」最合理。(A)「你的聲音太大了」與聽不到矛盾；(C)「你可以把麥克風關掉嗎？」與 A 原本沒開麥克風的情況相反；(D)「你的鏡頭壞了」與聲音無關，A 也不會接著問聽不聽得到。故選 (B)。", "level": "B2", "topic": "online class"}, {"id": "M263", "type": "dialogue", "q": "A: Do you offer a student discount?\nB: Yes, ten percent off. ______\nA: Sure. Here it is.", "options": ["Would you like to join our club?", "How old are you?", "May I see your student ID?", "Where do you study?"], "answer": 2, "explain": "A 問有沒有學生優惠；店員說打九折（ten percent off），A 接著說「好的，在這裡」並遞出東西，可知店員要求出示證件。(C)「可以看一下你的學生證嗎？」最合理。(A)「要加入我們的會員嗎？」不能用 Here it is 回答；(B)「你幾歲？」、(D)「你在哪裡讀書？」都應回答年齡或學校名稱。故選 (C)。", "level": "B1", "topic": "shopping"}, {"id": "M264", "type": "dialogue", "q": "A: I've been feeling really stressed out because of the upcoming exams.\nB: ______ Taking a walk or listening to music might help.", "options": ["Why don't you take a short break?", "You must be very proud of yourself.", "How about studying all night?", "I'm glad you're feeling better."], "answer": 0, "explain": "A 說因為即將到來的考試而壓力很大；B 接著建議「散散步或聽聽音樂可能有幫助」，可知 B 在勸對方放鬆一下。(A)「你何不稍微休息一下？」最恰當。(B)「你一定很以自己為傲」與壓力大的情境不符；(C)「要不要熬夜讀書？」會讓壓力更大，與後面放鬆的建議矛盾；(D)「真高興你好多了」與 A 現在仍覺得壓力大矛盾。故選 (A)。", "level": "B2", "topic": "stress"}, {"id": "M265", "type": "dialogue", "q": "A: Oh no, I can't find my wallet anywhere!\nB: ______\nA: At the convenience store. I bought a drink there after school.", "options": ["How much money was in it?", "Where did you last use it?", "What color is it?", "Why did you buy a drink?"], "answer": 1, "explain": "A 找不到錢包；A 接著回答「在便利商店，我放學後在那裡買了飲料」，可知 B 問的是最後一次使用錢包的地點。(B)「你最後一次是在哪裡用它？」最合理。(A)「裡面有多少錢？」應回答金額；(C)「是什麼顏色？」應回答顏色；(D)「你為什麼要買飲料？」應說明理由，皆與答句不符。故選 (B)。", "level": "B1", "topic": "lost item"}, {"id": "M266", "type": "dialogue", "q": "A: Welcome! Come on in. ______\nB: Thanks. What a lovely apartment!", "options": ["Who are you looking for?", "Sorry, I'm on my way out.", "Did you bring me a gift?", "Make yourself at home."], "answer": 3, "explain": "A 歡迎客人進門；B 道謝並稱讚房子很漂亮，可知 A 說了招呼客人的客套話。(D)「別拘束，就當自己家」最恰當。(A)「你要找誰？」與已邀請對方進門矛盾；(B)「抱歉，我正要出門」與歡迎客人不符；(C)「你有帶禮物給我嗎？」不禮貌，B 也不會以「謝謝」回應。故選 (D)。", "level": "B1", "topic": "visiting"}, {"id": "M267", "type": "dialogue", "q": "A: Your English presentation was excellent! You spoke so clearly.\nB: ______ I practiced it in front of the mirror many times.", "options": ["No, it's not my fault.", "Don't mention it.", "Thanks. I'm glad you liked it.", "I'm sorry to hear that."], "answer": 2, "explain": "A 稱讚 B 的英文報告很棒、說得很清楚；B 接著說自己對著鏡子練習了很多次，因此應先道謝、接受稱讚。(C)「謝謝，很高興你喜歡」最恰當。(A)「不，那不是我的錯」用於被指責時；(B)「不客氣」用於回應別人的道謝，而非稱讚；(D)「聽到這消息很遺憾」用於回應壞消息。故選 (C)。", "level": "B1", "topic": "compliments"}, {"id": "M268", "type": "dialogue", "q": "A: Let's go see the new superhero movie this weekend.\nB: Sounds good. ______\nA: How about Sunday afternoon? There's a show at three.", "options": ["When are you free?", "Who's the director?", "Where did you see it?", "How was the movie?"], "answer": 0, "explain": "A 提議週末去看電影，B 同意後問了一個問題；A 回答「週日下午如何？三點有一場」，可知 B 問的是時間。(A)「你什麼時候有空？」最合理。(B)「導演是誰？」無法用時間回答；(C)「你在哪裡看的？」、(D)「電影好看嗎？」都表示 A 已經看過，與「這週末要去看」矛盾。故選 (A)。", "level": "B1", "topic": "making plans"}, {"id": "M269", "type": "dialogue", "q": "A: Could you cover my shift at the cafe on Saturday? My cousin is getting married.\nB: ______ Just remember to tell the manager about the change.\nA: I will. Thanks so much!", "options": ["Congratulations on your wedding!", "Sorry, I'm working that day, too.", "Why didn't you invite me?", "No problem. I'm free that day."], "answer": 3, "explain": "cover one's shift 意為「代某人的班」。A 因表親要結婚，請 B 週六幫忙代班；B 接著提醒 A 記得告訴店長換班的事，A 也道謝，可知 B 答應了。(D)「沒問題，我那天有空」最恰當。(A)「恭喜你結婚」搞錯了結婚的人；(B)「抱歉，我那天也要上班」表示無法代班，與後文矛盾；(C)「你怎麼沒邀請我？」答非所問。故選 (D)。", "level": "B2", "topic": "part-time job"}, {"id": "M270", "type": "dialogue", "q": "A: Excuse me, but you're not allowed to eat in the library.\nB: ______ I'll finish my sandwich outside.", "options": ["Help yourself.", "Oh, I'm sorry. I didn't know that.", "That's very kind of you.", "Yes, it's delicious."], "answer": 1, "explain": "A 提醒 B 圖書館內不能吃東西；B 接著說要到外面把三明治吃完，可知 B 接受勸告並道歉。(B)「喔，抱歉，我不知道」最合理。(A)「請自便」用於招待他人；(C)「你真好心」用於回應別人的幫忙或好意，用來回應規勸並不自然；(D)「對啊，很好吃」答非所問。故選 (B)。", "level": "B1", "topic": "library rules"}, {"id": "M271", "type": "dialogue", "q": "A: How would you like your hair cut today?\nB: ______ I want to keep it long.\nA: Sure. I'll just take off about two centimeters.", "options": ["Just a trim, please.", "Very short, please.", "Every two months.", "It took about an hour."], "answer": 0, "explain": "美髮師問 B 今天想怎麼剪；B 接著說「我想留長」，美髮師也說只剪掉約兩公分，可知 B 只要稍微修一下。(A)「稍微修剪就好」（trim 修剪）最恰當。(B)「請剪很短」與想留長矛盾；(C)「每兩個月一次」回答頻率；(D)「花了大約一小時」回答所花時間，皆答非所問。故選 (A)。", "level": "B2", "topic": "hair salon"}, {"id": "M272", "type": "dialogue", "q": "A: Do you have a pen I could borrow? Mine just ran out of ink.\nB: ______ But I need it back after class.", "options": ["No, I don't have any ink.", "Sorry, I lent it to you.", "Sure. Here's a blue one.", "Thanks. I'll return it soon."], "answer": 2, "explain": "A 的筆沒水了，想跟 B 借筆；B 接著說「但下課後要還我」，可知 B 答應借出。(C)「當然，這枝藍色的給你」最合理。(A)「不，我沒有墨水」表示拒絕且答非所問；(B)「抱歉，我借給你了」語意矛盾；(D)「謝謝，我很快就還你」是借東西的人才會說的話。故選 (C)。", "level": "B1", "topic": "school"}, {"id": "M273", "type": "dialogue", "q": "A: I heard you joined the school band. ______\nB: The trumpet. I've been learning it since junior high.", "options": ["How often do you practice?", "What instrument do you play?", "When is your next concert?", "Who is your music teacher?"], "answer": 1, "explain": "A 聽說 B 參加了學校的管樂隊；B 回答「小喇叭，我從國中就開始學了」，可知 A 問的是樂器。(B)「你演奏什麼樂器？」最合理。(A)「你多久練習一次？」應回答頻率；(C)「下次表演是什麼時候？」應回答時間；(D)「你的音樂老師是誰？」應回答人名，皆無法用「小喇叭」回答。故選 (B)。", "level": "B1", "topic": "school club"}, {"id": "M274", "type": "dialogue", "q": "A: How do the shoes fit?\nB: ______ Do you have them in half a size bigger?", "options": ["They fit perfectly.", "They're a little loose.", "I'll take them.", "They're a bit tight around the toes."], "answer": 3, "explain": "店員問鞋子合不合腳；B 接著問有沒有大半號的，可知鞋子太小。(D)「腳趾的地方有點緊」最合理。(A)「非常合腳」就不需要換尺寸；(B)「有點鬆」應該換小一點的；(C)「我要買這雙」表示已決定購買，與要求換尺寸矛盾。故選 (D)。", "level": "B2", "topic": "shopping"}, {"id": "M275", "type": "dialogue", "q": "A: Excuse me. Would you mind switching seats with me? ______\nB: Not at all. Let me just grab my bag.", "options": ["I'd prefer to stand for the whole trip.", "This seat is too comfortable for me.", "I'd like to sit next to my daughter.", "You're sitting in the wrong car."], "answer": 2, "explain": "A 在車上請 B 和自己換座位，並在空格說明理由；B 回答「一點也不介意，我拿一下包包」，表示同意。(C)「我想坐在我女兒旁邊」是合理的換位理由。(A)「我寧願整趟路都站著」就不需要換座位；(B)「這個位子對我來說太舒服了」不合邏輯；(D)「你坐錯車廂了」應請對方離開，而不是和對方交換座位。故選 (C)。", "level": "B2", "topic": "travel"}, {"id": "M276", "type": "dialogue", "q": "A: Mr. Wang, would you mind if I left work an hour early today? My son is sick.\nB: ______ I hope he gets well soon.", "options": ["Not at all. Go ahead.", "Yes, I'd be glad to.", "Sure. I'll leave early, too.", "No, you can't stay here."], "answer": 0, "explain": "「Would you mind if I...?」字面意思是「你介意我……嗎？」，要表示同意須用否定回答。B 接著祝 A 的兒子早日康復，可知 B 准許 A 提早下班。(A)「一點也不介意，去吧」最恰當。(B)「是的，我很樂意」用 Yes 回答表示「介意」，且 I'd be glad to 是答應幫忙的說法；(C)「好，我也要提早走」答非所問；(D)「不，你不能待在這裡」語意不通。故選 (A)。", "level": "B2", "topic": "workplace"}, {"id": "M277", "type": "dialogue", "q": "A: Excuse me. Could you take a picture of us?\nB: ______ Just press this button, right?", "options": ["No, thanks. I don't need any.", "Say cheese!", "Here's my camera.", "Sure, no problem."], "answer": 3, "explain": "A 請 B 幫忙拍照；B 接著確認「按這個鍵就好，對吧？」，可知 B 答應幫忙。(D)「當然，沒問題」最恰當。(A)「不用了，謝謝，我不需要」用於拒絕別人提供的東西；(B)「笑一個！」是按快門前才說的，不會出現在確認操作方式之前；(C)「這是我的相機」應由請人拍照的 A 說，而不是 B。故選 (D)。", "level": "B1", "topic": "sightseeing"}, {"id": "M278", "type": "dialogue", "q": "A: We need more volunteers for the beach cleanup this Sunday. ______\nB: Count me in. What time should I be there?", "options": ["Have you ever been to the beach?", "Would you be interested in helping?", "Did you enjoy the cleanup?", "Why is the beach so dirty?"], "answer": 1, "explain": "A 說這週日的淨灘活動需要更多志工；B 回答「算我一份，我該幾點到？」，可知 A 在邀請 B 參加。(B)「你有興趣來幫忙嗎？」最合理。(A)「你去過海邊嗎？」應回答 Yes/No；(C)「你喜歡那次淨灘嗎？」表示活動已結束，與「這週日」矛盾；(D)「海灘為什麼這麼髒？」不能用 Count me in 回答。故選 (B)。", "level": "B2", "topic": "volunteering"}, {"id": "M279", "type": "dialogue", "q": "A: The meeting will be in Room 302 at 3:15. Please bring your ID card and the signed form.\nB: ______ I'm writing it down.\nA: Sure. Room 302, at 3:15.", "options": ["That's all I need, thanks.", "Can you write it down for me?", "Sorry, could you say that more slowly?", "I've already been there."], "answer": 2, "explain": "A 一口氣說出會議地點、時間和要帶的東西；B 說「我正在抄下來」，A 接著放慢速度重複「302 室，3 點 15 分」，可知 B 請 A 說慢一點。(C)「抱歉，可以說慢一點嗎？」最恰當。(A)「我只需要這些，謝謝」A 就不必再重複；(B)「你可以幫我寫下來嗎？」與 B 自己正在抄寫矛盾；(D)「我已經去過了」答非所問。故選 (C)。", "level": "B2", "topic": "asking to repeat"}, {"id": "M280", "type": "dialogue", "q": "A: Dinner is on me tonight. You helped me so much with my move.\nB: ______ Next time, it's my treat.", "options": ["Thanks. That's very generous of you.", "OK. Let's split the bill.", "No, I've already eaten.", "Sorry, I don't have time to help you."], "answer": 0, "explain": "「Dinner is on me.」意為「晚餐我請客」，A 為了感謝 B 幫忙搬家而請客；B 接著說「下次換我請」，可知 B 接受了好意。(A)「謝謝，你真大方」最恰當。(B)「好，我們各付各的」與 A 請客及「下次換我請」矛盾；(C)「不，我已經吃過了」表示拒絕，與下次換我請不連貫；(D)「抱歉，我沒空幫你」與情境無關，A 已經搬完家了。故選 (A)。", "level": "B2", "topic": "treating"}, {"id": "M281", "type": "dialogue", "q": "A: My computer just crashed, and I lost the file I was working on.\nB: ______ Next time, remember to save your work every few minutes.", "options": ["Congratulations!", "Oh, no. That's terrible.", "It's up to you.", "I couldn't agree more."], "answer": 1, "explain": "A 說電腦當機，正在處理的檔案不見了；B 接著提醒下次要每隔幾分鐘存檔，可知 B 先對這件倒楣事表示同情。(B)「喔，不，真糟糕」最恰當。(A)「恭喜！」用於好消息；(C)「由你決定」用於對方徵詢意見時；(D)「我完全同意」用於贊同別人的看法，皆不合語境。故選 (B)。", "level": "B1", "topic": "office"}, {"id": "M282", "type": "dialogue", "q": "A: Should we take the MRT or a taxi to the concert tonight?\nB: ______ The traffic will be terrible on a Friday night.", "options": ["Let's take a taxi. It's more comfortable.", "The concert starts at eight.", "I've never been to a concert.", "The MRT would be better."], "answer": 3, "explain": "A 問今晚去演唱會要搭捷運還是計程車；B 接著說「星期五晚上一定很塞」，可知 B 選擇不受塞車影響的捷運。(D)「搭捷運比較好」最合理。(A)「搭計程車吧，比較舒服」與塞車的理由矛盾；(B)「演唱會八點開始」、(C)「我從來沒去過演唱會」都沒有回答要選哪種交通工具。故選 (D)。", "level": "B1", "topic": "making plans"}, {"id": "M283", "type": "dialogue", "q": "A: Hi, Linda. This is Ben. ______ I have a high fever.\nB: Oh, I'm sorry to hear that. Take the day off and get some rest.", "options": ["I'm afraid I can't come to work today.", "I'll be there in ten minutes.", "Can I work overtime tonight?", "I just got a promotion."], "answer": 0, "explain": "Ben 打電話給主管 Linda 說自己發高燒；主管回答「那就請一天假，好好休息」，可知 Ben 是在請病假。(A)「恐怕我今天沒辦法去上班」最恰當。(B)「我十分鐘後到」、(C)「我今晚可以加班嗎？」都與發燒、需要休息矛盾；(D)「我剛升職了」是好消息，主管不會回應「聽到這消息很遺憾」。故選 (A)。", "level": "B2", "topic": "sick leave"}, {"id": "M284", "type": "dialogue", "q": "A: Customer service. How can I help you?\nB: I ordered a phone case two weeks ago, but it still hasn't arrived.\nA: ______\nB: Sure. It's 58302.", "options": ["Would you like to cancel your membership?", "What color would you like?", "Could you give me your order number, please?", "It will be delivered tomorrow."], "answer": 2, "explain": "B 向客服反映兩週前訂的手機殼還沒送到；B 接著回答「好的，是 58302」，可知客服要求提供一組號碼。(C)「可以給我您的訂單編號嗎？」最合理。(A)「您要取消會員資格嗎？」答非所問；(B)「您想要什麼顏色？」無法用號碼回答；(D)「明天會送達」是陳述句，B 不會接著說「好的，是 58302」。故選 (C)。", "level": "B2", "topic": "customer service"}, {"id": "M285", "type": "dialogue", "q": "A: Hi, I'm Amy. I just started working in the sales department.\nB: ______ I'm Tom from marketing. Let me know if you need anything.", "options": ["See you later.", "Sorry, I'm busy right now.", "Long time no see.", "Nice to meet you, Amy."], "answer": 3, "explain": "新同事 Amy 自我介紹；B 接著介紹自己是行銷部的 Tom，並說有需要可以找他，可知兩人是初次見面。(D)「很高興認識你，Amy」最恰當。(A)「待會見」是道別用語；(B)「抱歉，我現在很忙」與後面熱心提供協助矛盾；(C)「好久不見」用於久別重逢的熟人，不適用於初次見面。故選 (D)。", "level": "B1", "topic": "introductions"}, {"id": "M286", "type": "dialogue", "q": "A: Oh no, I left my wallet at home. ______\nB: Sure. How much do you need?", "options": ["Can you pay me back tomorrow?", "Could you lend me some money for lunch?", "Did you find my wallet?", "How much is your wallet?"], "answer": 1, "explain": "A 發現錢包忘在家裡；B 回答「當然，你需要多少？」，可知 A 想跟 B 借錢。(B)「可以借我一點錢買午餐嗎？」最合理。(A)「你明天能還我錢嗎？」是借錢給別人的人說的，A 並沒有借錢給 B；(C)「你找到我的錢包了嗎？」A 已經知道錢包在家裡；(D)「你的錢包多少錢？」答非所問。故選 (B)。", "level": "B1", "topic": "borrowing"}, {"id": "M287", "type": "dialogue", "q": "A: It's a bit chilly in here. ______\nB: Not at all. I was feeling cold, too.", "options": ["Would you like me to open the window?", "Can you turn on the fan?", "Would you mind if I closed the window?", "Do you feel like going swimming?"], "answer": 2, "explain": "A 覺得有點冷；B 回答「一點也不（介意），我也覺得冷」，Not at all 是回答 Would you mind...? 表示同意的典型說法。(C)「你介意我把窗戶關上嗎？」最恰當。(A)「要我幫你開窗嗎？」與覺得冷矛盾，且不能用 Not at all 回答；(B)「你可以打開電風扇嗎？」會更冷，也不能用 Not at all 回答；(D)「你想去游泳嗎？」與情境無關。故選 (C)。", "level": "B2", "topic": "polite requests"}, {"id": "M288", "type": "dialogue", "q": "A: Ms. Lee, I don't quite understand this grammar rule. ______\nB: Of course. Come to my office after class.", "options": ["Could you explain it to me again?", "Could you give us less homework?", "Why do we have to learn grammar?", "May I go to the restroom?"], "answer": 0, "explain": "學生說不太懂這條文法規則；老師回答「當然，下課後來我辦公室」，可知學生請老師再講解一次。(A)「您可以再跟我解釋一次嗎？」最合理。(B)「可以少出一點作業嗎？」與不懂文法無關，老師也不會為此請學生下課到辦公室；(C)「我們為什麼要學文法？」不能用 Of course 回答；(D)「我可以去洗手間嗎？」與「下課後來辦公室」不連貫。故選 (A)。", "level": "B1", "topic": "school"}, {"id": "M289", "type": "dialogue", "q": "A: How would you like your eggs?\nB: ______\nA: OK. And would you like toast with that?", "options": ["Very much, thank you.", "Scrambled, please.", "Two dozen, please.", "They're delicious."], "answer": 1, "explain": "「How would you like your eggs?」是問「蛋要怎麼料理？」，應回答烹調方式。(B)「請做炒蛋」最恰當。(A)「非常喜歡，謝謝」誤把 How would you like 當成「喜不喜歡」；(C)「請給我兩打」回答數量，一打（dozen）是十二個，不合點餐情境；(D)「很好吃」表示已經吃過，但此時才剛要點餐。故選 (B)。", "level": "B1", "topic": "restaurant"}, {"id": "M290", "type": "dialogue", "q": "A: Good morning, Star Electronics.\nB: Hi. I'm calling about the job opening I saw on your website.\nA: ______\nB: Sure, I'll wait.", "options": ["You can call me any time.", "What would you like to buy?", "Sorry, I didn't apply for it.", "Please hold. I'll transfer you to Human Resources."], "answer": 3, "explain": "B 打電話詢問公司網站上的職缺；B 接著說「好，我等」，可知對方請他稍候。(D)「請稍候，我幫您轉接人資部」最合理，transfer 在電話中指「轉接」。(A)「你隨時可以打給我」不會接「我等」；(B)「您想買什麼？」答非所問；(C)「抱歉，我沒有應徵」說話者錯誤，要應徵的是 B 而不是接電話的人。故選 (D)。", "level": "B2", "topic": "phone call"}, {"id": "M291", "type": "dialogue", "q": "A: Would you like some more noodles?\nB: ______ I'm full. Everything was delicious, though.\nA: I'm glad you enjoyed it.", "options": ["No, thanks.", "Yes, please.", "Help yourself.", "Here you are."], "answer": 0, "explain": "主人問 B 要不要再來些麵；B 接著說「我飽了，不過每道菜都很好吃」，可知 B 婉拒。(A)「不用了，謝謝」最恰當。(B)「好，麻煩了」與吃飽矛盾；(C)「請自便」是主人招待客人的用語；(D)「給你」是遞東西時說的話，不是回答詢問。故選 (A)。", "level": "B1", "topic": "dining"}, {"id": "M292", "type": "dialogue", "q": "A: Bright Smile Dental Clinic. How may I help you?\nB: ______\nA: Let me check. Is Wednesday at 4 p.m. OK for you?", "options": ["I'd like to cancel my order.", "My teeth look great, thanks.", "I'd like to make an appointment for a checkup.", "Could you tell me how to brush my teeth?"], "answer": 2, "explain": "B 打電話到牙醫診所；對方接著說「我查一下，週三下午四點可以嗎？」，可知 B 想預約看診。(C)「我想預約做檢查」最合理。(A)「我想取消訂單」是購物用語；(B)「我的牙齒看起來很好，謝謝」不需要安排時間；(D)「你可以告訴我怎麼刷牙嗎？」與安排看診時段無關。故選 (C)。", "level": "B1", "topic": "health"}, {"id": "M293", "type": "dialogue", "q": "A: I think we should do our project on plastic pollution.\nB: ______ Many groups have already chosen that topic. How about light pollution?", "options": ["I totally agree with you.", "I'm not sure that's a good idea.", "That's exactly what I was going to say.", "Let's do it right now."], "answer": 1, "explain": "A 提議報告主題做塑膠污染；B 接著說很多組已經選了這個題目，並改提光害，可知 B 不贊成。(B)「我不確定那是個好主意」是委婉表達反對的說法。(A)「我完全同意你」、(C)「我正要這麼說」、(D)「我們現在就開始吧」都表示贊成，與後面另提新主題矛盾。故選 (B)。", "level": "B2", "topic": "group project"}, {"id": "M294", "type": "dialogue", "q": "A: Excuse me. Where can I find the olive oil?\nB: ______\nA: Thank you. And where's the checkout counter?", "options": ["It's 250 dollars a bottle.", "We have it in two sizes.", "Sorry, we're closed tomorrow.", "It's in aisle 5, next to the vinegar."], "answer": 3, "explain": "A 在超市詢問橄欖油放在哪裡，應回答位置；A 接著道謝，並用 And where...? 再問另一個地點。(D)「在第五走道，醋的旁邊」（aisle 走道）最合理。(A)「一瓶 250 元」回答價格；(B)「我們有兩種容量」回答尺寸；(C)「抱歉，我們明天公休」與詢問位置無關。故選 (D)。", "level": "B1", "topic": "supermarket"}, {"id": "M295", "type": "dialogue", "q": "A: My suitcase didn't come out on the baggage carousel.\nB: I'm sorry to hear that. ______\nA: It's a large black one with a red ribbon on the handle.", "options": ["Where are you flying to next?", "How much did you pay for it?", "Could you describe it for me?", "Did you pack it yourself?"], "answer": 2, "explain": "A 在機場行李轉盤等不到自己的行李箱；A 接著描述「是一個大型黑色行李箱，提把上綁著紅色緞帶」，可知機場人員請 A 描述外觀。(C)「可以描述一下它的樣子嗎？」最合理。(A)「你接下來要飛去哪？」應回答地點；(B)「你買它花了多少錢？」應回答價格；(D)「是你自己打包的嗎？」應回答 Yes/No。故選 (C)。", "level": "B2", "topic": "airport"}, {"id": "M296", "type": "dialogue", "q": "A: Did you get a chance to read my draft? What do you think?\nB: ______ But you might want to shorten the introduction a little.", "options": ["Overall, it looks good.", "I haven't read it yet.", "I wrote it myself.", "It's none of your business."], "answer": 0, "explain": "A 問 B 讀了自己的草稿沒有、覺得如何；B 接著說「不過你也許可以把引言縮短一點」，But 表示語氣轉折，前面應是正面評價。(A)「整體來說看起來不錯」最恰當。(B)「我還沒讀」與後面給出具體建議矛盾；(C)「是我自己寫的」不合理，草稿是 A 寫的；(D)「不關你的事」語氣無禮又不合邏輯。故選 (A)。", "level": "B2", "topic": "giving feedback"}, {"id": "M297", "type": "dialogue", "q": "A: I'd like to return these books, please.\nB: Let me see... ______\nA: Oh, really? How much is the fine?", "options": ["You can borrow up to five books.", "This one is three days overdue.", "Thanks for returning them early.", "The library closes at nine."], "answer": 1, "explain": "A 在圖書館還書；A 接著問「罰款多少？」，可知館員指出書逾期了。(B)「這本逾期三天了」最合理，overdue 意為「過期的、逾期的」。(A)「你最多可以借五本」與罰款無關；(C)「謝謝你提早歸還」提早還書不會被罰款；(D)「圖書館九點關門」與罰款無關。故選 (B)。", "level": "B2", "topic": "library"}, {"id": "M298", "type": "dialogue", "q": "A: Does this salad have any nuts in it? ______\nB: I'm not sure. Let me check with the kitchen. We don't want you to get sick.", "options": ["I'd like extra nuts, please.", "It tastes a little salty.", "I'm a vegetarian, so I don't eat meat.", "I'm allergic to them."], "answer": 3, "explain": "A 問沙拉裡有沒有堅果；服務生說要去廚房確認，並說「我們不希望您身體不舒服」，可知 A 對堅果過敏。(D)「我對堅果過敏」最合理，them 指 nuts。(A)「我想多加一些堅果」與擔心生病無關；(B)「吃起來有點鹹」表示已經吃過，與詢問成分及後文不符；(C)「我吃素，所以不吃肉」與堅果無關。故選 (D)。", "level": "B2", "topic": "food allergy"}, {"id": "M299", "type": "dialogue", "q": "A: Hello. Could I speak to Mr. Huang, please?\nB: ______\nA: This is Jenny Wu from Green Bank.", "options": ["May I ask who's calling?", "Sorry, I'm busy right now.", "Yes, I'll call you back.", "You're welcome."], "answer": 0, "explain": "A 打電話找黃先生；A 接著說「我是綠色銀行的吳珍妮」，可知接電話的人詢問來電者的身分。(A)「請問您是哪位？」最合理。(B)「抱歉，我現在很忙」、(C)「好，我再回電給你」都不會讓 A 接著自我介紹；(D)「不客氣」用於回應道謝，A 並沒有道謝。故選 (A)。", "level": "B1", "topic": "phone call"}, {"id": "M300", "type": "dialogue", "q": "A: The final exams are coming up. Do you want to study together this Saturday?\nB: ______ What time shall we meet?\nA: How about nine in the morning at the city library?", "options": ["Sorry, I have to work all weekend.", "I'd rather study alone.", "That's a great idea.", "The exams were easier than I expected."], "answer": 2, "explain": "A 約 B 週六一起準備期末考；B 接著問「我們幾點見面？」，可知 B 同意。(C)「好主意」最恰當。(A)「抱歉，我整個週末都要打工」、(B)「我寧願自己讀」都表示拒絕，與接著約時間矛盾；(D)「考試比我預期的簡單」表示已經考完，與「期末考快到了」矛盾。故選 (C)。", "level": "B1", "topic": "making plans"}, {"id": "M301", "type": "vocab", "q": "I put too much salt in the soup, so now it tastes too ______.", "options": ["sweet", "salty", "sour", "fresh"], "answer": 1, "explain": "句意：我在湯裡放了太多鹽，所以現在湯嚐起來太鹹了。由 too much salt（太多鹽）可知湯變「鹹」了，salty 鹹的。(A) sweet 甜的 (C) sour 酸的 (D) fresh 新鮮的，都不是放太多鹽造成的味道。故選 (B)。", "level": "A2", "topic": "food"}, {"id": "M302", "type": "vocab", "q": "Because of the strong typhoon, all the schools in Taipei were ______ yesterday, so the students stayed home.", "options": ["crowded", "busy", "open", "closed"], "answer": 3, "explain": "句意：因為強烈颱風，台北所有的學校昨天都停課，所以學生都待在家裡。由 typhoon（颱風）和 stayed home（待在家）可知學校「關閉、停課」，closed 關閉的。(A) crowded 擁擠的 (B) busy 忙碌的 (C) open 開放的，都無法說明學生為什麼待在家裡。故選 (D)。", "level": "A2", "topic": "weather"}, {"id": "M303", "type": "vocab", "q": "Mr. Hsu teaches ______. In his class, we learn about the past, like how people lived in Taiwan 100 years ago.", "options": ["history", "science", "music", "math"], "answer": 0, "explain": "句意：許老師教歷史。在他的課堂上，我們學習過去的事，例如一百年前台灣人是怎麼生活的。由 learn about the past（學習過去的事）可知是 history 歷史。(B) science 自然科學 (C) music 音樂 (D) math 數學，都不是學習過去發生的事。故選 (A)。", "level": "A2", "topic": "school subjects"}, {"id": "M304", "type": "vocab", "q": "My uncle's daughter is my ______. We often play games together at family parties.", "options": ["aunt", "niece", "cousin", "sister"], "answer": 2, "explain": "句意：我叔叔（舅舅）的女兒是我的堂（表）姊妹，我們常在家庭聚會時一起玩遊戲。cousin 堂（表）兄弟姊妹，指伯叔姑舅姨的孩子。(A) aunt 阿姨；姑姑；嬸嬸 (B) niece 姪女；外甥女，是兄弟姊妹的女兒 (D) sister 姊妹，皆不符合「叔叔的女兒」。故選 (C)。", "level": "A2", "topic": "family"}, {"id": "M305", "type": "vocab", "q": "We missed the last bus, so we took a ______ home.", "options": ["ticket", "map", "taxi", "seat"], "answer": 2, "explain": "句意：我們錯過了末班公車，所以搭計程車回家。take a taxi 搭計程車，可以代替公車把人載回家。(A) ticket 票 (B) map 地圖 (D) seat 座位，都不是可以「搭乘回家」的交通工具。故選 (C)。", "level": "A2", "topic": "transportation"}, {"id": "M306", "type": "vocab", "q": "You have a high fever. You should stay in bed and take this ______ three times a day.", "options": ["medicine", "message", "magazine", "machine"], "answer": 0, "explain": "句意：你發高燒了，應該躺在床上休息，並且一天吃三次這個藥。take medicine 吃藥，medicine 藥。(B) message 訊息 (C) magazine 雜誌 (D) machine 機器，字形相近，但都不能「一天吃三次」。故選 (A)。", "level": "A2", "topic": "health"}, {"id": "M307", "type": "vocab", "q": "My brother loves taking pictures. He always carries his ______ when he goes hiking.", "options": ["guitar", "racket", "towel", "camera"], "answer": 3, "explain": "句意：我哥哥很喜歡拍照，他去健行時總是帶著他的相機。由 taking pictures（拍照）可知要選 camera 相機。(A) guitar 吉他 (B) racket 球拍 (C) towel 毛巾，都和拍照無關。故選 (D)。", "level": "A2", "topic": "hobbies"}, {"id": "M308", "type": "vocab", "q": "This shirt is on ______ today. Everything in the store is 30% off.", "options": ["time", "sale", "foot", "fire"], "answer": 1, "explain": "句意：這件襯衫今天在特價，店裡所有商品都打七折。由 30% off（減價百分之三十，即打七折）可知是 on sale 特價中。(A) on time 準時 (C) on foot 步行 (D) on fire 著火，都與打折無關。故選 (B)。", "level": "A2", "topic": "shopping"}, {"id": "M309", "type": "vocab", "q": "Ms. Wang works at a hospital. She is a ______, and she takes care of sick people every day.", "options": ["nurse", "farmer", "pilot", "cook"], "answer": 0, "explain": "句意：王小姐在醫院工作，她是一名護理師，每天照顧生病的人。nurse 護理師，符合「在醫院照顧病人」。(B) farmer 農夫 (C) pilot 飛行員 (D) cook 廚師，工作內容都不是照顧病人。故選 (A)。", "level": "A2", "topic": "jobs"}, {"id": "M310", "type": "vocab", "q": "An elephant has a long ______. It uses it to pick up food and drink water.", "options": ["tail", "ear", "nose", "foot"], "answer": 2, "explain": "句意：大象有長長的鼻子，牠用鼻子撿起食物和喝水。nose 鼻子（大象的長鼻子也叫 trunk）。(A) tail 尾巴，大象不用尾巴拿食物；(B) ear 耳朵 (D) foot 腳，都不是長的，也不能用來喝水。故選 (C)。", "level": "A2", "topic": "animals"}, {"id": "M311", "type": "vocab", "q": "There are clothes and books all over my bedroom floor. Mom wants me to ______ my room before dinner.", "options": ["wake up", "give up", "stand up", "clean up"], "answer": 3, "explain": "句意：我房間的地板上到處都是衣服和書，媽媽要我在晚餐前把房間整理乾淨。由地板上到處都是衣服和書可知房間很亂，需要「打掃、整理」，clean up 打掃乾淨。(A) wake up 醒來 (B) give up 放棄 (C) stand up 站起來，都不能接 my room 表示整理房間。故選 (D)。", "level": "A2", "topic": "chores"}, {"id": "M312", "type": "vocab", "q": "Our summer vacation ______ in early July and ends in late August.", "options": ["finishes", "begins", "leaves", "closes"], "answer": 1, "explain": "句意：我們的暑假在七月初開始，八月底結束。由後半句 ends in late August（八月底結束）可知前面應是「開始」，begins 開始。(A) finishes 結束，與後面的 ends 意思重複，前後不合邏輯；(C) leaves 離開 (D) closes 關門，都不能用來表示假期開始。故選 (B)。", "level": "A2", "topic": "school calendar"}, {"id": "M313", "type": "vocab", "q": "I need to buy a ______ before I can mail this letter.", "options": ["stamp", "coin", "card", "bag"], "answer": 0, "explain": "句意：在寄出這封信之前，我需要買一張郵票。stamp 郵票，寄信時必須貼上郵票。(B) coin 硬幣 (C) card 卡片 (D) bag 袋子，都不是寄信前一定要買的東西。故選 (A)。", "level": "A2", "topic": "post office"}, {"id": "M314", "type": "vocab", "q": "Lily felt ______ after her best friend moved to another city. She had no one to talk to at lunch.", "options": ["proud", "lucky", "funny", "lonely"], "answer": 3, "explain": "句意：莉莉最好的朋友搬到另一個城市後，她覺得很寂寞，午餐時都沒有人可以聊天。lonely 寂寞的，符合「沒有人可以聊天」。(A) proud 驕傲的 (B) lucky 幸運的 (C) funny 好笑的，皆與情境不合。故選 (D)。", "level": "A2", "topic": "feelings"}, {"id": "M315", "type": "grammar", "q": "My sister ______ to school by bus every day.", "options": ["go", "going", "goes", "gone"], "answer": 2, "explain": "句意：我妹妹每天搭公車上學。every day 表示習慣，用現在簡單式；主詞 My sister 是第三人稱單數，動詞要加 -es，故用 goes。(A) go 未配合第三人稱單數；(B) going 前面必須有 be 動詞；(D) gone 是過去分詞，不能單獨當動詞。故選 (C)。", "level": "A2", "topic": "present simple"}, {"id": "M316", "type": "grammar", "q": "We ______ to Penghu with our grandparents last summer.", "options": ["went", "go", "will go", "are going"], "answer": 0, "explain": "句意：去年夏天我們和祖父母一起去了澎湖。last summer（去年夏天）是過去時間，動詞用過去式，go 的過去式為 went。(B) go 為現在式 (C) will go 為未來式 (D) are going 為現在進行式，都不能搭配 last summer。故選 (A)。", "level": "A2", "topic": "past simple"}, {"id": "M317", "type": "grammar", "q": "My brother is 180 centimeters tall, and I am 170. He is ______ than me.", "options": ["tall", "taller", "tallest", "more tall"], "answer": 1, "explain": "句意：我哥哥身高 180 公分，我 170 公分，他比我高。兩者比較且後面有 than，要用比較級；tall 的比較級是 taller。(A) tall 為原級 (C) tallest 為最高級；(D) tall 是短的形容詞，比較級直接加 -er，不用 more。故選 (B)。", "level": "A2", "topic": "comparatives"}, {"id": "M318", "type": "grammar", "q": "Look at those dark clouds. It ______ rain soon.", "options": ["is", "was", "has", "is going to"], "answer": 3, "explain": "句意：看看那些烏雲，快要下雨了。根據眼前的跡象（烏雲）預測即將發生的事，用 be going to + 原形動詞。(A) is (B) was 後面不能直接接原形動詞 rain；(C) has 後面要接過去分詞，也不合語意。故選 (D)。", "level": "A2", "topic": "be going to"}, {"id": "M319", "type": "grammar", "q": "Ken is only five years old, but he ______ swim very well.", "options": ["is", "can", "are", "has"], "answer": 1, "explain": "句意：小健只有五歲，但他很會游泳。助動詞 can 表示「能夠；會」，後面接原形動詞 swim。(A) is (C) are 是 be 動詞，後面不能接原形動詞，而且 are 與主詞 he 不一致；(D) has 意為「有」，後面也不能接原形動詞。故選 (B)。", "level": "A2", "topic": "can"}, {"id": "M320", "type": "grammar", "q": "Listen! Someone ______ the piano upstairs.", "options": ["play", "played", "is playing", "plays"], "answer": 2, "explain": "句意：你聽！樓上有人正在彈鋼琴。Listen! 表示說話當下正在發生的動作，要用現在進行式 is + V-ing。(A) play 未配合單數主詞 someone；(B) played 為過去式；(D) plays 為現在簡單式，表示習慣，不合「此刻正在」的語意。故選 (C)。", "level": "A2", "topic": "present continuous"}, {"id": "M321", "type": "grammar", "q": "There ______ two cats and a dog in my grandpa's house.", "options": ["are", "is", "be", "has"], "answer": 0, "explain": "句意：我爺爺家有兩隻貓和一隻狗。There is/are 表示「某處有…」；後面的 two cats and a dog 是複數，所以用 are。(B) is 用於單數名詞；(C) be 必須依主詞變化，不能用原形；(D) There has 不是正確用法。故選 (A)。", "level": "A2", "topic": "there is / there are"}, {"id": "M322", "type": "grammar", "q": "The school concert starts ______ seven o'clock tonight.", "options": ["in", "on", "for", "at"], "answer": 3, "explain": "句意：學校音樂會今晚七點開始。表示「幾點鐘」的時間點，介系詞用 at。(A) in 用於月份、年份或上午、下午等較長的時間；(B) on 用於日期或星期；(C) for 表示一段時間，如 for two hours。故選 (D)。", "level": "A2", "topic": "prepositions of time"}, {"id": "M323", "type": "grammar", "q": "The blue whale is the ______ animal in the world.", "options": ["big", "bigger", "biggest", "most big"], "answer": 2, "explain": "句意：藍鯨是世界上最大的動物。前面有 the，後面有 in the world（在某個範圍內），要用最高級；big 的最高級要重複字尾 g 再加 -est，寫成 biggest。(A) big 為原級 (B) bigger 為比較級；(D) big 是短的形容詞，不用 most。故選 (C)。", "level": "A2", "topic": "superlatives"}, {"id": "M324", "type": "grammar", "q": "Students ______ run in the hallways. Someone could fall and get hurt.", "options": ["must", "mustn't", "can", "have to"], "answer": 1, "explain": "句意：學生不可以在走廊上奔跑，可能會有人跌倒受傷。由後句「可能有人跌倒受傷」可知這是被禁止的事，用 mustn't（must not）表示「不可以」。(A) must 必須 (C) can 可以 (D) have to 必須，都與後句的危險情況矛盾。故選 (B)。", "level": "A2", "topic": "must / mustn't"}, {"id": "M325", "type": "grammar", "q": "Sorry, there isn't ______ juice left. Would you like some water instead?", "options": ["any", "some", "many", "a"], "answer": 0, "explain": "句意：抱歉，果汁已經沒有了，你要不要改喝水？否定句中表示「一些；任何」用 any。(B) some 多用於肯定句；(C) many 修飾可數名詞，juice 是不可數名詞；(D) a 不能用在不可數名詞 juice 前面。故選 (A)。", "level": "A2", "topic": "some / any"}, {"id": "M326", "type": "grammar", "q": "______ brothers and sisters do you have?", "options": ["How much", "How old", "How long", "How many"], "answer": 3, "explain": "句意：你有幾個兄弟姊妹？brothers and sisters 是可數名詞複數，詢問「數量多少」用 How many。(A) How much 用於不可數名詞或詢問價錢；(B) How old 詢問年紀；(C) How long 詢問時間長短或長度，皆不合。故選 (D)。", "level": "A2", "topic": "how many / how much"}, {"id": "M327", "type": "grammar", "q": "This isn't my pencil case. Mine is blue. Is it ______?", "options": ["you", "yours", "your", "you're"], "answer": 1, "explain": "句意：這不是我的鉛筆盒，我的是藍色的。這是你的嗎？空格後面沒有名詞，要用所有格代名詞 yours（= your pencil case）。(A) you 為主格或受格；(C) your 後面必須接名詞；(D) you're 是 you are 的縮寫。故選 (B)。", "level": "A2", "topic": "possessive pronouns"}, {"id": "M328", "type": "dialogue", "q": "A: Excuse me. What time is it?\nB: ______\nA: Oh no! I'm going to miss my train.", "options": ["It's Tuesday.", "It's sunny today.", "It takes ten minutes.", "It's almost four o'clock."], "answer": 3, "explain": "A 問現在幾點，B 回答「快四點了」，A 接著說「糟了！我要趕不上火車了」，前後連貫。(A) 今天星期二，回答的是星期幾；(B) 今天天氣晴朗，回答的是天氣；(C) 要花十分鐘，回答的是需要多少時間，皆答非所問。故選 (D)。", "level": "A2", "topic": "asking the time"}, {"id": "M329", "type": "dialogue", "q": "A: Hi, I'm Jack. I'm new in this class.\nB: ______\nA: Nice to meet you, too.", "options": ["See you tomorrow.", "Hi, I'm Emma. Nice to meet you.", "I'm fine, thank you.", "You're welcome."], "answer": 1, "explain": "A 自我介紹說自己是新同學，B 也介紹自己並說「很高興認識你」，所以 A 回答「我也很高興認識你」。(A) 明天見，用於道別；(C) 我很好，謝謝，用來回答 How are you?；(D) 不客氣，用來回應道謝，都接不上 Nice to meet you, too.。故選 (B)。", "level": "A2", "topic": "meeting people"}, {"id": "M330", "type": "dialogue", "q": "A: What would you like to drink?\nB: ______\nA: OK. One orange juice. Anything else?", "options": ["I'd like a hamburger, please.", "I'm not hungry.", "Orange juice, please.", "It's 50 dollars."], "answer": 2, "explain": "A 問要喝什麼，B 回答「請給我柳橙汁」，A 再確認「好的，一杯柳橙汁，還需要別的嗎？」。(A) 漢堡是食物，不是飲料，也和 A 確認的柳橙汁不符；(B) 我不餓，答非所問；(D) 是 50 元，應該是店員說的話。故選 (C)。", "level": "A2", "topic": "ordering drinks"}, {"id": "M331", "type": "dialogue", "q": "A: What did you do last weekend?\nB: ______\nA: That sounds fun. Did you see the pandas?", "options": ["I went to the zoo with my family.", "I'm going to the beach.", "I like animals very much.", "I'll stay home this weekend."], "answer": 0, "explain": "A 問上週末做了什麼（過去式），B 回答「我和家人去了動物園」，A 接著問「有看到貓熊嗎？」，前後連貫。(B) 我要去海邊、(D) 這個週末我會待在家，都是未來的計畫，與 last weekend 不合；(C) 我很喜歡動物，沒有回答做了什麼。故選 (A)。", "level": "A2", "topic": "weekend activities"}, {"id": "M332", "type": "dialogue", "q": "A: Why are you so happy today?\nB: ______\nA: Wow! Congratulations!", "options": ["I lost my bike yesterday.", "I'm tired of studying.", "I won first prize in the drawing contest.", "It's raining again."], "answer": 2, "explain": "A 問 B 今天為什麼這麼開心，B 回答「我在繪畫比賽得了第一名」，所以 A 說「哇！恭喜！」。(A) 我昨天弄丟了腳踏車 (B) 我讀書讀累了 (D) 又下雨了，都不是開心的理由，A 也不會說恭喜。故選 (C)。", "level": "A2", "topic": "good news"}, {"id": "M333", "type": "dialogue", "q": "A: Excuse me. Is there a bookstore near here?\nB: ______\nA: Thanks. I'll walk there now.", "options": ["No, I don't like it.", "It opens at ten.", "Sorry, I'm busy.", "Yes. There's one next to the bank."], "answer": 3, "explain": "A 問附近有沒有書店，B 回答「有，銀行旁邊就有一家」，A 道謝並說現在就走過去。(A) 不，我不喜歡它，答非所問；(B) 它十點開門，沒有說明地點；(C) 抱歉，我很忙，A 不會接著道謝並說要走過去。故選 (D)。", "level": "A2", "topic": "asking for places"}, {"id": "M334", "type": "dialogue", "q": "A: What do you usually do in your free time?\nB: ______\nA: Me too. What kind of books do you like?", "options": ["I usually go to school by bus.", "I like reading books.", "I have two free tickets.", "I'm free on Sunday."], "answer": 1, "explain": "A 問 B 空閒時通常做什麼，B 回答「我喜歡看書」，A 說「我也是」並追問喜歡哪一類的書。(A) 我通常搭公車上學，與空閒時間無關；(C) 我有兩張免費的票、(D) 我星期天有空，都只是用到 free 這個字，沒有回答問題，也接不上 A 問書的種類。故選 (B)。", "level": "A2", "topic": "free time"}, {"id": "M335", "type": "dialogue", "q": "A: Which T-shirt do you like, the red one or the black one?\nB: ______\nA: Me too. Black looks cool.", "options": ["The black one.", "Yes, I do.", "It's 200 dollars.", "Large, please."], "answer": 0, "explain": "A 問 B 喜歡紅色還是黑色的 T 恤，B 回答「黑色那件」，A 說「我也是，黑色看起來很酷」。(B) Yes, I do. 用來回答 Do you…? 的問句，不能回答二選一的 Which 問句；(C) 200 元，回答的是價錢；(D) 請給我 L 號，回答的是尺寸，皆答非所問。故選 (A)。", "level": "A2", "topic": "shopping for clothes"}, {"id": "M336", "type": "dialogue", "q": "A: What's the weather like in Taipei today?\nB: ______\nA: Then I'll take a jacket with me.", "options": ["It's Friday today.", "I'm from Taipei.", "It's hot and sunny.", "It's cold and windy."], "answer": 3, "explain": "A 問台北今天的天氣如何，B 回答「又冷又颳風」，所以 A 說「那我要帶件外套」。(A) 今天星期五，答非所問；(B) 我是台北人，沒有說明天氣；(C) 又熱又晴朗，與 A 要帶外套不合。故選 (D)。", "level": "A2", "topic": "weather"}, {"id": "M337", "type": "dialogue", "q": "A: How many people are there in your family?\nB: ______\nA: Oh, so you're an only child.", "options": ["They are teachers.", "We live in Hsinchu.", "Three: my parents and me.", "My family is very happy."], "answer": 2, "explain": "A 問 B 家裡有幾個人，B 回答「三個人：我爸媽和我」，A 因此說「喔，所以你是獨生子女」。(A) 他們是老師 (B) 我們住在新竹 (D) 我的家庭很幸福，都沒有回答人數，也無法推出 B 是獨生子女。故選 (C)。", "level": "A2", "topic": "family"}, {"id": "M338", "type": "dialogue", "q": "A: Do you have any pets?\nB: ______\nA: How cute! What's its name?", "options": ["Yes, I have a cat.", "No, I don't.", "Yes, I have two dogs.", "I'm going to the pet shop."], "answer": 0, "explain": "A 問 B 有沒有養寵物，B 回答「有，我養了一隻貓」，A 說「好可愛！牠叫什麼名字？」。(B) 沒有養，A 不會接著問寵物的名字；(C) 養了兩隻狗，A 應該問 their names，不會用單數的 its name；(D) 我要去寵物店，沒有回答問題。故選 (A)。", "level": "A2", "topic": "pets"}, {"id": "M339", "type": "dialogue", "q": "A: Did you finish the English homework?\nB: ______\nA: Don't worry. I can help you after lunch.", "options": ["Yes, it was very easy.", "Not yet. It's too hard for me.", "I like English class.", "Here you are."], "answer": 1, "explain": "A 問 B 英文作業寫完了沒，B 回答「還沒，對我來說太難了」，A 便安慰他「別擔心，我午餐後可以幫你」。(A) 寫完了而且很簡單，A 不需要說 Don't worry 並提供幫忙；(C) 我喜歡英文課，答非所問；(D) 給你，用於遞東西給別人。故選 (B)。", "level": "A2", "topic": "homework"}, {"id": "M340", "type": "dialogue", "q": "A: How do you get to school every day?\nB: ______\nA: How long does the ride take?", "options": ["At seven thirty.", "With my best friend.", "By MRT.", "Because I'm late."], "answer": 2, "explain": "A 問 B 每天怎麼去學校（交通方式），B 回答「搭捷運」，A 接著問「搭車要多久？」。(A) 七點半，回答的是時間；(B) 和我最好的朋友一起，回答的是同伴；(D) 因為我遲到了，答非所問。故選 (C)。", "level": "A2", "topic": "transportation"}, {"id": "M341", "type": "vocab", "q": "Far from supporting the researchers' theory, the new data seriously ______ it, so the team had to go back to the drawing board.", "options": ["reinforced", "undermined", "illustrated", "anticipated"], "answer": 1, "explain": "句意：新資料非但沒有支持研究人員的理論，反而嚴重削弱了它，所以團隊只好從頭來過。Far from V-ing「非但不…」，可知資料與理論相互矛盾，undermine「削弱；動搖」符合語意。(A) reinforced 強化，與 far from supporting 矛盾 (C) illustrated 舉例說明 (D) anticipated 預料，皆無法說明團隊為何必須重新開始。故選 (B)。", "level": "C1", "topic": "scientific research"}, {"id": "M342", "type": "vocab", "q": "Because the early symptoms of the two illnesses are almost identical, doctors often find it difficult to ______ between them without a blood test.", "options": ["compensate", "negotiate", "collaborate", "differentiate"], "answer": 3, "explain": "句意：由於這兩種疾病的早期症狀幾乎相同，醫生若不驗血往往很難區分兩者。differentiate between A and B「區分 A 與 B」（＝ distinguish between A and B）。(A) compensate 補償（常接 for）(B) negotiate 協商 (C) collaborate 合作，皆不合語意。故選 (D)。", "level": "C1", "topic": "medicine"}, {"id": "M343", "type": "vocab", "q": "The novelist is admired for her ______ style: she can capture an entire life in a few carefully chosen sentences.", "options": ["concise", "verbose", "tedious", "ambiguous"], "answer": 0, "explain": "句意：這位小說家以簡潔的文風受到推崇：她只用幾句精心挑選的句子，就能寫出一個人的一生。concise「簡潔的」，與冒號後「用幾句話寫出一生」相呼應。(B) verbose 冗長囉嗦的，與文意相反 (C) tedious 冗長乏味的 (D) ambiguous 模稜兩可的，皆與「精心挑選的句子」不符。故選 (A)。", "level": "C1", "topic": "literature"}, {"id": "M344", "type": "vocab", "q": "Although the two leaders disagreed on almost everything, they managed to reach a ______ that allowed both sides to claim a partial victory.", "options": ["dilemma", "verdict", "compromise", "monopoly"], "answer": 2, "explain": "句意：雖然兩位領袖幾乎在每件事上都意見分歧，他們仍設法達成一項讓雙方都能宣稱獲得部分勝利的妥協。reach a compromise「達成妥協」，雙方各退一步，才會「都獲得部分勝利」。(A) dilemma 兩難的困境 (B) verdict 裁決，由陪審團或法官作出，而非雙方協商的結果 (D) monopoly 壟斷，皆不合語意。故選 (C)。", "level": "C1", "topic": "negotiation"}, {"id": "M345", "type": "vocab", "q": "Many of the town's young people have ______ to big cities in search of better jobs, leaving behind a population that grows older every year.", "options": ["migrated", "deteriorated", "evaporated", "retaliated"], "answer": 0, "explain": "句意：鎮上許多年輕人為了尋找更好的工作而遷移到大城市，留下的人口一年比一年老化。migrate「遷移」，常接 to + 地點。(B) deteriorated 惡化 (C) evaporated 蒸發；消失 (D) retaliated 報復，皆不合語意。故選 (A)。", "level": "C1", "topic": "rural communities"}, {"id": "M346", "type": "vocab", "q": "Since the new treatment has not yet been tested on humans, it would be ______ to promise patients that it will cure them.", "options": ["vulnerable", "inevitable", "spontaneous", "premature"], "answer": 3, "explain": "句意：由於這種新療法尚未在人體上試驗過，現在就向病人保證它能治好他們還言之過早。premature「過早的；為時尚早的」，常用 It is premature to V。(A) vulnerable 易受傷害的 (B) inevitable 不可避免的 (C) spontaneous 自發的，皆不合語意。故選 (D)。", "level": "C1", "topic": "medical research"}, {"id": "M347", "type": "vocab", "q": "The old law was finally ______ after decades of protest, so the practice it had banned became legal again.", "options": ["enforced", "repealed", "drafted", "violated"], "answer": 1, "explain": "句意：在數十年的抗議之後，這條舊法律終於被廢除，因此它原本禁止的行為又變得合法了。repeal「廢除（法律）」。(A) enforced 執行，若法律被執行，該行為仍屬違法 (C) drafted 起草，與「舊法律」不合 (D) violated 違反，法律被違反並不會使該行為變得合法。故選 (B)。", "level": "C1", "topic": "law"}, {"id": "M348", "type": "vocab", "q": "The volcano had been ______ for more than 300 years, so its sudden eruption took scientists completely by surprise.", "options": ["fertile", "turbulent", "dormant", "hostile"], "answer": 2, "explain": "句意：這座火山已經沉寂了三百多年，所以它突然噴發讓科學家完全措手不及。dormant「休眠的；暫時不活動的」，正因為長期休眠，噴發才出乎意料。(A) fertile 肥沃的 (B) turbulent 動盪的；洶湧的 (D) hostile 有敵意的，皆無法說明噴發為何令人意外。故選 (C)。", "level": "C1", "topic": "geology"}, {"id": "M349", "type": "vocab", "q": "Critics praised the documentary for its ______ portrayal of factory workers; instead of turning them into heroes or victims, it simply showed their lives as they were.", "options": ["sentimental", "exaggerated", "biased", "objective"], "answer": 3, "explain": "句意：評論家稱讚這部紀錄片對工廠工人的描繪十分客觀：它既不把他們塑造成英雄，也不把他們塑造成受害者，只是如實呈現他們的生活。objective「客觀的」。(A) sentimental 濫情的 (B) exaggerated 誇大的 (C) biased 有偏見的，都與「如實呈現」相反。故選 (D)。", "level": "C1", "topic": "film"}, {"id": "M350", "type": "vocab", "q": "Although it is ______ to blame the driver alone, investigators found that poor road design also played a major role in the accident.", "options": ["tempting", "reluctant", "eligible", "obligatory"], "answer": 0, "explain": "句意：雖然人們很容易想把責任全推給駕駛，但調查人員發現，不良的道路設計也是造成這起事故的主因之一。It is tempting to V「讓人忍不住想…；（做某事）很誘人」。(B) reluctant 不情願的，用來形容人，不用於 It is ___ to V 句型 (C) eligible 有資格的 (D) obligatory 義務的；強制的，皆不合語意。故選 (A)。", "level": "C1", "topic": "road safety"}, {"id": "M351", "type": "vocab", "q": "Norwegian and Swedish are so closely related that speakers of one can usually understand the other without formal study; linguists describe such languages as mutually ______.", "options": ["accessible", "beneficial", "intelligible", "exclusive"], "answer": 2, "explain": "句意：挪威語和瑞典語關係非常密切，說其中一種語言的人通常不必正式學習就能聽懂另一種；語言學家稱這類語言「可以互通」。mutually intelligible「彼此能理解的」，intelligible 意為「可理解的」。(A) accessible 可接近的 (B) beneficial 有益的（mutually beneficial 互惠的）(D) exclusive 排他的（mutually exclusive 互斥的），皆不合語意。故選 (C)。", "level": "C1", "topic": "languages"}, {"id": "M352", "type": "vocab", "q": "The scientist's claims were met with ______ at first, since no other laboratory had been able to reproduce her results.", "options": ["enthusiasm", "skepticism", "nostalgia", "hospitality"], "answer": 1, "explain": "句意：這位科學家的主張起初遭到質疑，因為沒有其他實驗室能夠重現她的研究結果。be met with skepticism「遭到懷疑」，與「無法重現結果」的原因相符。(A) enthusiasm 熱情 (C) nostalgia 懷舊 (D) hospitality 好客，皆不合語意。故選 (B)。", "level": "C1", "topic": "science"}, {"id": "M353", "type": "vocab", "q": "Rather than solving the problem, the new highway simply ______ traffic to the smaller roads nearby, which are now more crowded than ever.", "options": ["eliminated", "accelerated", "prohibited", "diverted"], "answer": 3, "explain": "句意：新的公路非但沒有解決問題，反而只是把車流轉移到附近較小的道路上，那些道路現在比以往更擁擠。divert「使轉向；轉移」，divert A to B 表示把 A 轉移到 B。(A) eliminated 消除，與「更擁擠」矛盾 (B) accelerated 加速 (C) prohibited 禁止，禁止車輛通行並不會使小路更擁擠。故選 (D)。", "level": "C1", "topic": "urban traffic"}, {"id": "M354", "type": "vocab", "q": "Her apology sounded ______: she was smiling as she said it, and she made exactly the same mistake the very next day.", "options": ["insincere", "spontaneous", "eloquent", "humble"], "answer": 0, "explain": "句意：她的道歉聽起來不真誠：她道歉時臉上還帶著笑，而且隔天就犯了一模一樣的錯。insincere「不真誠的」，冒號後的兩項描述都是證據。(B) spontaneous 自發的；即興的 (C) eloquent 口才好的；有說服力的 (D) humble 謙遜的，皆無法由後文推得。故選 (A)。", "level": "C1", "topic": "relationships"}, {"id": "M355", "type": "grammar", "q": "The safety inspector demanded that the factory ______ until every faulty machine had been replaced.", "options": ["is closed", "will be closed", "be closed", "was closing"], "answer": 2, "explain": "句意：安全稽查員要求工廠在所有故障機器都換新之前必須停工。demand（要求）屬於表示命令、要求的動詞，後接 that 子句時用「(should) + 原形動詞」；工廠是「被關閉」，故用被動 be closed。(A) is closed、(B) will be closed 為直述語氣 (D) was closing 為過去進行式，皆不符合此句型。故選 (C)。", "level": "C1", "topic": "subjunctive (demand that)"}, {"id": "M356", "type": "grammar", "q": "If Mia ______ so afraid of flying, she would have joined us on our trip to Hokkaido last winter.", "options": ["weren't", "hadn't", "wouldn't be", "isn't"], "answer": 0, "explain": "句意：要不是蜜雅這麼怕搭飛機，她去年冬天就會和我們一起去北海道旅行了。此為混合假設語氣：if 子句敘述與「現在（一向如此的）事實」相反的狀態（她到現在仍然怕搭飛機），用過去式 were（否定為 weren't）；主要子句敘述與「過去事實」相反的結果，用 would have + p.p.。(B) hadn't 後面缺少 been，文法錯誤 (C) if 子句中不可用 would (D) isn't 為直述語氣，無法與 would have joined 搭配。故選 (A)。", "level": "C1", "topic": "mixed conditional"}, {"id": "M357", "type": "grammar", "q": "It is not the long working hours but the lack of respect ______ drives many young nurses to leave the profession.", "options": ["what", "where", "whom", "that"], "answer": 3, "explain": "句意：促使許多年輕護理師離開這一行的，不是長時間的工作，而是缺乏尊重。此為強調句（分裂句）「It is + 被強調部分 + that + 其餘部分」，被強調的是主詞 not A but B，後接 that drives…。(A) what 本身含先行詞，不能接在被強調的名詞之後 (B) where 為關係副詞，後須接完整子句，此處卻缺主詞 (C) whom 為受格，不能作主詞。故選 (D)。", "level": "C1", "topic": "cleft sentence"}, {"id": "M358", "type": "grammar", "q": "______ twice by the same company, Jason decided to stop applying for jobs and start his own business instead.", "options": ["Rejecting", "Having been rejected", "Having rejected", "To reject"], "answer": 1, "explain": "句意：在被同一家公司拒絕兩次之後，傑森決定不再求職，改為自己創業。分詞構句的主詞與主要子句相同（Jason），傑森是「被拒絕」，且此事發生在做決定之前，故用完成式被動分詞 Having been rejected。(A) Rejecting、(C) Having rejected 為主動，表示傑森拒絕別人，與 by the same company 矛盾 (D) To reject 表目的，不合語意。故選 (B)。", "level": "C1", "topic": "perfect passive participle"}, {"id": "M359", "type": "grammar", "q": "Only by cutting greenhouse gas emissions sharply in this decade ______ to limit global warming to 1.5°C.", "options": ["we will be able", "will we be able", "we can be able", "can we be able"], "answer": 1, "explain": "句意：唯有在這十年內大幅削減溫室氣體排放，我們才能將全球暖化限制在攝氏 1.5 度以內。「Only + 副詞片語（by V-ing）」置於句首時，主要子句須倒裝，把助動詞 will 移到主詞 we 之前：will we be able。(A) 未倒裝 (C)(D) can 與 be able to 都表示能力，不可連用。故選 (B)。", "level": "C1", "topic": "inversion (only + adverbial)"}, {"id": "M360", "type": "grammar", "q": "______ for the quick action of a passenger who knew CPR, the man might not have survived his heart attack on the train platform.", "options": ["Had it been not", "Without it had been", "Had it not been", "Unless it had been"], "answer": 2, "explain": "句意：要不是一位會心肺復甦術的乘客迅速搶救，這名男子在月台上心臟病發時可能就活不下來了。「要不是…」與過去事實相反用 If it had not been for…，省略 if 後倒裝為 Had it not been for…，主要子句用 might/would have + p.p.。(A) Had it been not 語序錯誤，否定詞 not 應緊接在主詞 it 之後 (B) Without 為介系詞，後面不能接子句 (D) Unless 引導條件句，無法與 for 構成此句型。故選 (C)。", "level": "C1", "topic": "inverted conditional"}, {"id": "M361", "type": "grammar", "q": "______ she was after her twelve-hour shift, the doctor stayed to comfort the patient's worried family.", "options": ["Exhausted as", "As exhausted", "So exhausted", "Despite exhausted"], "answer": 0, "explain": "句意：雖然值完十二小時的班已經筋疲力盡，那位醫生還是留下來安慰病患憂心的家屬。「形容詞 + as + S + be」為表示讓步的倒裝句型，等於 Although she was exhausted。(B) As exhausted she was 語序錯誤 (C) So exhausted 須用「So + adj. + be + S + that…」表示「如此…以致於」，結構與語意皆不合 (D) Despite 為介系詞，後面不能直接接形容詞和子句。故選 (A)。", "level": "C1", "topic": "concession (adj. + as)"}, {"id": "M362", "type": "grammar", "q": "I'd rather you ______ photos of me online without asking me first; some of them are really embarrassing.", "options": ["don't post", "won't post", "not to post", "didn't post"], "answer": 3, "explain": "句意：我希望你不要沒先問過我就把我的照片貼到網路上，有些照片真的很尷尬。「would rather + S + 過去式」表示希望別人現在或未來（不要）做某事，屬於假設語氣，故用 didn't post。(A) don't post、(B) won't post 為直述語氣 (C) would rather 後接子句時不可用不定詞。故選 (D)。", "level": "C1", "topic": "would rather + past subjunctive"}, {"id": "M363", "type": "grammar", "q": "The last train ______, the stranded passengers had no choice but to spend the night at the station.", "options": ["had left", "to leave", "having left", "was leaving"], "answer": 2, "explain": "句意：末班車已經開走了，受困的乘客別無選擇，只能在車站過夜。此為獨立分詞構句：分詞的主詞（The last train）與主要子句的主詞（the stranded passengers）不同時，須保留自己的主詞；火車開走發生在前，故用完成式分詞 having left。(A) had left、(D) was leaving 為限定動詞，兩個子句之間沒有連接詞，形成錯誤的連寫句 (B) to leave 無法表示已經發生的原因。故選 (C)。", "level": "C1", "topic": "absolute construction"}, {"id": "M364", "type": "grammar", "q": "No sooner ______ the stage than the power went out, leaving the whole stadium in darkness.", "options": ["the singer had stepped onto", "had the singer stepped onto", "has the singer stepped onto", "was the singer stepping onto"], "answer": 1, "explain": "句意：歌手一踏上舞台就停電了，整座體育場陷入一片黑暗。「No sooner + had + S + p.p. + than + S + 過去式」表示「一…就…」，No sooner 置於句首時須倒裝；停電（went out）為過去式，踏上舞台發生得更早，故用過去完成式倒裝 had the singer stepped onto。(A) 未倒裝 (C) has 為現在完成式，與 went out 時態不符 (D) 此句型不用過去進行式。故選 (B)。", "level": "C1", "topic": "no sooner ... than"}, {"id": "M365", "type": "grammar", "q": "If the sun ______ to disappear suddenly, Earth would continue to receive its light for about eight more minutes.", "options": ["were", "has", "would", "was being"], "answer": 0, "explain": "句意：假如太陽突然消失，地球仍會繼續接收到它的光大約八分鐘。「If + S + were to + V, S + would + V」用來假設未來極不可能發生的情況。陽光從太陽傳到地球約需八分多鐘，所以光線還會持續一段時間。(B) has to disappear 意為「必須消失」，且為直述語氣，無法與 would continue 搭配 (C) if 子句中不用 would (D) was being to 結構錯誤。故選 (A)。", "level": "C1", "topic": "were to (unlikely future)"}, {"id": "M366", "type": "grammar", "q": "The museum received more than three hundred letters last year, most of ______ were written by children asking questions about dinosaurs.", "options": ["them", "it", "that", "which"], "answer": 3, "explain": "句意：博物館去年收到三百多封信，其中大部分是孩子寫來詢問恐龍問題的。「數量詞 + of + which/whom」可引導非限定形容詞子句，先行詞 letters 為物，故用 which。(A) them 為人稱代名詞，會使兩個子句之間缺少連接詞 (B) it 單複數不符，同樣缺少連接詞 (C) that 不能放在介系詞之後，也不能用於非限定子句。故選 (D)。", "level": "C1", "topic": "quantifier + of which"}, {"id": "M367", "type": "grammar", "q": "Little ______ that the dusty painting he had bought for NT$500 at a flea market was actually a valuable work by a famous artist.", "options": ["he knew", "knew he", "did he know", "he did know"], "answer": 2, "explain": "句意：他做夢也沒想到，自己在跳蚤市場用新台幣五百元買下的那幅滿是灰塵的畫，竟然是一位名畫家的珍貴作品。否定副詞 Little（＝ not at all）置於句首時，須倒裝為「助動詞 + S + 原形動詞」，故用 did he know。(A) he knew、(D) he did know 皆未倒裝 (B) knew he 倒裝方式錯誤，一般動詞須藉助 did 倒裝。故選 (C)。", "level": "C1", "topic": "inversion (little)"}, {"id": "M368", "type": "dialogue", "q": "A: I think the committee should approve the plan as it is. It's ready.\nB: ______ The budget section still has some numbers that don't add up.\nA: Fair point. Let's ask the finance team to check it again before we vote.", "options": ["I couldn't agree more.", "That's exactly what I was going to say.", "It's not my cup of tea.", "I'm not sure that's wise just yet."], "answer": 3, "explain": "A 認為委員會應照原樣通過計畫，B 接著指出預算部分仍有數字對不上，A 回應 Fair point（說得有道理）並建議先請財務組再檢查，可知 B 是委婉地表示不同意。I'm not sure that's wise just yet.（我不確定現在就這麼做是否明智）符合語境。(A) 我完全同意 (B) 那正是我要說的，都表示贊同，與後文矛盾 (C) 那不是我喜歡的類型，用於表達個人喜好，答非所問。故選 (D)。", "level": "C1", "topic": "meetings"}, {"id": "M369", "type": "dialogue", "q": "A: Did you hear that the city is going to turn the old sugar factory into an art park?\nB: ______ I've heard that rumor at least three times in the past five years.\nA: True, but this time the mayor has actually announced a budget for it.", "options": ["That's the best news I've heard all year!", "I'll believe it when I see it.", "Who told you I was going there?", "I wish I had gone with you."], "answer": 1, "explain": "B 說這個傳聞過去五年至少聽過三次，A 回應「沒錯，但這次市長真的公布預算了」，可知 B 對這個消息抱持懷疑。I'll believe it when I see it.（等我親眼看到才會相信）用來表達懷疑。(A) 這是我今年聽過最好的消息，語氣興奮，與後句的懷疑不符 (C) 誰告訴你我要去那裡 (D) 真希望我當時有和你一起去，皆答非所問。故選 (B)。", "level": "C1", "topic": "expressing doubt"}, {"id": "M370", "type": "dialogue", "q": "A: How did your presentation go? You were so worried about it.\nB: ______ The professor even asked if she could share my slides with next year's class.\nA: See? I told you there was nothing to worry about.", "options": ["Better than I could have hoped.", "Don't get me started.", "I wouldn't know where to begin.", "It went over my head."], "answer": 0, "explain": "B 接著說教授甚至問能不能把他的投影片分享給明年的學生，A 也回應「我就說沒什麼好擔心的吧」，可知報告非常成功。Better than I could have hoped.（比我所能期望的還要好）符合語境。(B) Don't get me started. 表示某件事讓人一提就有一肚子抱怨 (C) 我不知道該從哪裡說起，通常暗示情況很糟或很複雜 (D) It went over my head. 意為「我聽不懂」，皆與後文不符。故選 (A)。", "level": "C1", "topic": "presentations"}, {"id": "M371", "type": "dialogue", "q": "A: I'm thinking of quitting my part-time job to focus on the exam, but I'm worried about money.\nB: ______ Maybe you could ask your manager to cut your hours instead of quitting completely.\nA: That's a good idea. I hadn't thought of that.", "options": ["Money talks, you know.", "You should have quit a long time ago.", "Have you considered a middle ground?", "It's none of my business."], "answer": 2, "explain": "B 接著建議 A 請店長減少排班，而不是完全辭職，這是一種折衷的辦法，因此先問 Have you considered a middle ground?（你考慮過折衷的辦法嗎？）最合理。(A) 有錢好辦事，與後面的建議無關 (B) 你早就該辭職了，與後句「不要完全辭職」矛盾 (D) 這不關我的事，卻接著給建議，前後矛盾。故選 (C)。", "level": "C1", "topic": "giving advice"}, {"id": "M372", "type": "dialogue", "q": "A: Your essay makes some strong points, but the second half feels a bit rushed.\nB: ______ I was writing it at two in the morning.\nA: That explains it. Try to leave yourself a few extra days next time.", "options": ["Thanks, I spent weeks polishing it.", "I think you've misunderstood my main point.", "Could you speak a little louder?", "Guilty as charged."], "answer": 3, "explain": "A 指出文章後半段有點倉促，B 接著承認自己是凌晨兩點寫的，可知 B 坦然接受對方的批評。Guilty as charged.（我承認，確實如此）原為法庭用語，口語中常用來幽默地承認對方的指正。(A) 謝謝，我花了好幾週潤飾，與凌晨趕工矛盾 (B) 我想你誤解了我的重點，屬於反駁，與後句的承認不符 (C) 你能說大聲一點嗎，答非所問。故選 (D)。", "level": "C1", "topic": "feedback"}, {"id": "M373", "type": "dialogue", "q": "A: The flight to Singapore has been delayed again. It's now leaving at midnight.\nB: ______ We'd better call the hotel and tell them we won't be checking in until the small hours.\nA: Good idea. I'll also let our tour guide know.", "options": ["Well, that throws our whole schedule off.", "Not again! We'll have to cancel the whole trip.", "Then we'd better get a move on, or we'll miss our flight.", "So they've finally brought it forward?"], "answer": 0, "explain": "A 說飛往新加坡的班機再度延誤，改到午夜才起飛，B 接著建議打電話通知飯店要到凌晨才會入住，可知 B 先指出延誤打亂了原本的行程。Well, that throws our whole schedule off.（唉，這下我們整個行程都被打亂了）符合語境；throw off 意為「打亂」，the small hours 指「凌晨時分」。(B) 又來了！我們只好取消整趟旅行，與後句仍要通知飯店晚點入住矛盾 (C) 那我們得趕快，不然會錯過班機，班機延誤並不需要趕路 (D) 所以他們終於把班機提前了？與「延誤」相反。故選 (A)。", "level": "C1", "topic": "flight delays"}, {"id": "M374", "type": "dialogue", "q": "A: We'd like to offer you the position, with a starting salary of NT$38,000 a month.\nB: ______ Given my two years of experience, I was hoping for something closer to NT$42,000.\nA: Let me talk to the manager and see what we can do.", "options": ["That's more than generous. I accept.", "I really appreciate the offer, but is there any room for negotiation?", "I'm afraid I've never worked before.", "Could you tell me where the interview will be held?"], "answer": 1, "explain": "A 提出錄用條件與起薪，B 接著說以自己兩年的經驗，原本希望薪水接近四萬二，A 回應會去和經理談談，可知 B 是在禮貌地議價。I really appreciate the offer, but is there any room for negotiation?（很感謝您的提議，但薪資是否還有商量的空間？）符合語境。(A) 這已經非常優渥了，我接受，與後句爭取更高薪水矛盾 (C) 恐怕我從來沒工作過，與兩年經驗矛盾 (D) 能告訴我面試在哪裡舉行嗎，雙方已經在談錄用條件，答非所問。故選 (B)。", "level": "C1", "topic": "job offers"}, {"id": "M375", "type": "dialogue", "q": "A: I can't believe Jason took all the credit for our group project in front of the teacher.\nB: ______ He did the least work of all of us!\nA: Exactly. I think we should talk to him before we go to the teacher.", "options": ["Well, he deserves it, doesn't he?", "Don't be so hard on yourself.", "Tell me about it.", "I'll take your word for it."], "answer": 2, "explain": "A 抱怨傑森在老師面前把小組報告的功勞全攬在自己身上，B 接著說他是我們之中做最少的人，可知 B 和 A 有同感。Tell me about it.（可不是嘛！）用來表示強烈認同對方的抱怨。(A) 嗯，那是他應得的，不是嗎，與「他做得最少」矛盾 (B) 別對自己太苛刻，A 並沒有自責 (D) 我就相信你的話吧，用於自己無法確認的情況，但 B 也是組員，親身經歷此事。故選 (C)。", "level": "C1", "topic": "group projects"}, {"id": "M376", "type": "dialogue", "q": "A: Are you sure you want to sign up for both the debate team and the robotics club this semester?\nB: ______ I've already stopped my piano lessons to make time.\nA: Well, as long as you don't burn yourself out.", "options": ["No, I'm still on the fence about joining either one.", "My mind's made up — I've thought it through.", "Actually, I've decided to bow out of both.", "Let's not go there; the piano is a sore subject."], "answer": 1, "explain": "A 問 B 是否確定這學期要同時參加辯論隊和機器人社，B 接著說已經停掉鋼琴課來騰出時間，A 也提醒別把自己累垮，可知 B 心意已決。My mind's made up — I've thought it through.（我已經下定決心了，也仔細想清楚了）符合語境。(A) 不，我對要不要參加其中任何一個都還猶豫不決（on the fence 猶豫不決），與已經騰出時間矛盾 (C) 其實我決定兩個都退出（bow out 退出），與 A 提醒別累垮的回應不符 (D) 別提了，鋼琴是我的痛處（a sore subject 令人不愉快的話題），卻接著主動提起鋼琴課，前後矛盾。故選 (B)。", "level": "C1", "topic": "school clubs"}, {"id": "M377", "type": "dialogue", "q": "A: Excuse me, I ordered the vegetarian set, but this soup seems to have pieces of pork in it.\nB: ______ I'll have the kitchen prepare a fresh bowl for you right away, and it'll be on the house.\nA: Thank you. I appreciate how quickly you've handled this.", "options": ["That's impossible. Our chef never makes mistakes.", "Would you like to see the dessert menu?", "I'm afraid we don't accept complaints after the meal.", "Please accept my apologies — there must have been a mix-up in the kitchen."], "answer": 3, "explain": "A 指出自己點的是素食套餐，湯裡卻有豬肉，B 接著說會請廚房立刻重做一碗並免費招待，可知 B 先為出錯道歉。Please accept my apologies — there must have been a mix-up in the kitchen.（非常抱歉，一定是廚房弄錯了）符合語境；mix-up 意為「混淆；弄錯」，on the house 意為「店家招待、免費」。(A) 不可能，我們主廚從不出錯，與後面主動重做矛盾 (B) 您想看看甜點菜單嗎，答非所問 (C) 恐怕我們用餐後不接受客訴，與後句的補救措施矛盾。故選 (D)。", "level": "C1", "topic": "restaurant complaints"}, {"id": "M378", "type": "dialogue", "q": "A: The weather app says there's a 70 percent chance of thunderstorms on Saturday afternoon.\nB: ______ Why don't we start the hike at dawn and be off the mountain by noon?\nA: Good thinking. I'll set my alarm for five.", "options": ["Then we'd better not take any chances.", "Great, the rain will make the trail less slippery.", "Let's cancel the trip and stay home all weekend.", "Seventy percent? That means it definitely won't rain."], "answer": 0, "explain": "A 說週六下午有七成機率會有雷陣雨，B 接著建議天一亮就出發、中午前下山，可知 B 主張避開風險。Then we'd better not take any chances.（那我們最好別冒險）符合語境。(B) 太好了，雨會讓步道比較不滑，不合常理 (C) 我們取消行程，整個週末待在家，與後句仍要去爬山矛盾 (D) 七成？那表示一定不會下雨，邏輯錯誤。故選 (A)。", "level": "C1", "topic": "outdoor plans"}, {"id": "M379", "type": "dialogue", "q": "A: I've read the article twice, but I still don't see how the author reaches her conclusion.\nB: ______ She jumps from one small survey to a claim about the whole country.\nA: So it's not just me. I thought I was missing something.", "options": ["It's crystal clear if you read it carefully.", "Maybe you should read it a third time.", "That's because her argument doesn't hold water.", "I've never heard of that author."], "answer": 2, "explain": "A 說讀了兩遍仍看不懂作者如何得出結論，B 接著指出作者從一份小規模調查直接跳到關於全國的主張，A 回應「原來不只是我看不懂」，可知 B 認為問題出在作者的論證。That's because her argument doesn't hold water.（那是因為她的論點根本站不住腳）符合語境；hold water 意為「（論點）站得住腳」，多用於否定句。(A) 只要仔細讀就非常清楚了 (B) 也許你該讀第三遍，都暗示是 A 的問題，與 A 的回應不符 (D) 我從沒聽過那位作者，與後句評論文章內容矛盾。故選 (C)。", "level": "C1", "topic": "critical reading"}, {"id": "M380", "type": "dialogue", "q": "A: I heard you're moving to Hsinchu for your new job. How do you feel about it?\nB: ______ I'm excited about the work, but I'll really miss my friends here in Tainan.\nA: I know what you mean. But it's less than two hours away by high-speed rail.", "options": ["I'm over the moon about it.", "Honestly, it's a bit bittersweet.", "Actually, the move has fallen through.", "Frankly, I can't get out of here fast enough."], "answer": 1, "explain": "A 問 B 對於搬到新竹工作有什麼感受，B 接著說對工作感到興奮，但會很想念台南的朋友，可知 B 悲喜交加。Honestly, it's a bit bittersweet.（老實說，心情有點苦樂參半）符合語境；bittersweet 意為「苦樂參半的」。(A) 我高興極了（over the moon 欣喜若狂）(D) 坦白說，我巴不得趕快離開這裡，都只表達單一情緒，與「會想念朋友」不符 (C) 其實搬家的事已經告吹了（fall through 落空；告吹），與後文 A 談論新竹離台南多遠矛盾。故選 (B)。", "level": "C1", "topic": "moving"}, {"id": "M381", "type": "vocab", "q": "Several factors ______ against the success of the new shopping district, not least the fact that no one had ever asked local residents what they actually wanted.", "options": ["mitigated", "militated", "mediated", "meditated"], "answer": 1, "explain": "句意：有好幾個因素不利於新商圈的成功，尤其是從來沒有人問過當地居民真正想要的是什麼。militate against sth 意為「（因素、情況）對…產生不利影響；妨礙」，常用來說明某事難以成功；not least 意為「尤其是」。(A) mitigated 減輕；緩和，為及物動詞（如 mitigate the damage），「mitigate against」是常見誤用，語意也不合 (C) mediated 調解，常用 mediate between A and B (D) meditated 沉思；冥想，常用 meditate on，皆不能接 against 表示「不利於」。故選 (B)。", "level": "C2", "topic": "urban planning"}, {"id": "M382", "type": "grammar", "q": "Nowhere ______ the effects of rising sea levels more visible than on some low-lying Pacific islands, where entire villages have already had to move to higher ground.", "options": ["is", "have", "are", "do"], "answer": 2, "explain": "句意：海平面上升的影響，沒有哪裡比某些地勢低窪的太平洋島嶼更明顯，那裡已經有整座村莊不得不遷往地勢較高的地方。否定副詞 Nowhere 置於句首時須倒裝；本句的主要動詞是 be 動詞（後接形容詞補語 more visible），倒裝為「be + S + 補語」。真正的主詞是複數的 the effects（of rising sea levels 只是修飾語），故用 are。(A) is 與複數主詞 the effects 不一致 (B) have 後面缺少 been，句中沒有過去分詞，結構不完整 (D) do 是一般動詞的助動詞，但句中沒有原形動詞，形容詞補語 more visible 前需要 be 動詞。故選 (C)。", "level": "C2", "topic": "inversion (nowhere)"}, {"id": "M383", "type": "dialogue", "q": "A: Your older brother seemed a little annoyed when he found out you'd borrowed his scooter without asking.\nB: ______ He didn't say a single word to me for a whole week.\nA: Ouch. Maybe next time you should ask first.", "options": ["That's putting it mildly.", "Speak for yourself.", "He took it in his stride.", "He didn't bat an eyelid."], "answer": 0, "explain": "句意：A 說 B 的哥哥發現 B 沒問一聲就借走他的機車時，似乎有點不高興；B 回答「這麼說還太客氣了」，接著說哥哥整整一個星期都沒跟他說一句話；A 說「哎唷，下次還是先問一聲吧」。That's putting it mildly. 意為「這麼說太輕描淡寫了；實際情況嚴重得多」，正好回應 A 口中的 a little annoyed，並由後文的冷戰一週佐證。(B) Speak for yourself.「那只是你自己的情況／看法，別把我算進去」，用於反駁對方以偏概全，與語境不符 (C) He took it in his stride.「他泰然處之」(D) He didn't bat an eyelid.「他眉頭都沒皺一下」，兩者都表示哥哥毫不在意，與一週不講話矛盾。故選 (A)。", "level": "C2", "topic": "sibling conflict"}, {"id": "M384", "type": "vocab", "q": "Only the most ______ reader would believe a website claiming that a single herbal tea can cure every known disease.", "options": ["credible", "creditable", "incredulous", "credulous"], "answer": 3, "explain": "句意：只有最容易輕信的讀者，才會相信一個聲稱單單一種草本茶就能治好所有已知疾病的網站。credulous「輕信的；容易上當的」，用來形容人。(A) credible「可信的」，通常形容說法、證據或消息來源可靠，不是形容「輕易相信」的讀者 (B) creditable「值得稱讚的」(C) incredulous「不肯相信的；表示懷疑的」，與 would believe 正好相反。故選 (D)。", "level": "C2", "topic": "media literacy"}, {"id": "M385", "type": "grammar", "q": "Walking into the bakery early that morning, ______.", "options": ["the smell of fresh bread filled the air", "I was greeted by the smell of fresh bread", "the smell of fresh bread greeted me", "there was a wonderful smell of fresh bread"], "answer": 1, "explain": "句意：那天一大早我一走進麵包店，新鮮麵包的香味就迎面撲來。分詞構句 Walking into the bakery 省略了主詞，其邏輯主詞必須與主要子句的主詞相同；會「走進麵包店」的只有人，所以主要子句須以 I 為主詞，用被動語態 I was greeted by... 。(A)(C) 主詞是 the smell of fresh bread，變成「麵包香味走進麵包店」(D) 主詞是虛主詞 there，三者都造成分詞與主要子句主詞不一致的「懸垂分詞」（dangling participle）錯誤。故選 (B)。", "level": "C2", "topic": "dangling participle"}, {"id": "M386", "type": "dialogue", "q": "A: So you still haven't managed to get tickets for the concert?\nB: ______ I was online the second they went on sale, but they sold out in less than a minute.\nA: That's a shame. Maybe they'll add another show.", "options": ["Not that I'm aware of.", "Not on your life.", "Not for want of trying.", "Not to worry."], "answer": 2, "explain": "句意：A 問 B 是不是還沒買到演唱會的票；B 回答「可不是因為我不夠努力」，接著說開賣那一秒就上網搶了，但票不到一分鐘就賣光；A 說真可惜，也許主辦單位會加場。Not for want of trying. 意為「並不是因為沒有努力（而是事與願違）」，want 在此作「缺乏」解。(A) Not that I'm aware of.「據我所知沒有」，用於自己不確定的事，但買票是 B 親身的經驗 (B) Not on your life.「門都沒有；絕對不要」，用於斷然拒絕 (D) Not to worry.「別擔心」，用於安慰對方，與後面說明搶票失敗接不上。故選 (C)。", "level": "C2", "topic": "concert tickets"}, {"id": "M387", "type": "vocab", "q": "Despite three years of falling sales, the founder remained ______ about the company's future, insisting that the new product line would turn things around.", "options": ["sanguine", "despondent", "ambivalent", "indifferent"], "answer": 0, "explain": "句意：儘管營業額已經連續三年下滑，這位創辦人對公司的前景依然樂觀，堅稱新的產品線會扭轉局面。sanguine「（尤指在困境中）樂觀的；充滿信心的」，與 insisting that... would turn things around 相呼應。(B) despondent「沮喪的；灰心的」，與堅信情況會好轉相反 (C) ambivalent「心情矛盾的；舉棋不定的」(D) indifferent「漠不關心的」，兩者都與「堅稱」所表現的篤定與投入不符。故選 (A)。", "level": "C2", "topic": "business outlook"}, {"id": "M388", "type": "grammar", "q": "Such ______ the demand for tickets that the booking website crashed within minutes of going live.", "options": ["were", "did", "had", "was"], "answer": 3, "explain": "句意：門票的需求量大到訂票網站一開放，短短幾分鐘內就當機了。「Such + be + S + that 子句」是 such 置於句首的倒裝句，意為「…是如此之大，以致於…」，相當於 The demand for tickets was such that...。主詞 the demand 為單數，且全句為過去時態，故用 was。(A) were 與單數主詞 the demand 不一致 (B) did (C) had 都是助動詞，後面缺少主要動詞，無法與 the demand 構成完整子句。故選 (D)。", "level": "C2", "topic": "inversion (such + be)"}, {"id": "M389", "type": "dialogue", "q": "A: Did you know that the Great Wall of China is the only man-made structure you can see from the Moon with the naked eye?\nB: Actually, that's a myth. Astronauts who went to the Moon have said it can't be seen from that far away.\nA: ______ I've believed that since I was in elementary school.", "options": ["That's beside the point.", "Well, I stand corrected.", "You can say that again.", "No harm done."], "answer": 1, "explain": "句意：A 說萬里長城是唯一能從月球上用肉眼看到的人造建築；B 說那其實是個迷思，登上過月球的太空人都說從那麼遠的地方是看不到的；A 回答「好吧，是我說錯了」，並說自己從國小就一直這麼相信。I stand corrected. 意為「我承認我錯了」，是被別人糾正後有風度的回應。(A) That's beside the point.「那不是重點」，但能不能看見長城正是兩人討論的重點 (C) You can say that again.「說得一點也沒錯」，表示早有同感，與 A 一直相信這個說法、剛剛才被糾正矛盾 (D) No harm done.「沒什麼損失；沒關係」，用於原諒向自己道歉的人，但 B 並沒有道歉。故選 (B)。", "level": "C2", "topic": "common myths"}, {"id": "M390", "type": "vocab", "q": "Many companies pay ______ service to environmental protection, publishing glossy reports about going green while doing little to cut their own emissions.", "options": ["mouth", "tongue", "lip", "word"], "answer": 2, "explain": "句意：許多公司對環境保護只是口頭上說說，一面發表精美的綠色環保報告，一面卻幾乎沒有減少自身的排放。pay lip service to sth 為固定用語，意為「口頭上支持；嘴上說說而不付諸行動」。(A) mouth (B) tongue (D) word 雖然都與說話有關，但都不能與 pay ... service to 搭配成這個慣用語。故選 (C)。", "level": "C2", "topic": "corporate responsibility"}, {"id": "M391", "type": "grammar", "q": "It was only when the power went out for three whole days ______ how much we depend on electricity.", "options": ["that we realized", "did we realize", "we realized that", "when we realized"], "answer": 0, "explain": "句意：直到停電整整三天，我們才發現自己有多麼依賴電力。本句是強調句（分裂句）「It was + 被強調部分 + that + 其餘部分」，被強調的是時間副詞子句 only when the power went out...，其後接 that 與正常語序的子句。(B) did we realize 是把 Only when... 直接放在句首時才需要的倒裝，用了 It was... that 強調句就不再倒裝 (C) we realized that 少了強調句中緊接在被強調部分之後的 that，而且 realized that how much... 中 that 與 how 重複引導同一個名詞子句，不合文法 (D) when we realized 重複 when，強調句不用 when 連接。故選 (A)。", "level": "C2", "topic": "cleft sentence (it was only when)"}, {"id": "M392", "type": "dialogue", "q": "A: The landlord has promised to fix the leaking roof by the end of this week.\nB: ______ He's been saying that since March.\nA: I know, but this time he actually sounded serious.", "options": ["Better late than never.", "That's a weight off my mind.", "He's a man of his word, then.", "I wouldn't hold your breath."], "answer": 3, "explain": "句意：A 說房東答應這個週末前會修好漏水的屋頂；B 回答「我看你別抱太大期望」，因為房東從三月就一直這麼說；A 說「我知道，但這次他聽起來是認真的」。I wouldn't hold your breath. 意為「（換作是我）可不會抱太大期望」，表示懷疑某事會很快發生，與後文房東從三月起一再拖延相呼應。(A) Better late than never.「遲到總比不到好」，用於事情終於完成時，但屋頂根本還沒修 (B) That's a weight off my mind.「這下我可放心了」，與 B 懷疑的語氣相反 (C) He's a man of his word, then.「那他真是說話算話」，與房東一再食言矛盾。故選 (D)。", "level": "C2", "topic": "housing"}, {"id": "M393", "type": "vocab", "q": "Asked whether the new drug was safe for children, the researcher was deliberately ______: she described the results as 'promising but not yet conclusive' and refused to commit herself either way.", "options": ["emphatic", "equivocal", "categorical", "unanimous"], "answer": 1, "explain": "句意：被問到這種新藥對兒童是否安全時，那位研究人員刻意含糊其詞：她把結果形容為「很有希望，但尚無定論」，拒絕表明任何一方的立場。equivocal「模稜兩可的；含糊其詞的」，冒號後的說明正是證據。(A) emphatic「語氣強烈的；斷然的」(C) categorical「絕對的；毫不含糊的」，兩者都與 refused to commit herself either way 矛盾 (D) unanimous「全體一致的」，用於形容一群人的意見，不能用來形容一個人的回答。故選 (B)。", "level": "C2", "topic": "science communication"}, {"id": "M394", "type": "grammar", "q": "Grace wrote the new Wi-Fi password on a sticky note and stuck it on the fridge, lest she ______ it again.", "options": ["forgets", "not forget", "forget", "will forget"], "answer": 2, "explain": "句意：Grace 把新的 Wi-Fi 密碼寫在便利貼上，貼在冰箱上，以免自己又忘記。lest 意為「以免；唯恐」，屬正式用語，其後子句用原形動詞（假設語氣）或 should + 原形動詞，故寫成 lest she forget it（＝ lest she should forget it）。(A) forgets 用第三人稱單數現在式 (D) will forget 用 will，兩者都不符合 lest 後接原形動詞（或 should + 原形）的規則，時態也與全句的過去式不合 (B) not forget 多了 not：lest 本身已含「以免」的否定意味，再加 not 會變成「以免記得」，語意相反。故選 (C)。", "level": "C2", "topic": "lest + subjunctive"}, {"id": "M395", "type": "dialogue", "q": "A: I've signed up for a full marathon in December — all 42.195 kilometers of it.\nB: ______ I get out of breath just climbing the stairs at the MRT station.\nA: Ha! You could always start with a shorter race next year.", "options": ["Rather you than me!", "Count me in!", "You're telling me!", "Now you're talking!"], "answer": 0, "explain": "句意：A 說自己報名了十二月的全程馬拉松，要跑完整整 42.195 公里；B 說「還好要跑的是你不是我！」，因為自己光是爬捷運站的樓梯就喘不過氣；A 笑著說 B 明年可以先從短一點的比賽開始。Rather you than me. 意為「幸好要做這件事的是你而不是我」，表示自己絕不想做對方要做的苦差事，與 B 體力不好的說明吻合。(B) Count me in!「算我一份！」(D) Now you're talking!「這才像話！；這主意不錯！」，兩者都表示 B 想參加或很贊成，與後文不合 (C) You're telling me!「還用你說！（我深有同感）」，用於附和對方的抱怨，但 A 並沒有抱怨什麼。故選 (A)。", "level": "C2", "topic": "marathons"}, {"id": "M396", "type": "vocab", "q": "From the way she kept glancing at the clock and answering in single words, I ______ that she wanted the meeting to end as soon as possible.", "options": ["implied", "insinuated", "alluded", "inferred"], "answer": 3, "explain": "句意：從她一直瞄時鐘、回話都只用單字的樣子，我推斷她希望會議盡快結束。infer「（根據線索）推斷；推論」，主詞是接收訊息、做出判斷的人。(A) implied「暗示」，是傳達訊息的人（她）所做的事，與主詞 I 不合 (B) insinuated「（拐彎抹角地）暗示（負面的事）」，同樣是說話者的行為，且帶貶意 (C) alluded「間接提及」，須用 allude to sth，不能直接接 that 子句。故選 (D)。", "level": "C2", "topic": "body language"}, {"id": "M397", "type": "grammar", "q": "Few people believed the student team could build a working robot in just two weeks, but build one they ______.", "options": ["had", "did", "were", "do"], "answer": 1, "explain": "句意：很少人相信這支學生隊伍能在短短兩週內做出一台能運作的機器人，但他們真的做出來了。這是把動詞片語移到句首以加強語氣的「前置」（fronting）結構：but they did build one → but build one they did，句首動詞 build 用原形，句尾留下助動詞 did，表示「確實做到了」。(A) had 須搭配過去分詞 built (C) were 須搭配 building 或 built (D) do 為現在式，與全句的過去時態不合。故選 (B)。", "level": "C2", "topic": "fronting for emphasis"}, {"id": "M398", "type": "dialogue", "q": "A: Do you know when the new MRT line near our school is finally going to open?\nB: ______ The opening date has already been pushed back three times.\nA: Typical. I'll believe it when I see the first train.", "options": ["It goes without saying.", "It's a done deal.", "It's anyone's guess.", "It's on the tip of my tongue."], "answer": 2, "explain": "句意：A 問 B 學校附近的新捷運線到底什麼時候會通車；B 回答「誰也說不準」，因為通車日期已經延後三次了；A 說「老是這樣，我要看到第一班車才會相信」。It's anyone's guess. 意為「沒有人知道；誰也說不準」。(A) It goes without saying.「那是不用說的」，無法回答「什麼時候」的問題 (B) It's a done deal.「已經是定案了」，與一再延期矛盾 (D) It's on the tip of my tongue.「話就在嘴邊（一時想不起來）」，暗示有確切日期只是 B 忘了，與後文日期一延再延不合。故選 (C)。", "level": "C2", "topic": "public transport"}, {"id": "M399", "type": "vocab", "q": "Far from suffering from a ______ of choice, today's shoppers are often overwhelmed by the sheer number of options, from dozens of brands of toothpaste to hundreds of streaming shows.", "options": ["dearth", "plethora", "surfeit", "profusion"], "answer": 0, "explain": "句意：現今的消費者非但不缺選擇，反而常因選項多到數不清而不知所措，從數十種牙膏品牌到數百部串流影集都是如此。Far from... 意為「非但不…（反而）」，前後兩部分語意相反；後半句說選項多到令人招架不住，所以前半句應是「缺乏」，dearth「缺乏；不足」。(B) plethora「過多」(C) surfeit「過量」(D) profusion「大量；豐富」，三者都表示「很多」，與後半句意思相同而非相反，不合 Far from 的邏輯。故選 (A)。", "level": "C2", "topic": "consumer choice"}, {"id": "M400", "type": "vocab", "q": "The hotel staff were so ______ that guests barely noticed them, yet every request was handled within minutes and nothing a guest told them was ever repeated to anyone else.", "options": ["discrete", "obtrusive", "garrulous", "discreet"], "answer": 3, "explain": "句意：這家飯店的員工非常低調謹慎，客人幾乎察覺不到他們的存在，然而每項要求都在幾分鐘內處理好，客人跟他們說過的話也從不外傳。discreet「謹慎的；低調而守口如瓶的」，兼具「不引人注意」與「保密」兩層意思。(A) discrete「各自獨立的；分開的」，與 discreet 發音相同但意義完全不同 (B) obtrusive「惹人注意的；礙眼的」，與 barely noticed 矛盾 (C) garrulous「喋喋不休的；多嘴的」，與從不外傳矛盾。故選 (D)。", "level": "C2", "topic": "hospitality"}, {"id": "M401", "type": "grammar", "q": "Some of the volunteers had done this kind of work before; most, however, ______, so the whole first morning was spent on basic training.", "options": ["did not", "had not", "were not", "have not"], "answer": 1, "explain": "句意：有些志工以前做過這類工作，然而大多數人沒有，所以第一天整個上午都用來做基礎訓練。這是省略句：most, however, had not (done this kind of work before)，省略重複部分時，須保留與前文動詞時態一致的助動詞；前句用過去完成式 had done，故用 had not。(A) did not 與 had done 的時態不一致 (C) were not 用 be 動詞，無法代替 had done (D) have not 為現在完成式，與前句時態不一致。故選 (B)。", "level": "C2", "topic": "ellipsis (auxiliary)"}, {"id": "M402", "type": "dialogue", "q": "A: Honestly, I think we should just cancel the class trip this year. Organizing it is far too much trouble.\nB: ______ But wouldn't that be a real letdown for everyone who's been looking forward to it?\nA: Hmm, I suppose you have a point.", "options": ["I can see where you're coming from.", "I'm afraid I don't follow.", "I couldn't agree with you more.", "That's the most ridiculous idea I've ever heard."], "answer": 0, "explain": "句意：A 說今年乾脆取消班遊算了，籌辦起來實在太麻煩；B 說「我能理解你為什麼這麼想」，但又反問：這樣不會讓期待已久的同學大失所望嗎？A 說「嗯，你說得也有道理」。I can see where you're coming from. 意為「我明白你的出發點」，先表示理解再委婉提出不同意見，是有禮貌的反對方式，與後面以 But 開頭的反問相呼應。(B) I'm afraid I don't follow.「恐怕我聽不太懂」，但 B 顯然聽懂了 A 的意思 (C) I couldn't agree with you more.「我完全同意」，與後面的反問矛盾 (D) That's the most ridiculous idea I've ever heard.「這是我聽過最荒謬的主意」，語氣過於尖銳且已全盤否定，後面不會再接 But 的委婉讓步語氣。故選 (A)。", "level": "C2", "topic": "diplomatic disagreement"}, {"id": "M403", "type": "grammar", "q": "I ______ an umbrella after all. The rain had stopped by the time I left the station, so I ended up carrying it around all day for nothing.", "options": ["ought to have brought", "can't have brought", "needn't have brought", "might have brought"], "answer": 2, "explain": "句意：結果我根本不必帶傘。我離開車站時雨已經停了，最後整天白白拎著它到處走。needn't have + p.p. 表示「過去做了某事，但其實沒有必要」，與 for nothing（白費）呼應。(A) ought to have brought「早該帶（但沒帶）」，與說話者確實帶了傘矛盾 (B) can't have brought「不可能帶了」，是對過去的否定推測，但說話者整天都拎著傘 (D) might have brought「可能帶了」，是不確定的推測，說話者對自己確實帶了傘一事無須猜測。故選 (C)。", "level": "C2", "topic": "needn't have p.p."}, {"id": "M404", "type": "vocab", "q": "Since the study was funded by a company that sells the very supplement being tested, critics argue that the authors' ______ interest in the outcome may have influenced their conclusions.", "options": ["invested", "vested", "vexed", "vacant"], "answer": 1, "explain": "句意：由於這項研究是由一家販售受測營養補充品的公司出資，評論者認為，作者們與研究結果之間的利害關係可能影響了他們的結論。vested interest「既得利益；切身的利害關係」為固定搭配。(A) invested 是常見的誤用，正確的慣用語是 vested interest (C) vexed「令人頭痛的；爭議不休的」，常用於 a vexed question (D) vacant「空的；茫然的」，皆無法與 interest 構成此意。故選 (B)。", "level": "C2", "topic": "research ethics"}, {"id": "M405", "type": "dialogue", "q": "A: Sorry to bother you, but I've got an exam at eight tomorrow morning, and the walls in this building are pretty thin.\nB: ______ I'll turn the music down right away.\nA: Thanks so much. I really appreciate it.", "options": ["What's that got to do with me?", "Be my guest.", "Don't mention it.", "Say no more."], "answer": 3, "explain": "句意：A 說抱歉打擾，自己明天早上八點要考試，而這棟樓的牆壁很薄；B 回答「不用多說了」，表示馬上把音樂關小聲；A 道謝。A 並未直接提出要求，而是用暗示委婉地請 B 降低音量；Say no more. 意為「不必再說，我懂了」，表示立即領會對方的言外之意。(A) What's that got to do with me?「那跟我有什麼關係？」，與 B 立刻調小音樂矛盾 (B) Be my guest.「請便」，用於允許對方做某事，但 A 並不是在徵求許可 (C) Don't mention it.「不客氣」，是回應道謝的用語，A 此時並沒有道謝。故選 (D)。", "level": "C2", "topic": "indirect requests"}, {"id": "M406", "type": "grammar", "q": "The last bus left ten minutes ago, so we ______ start walking. Come on — it's only twenty minutes to the dorm.", "options": ["may as well", "may well", "used to", "needn't"], "answer": 0, "explain": "句意：末班公車十分鐘前就開走了，所以我們不如開始用走的吧。走吧，到宿舍只要二十分鐘。may as well + 原形動詞 意為「（既然沒有更好的選擇）不妨…；倒不如…」，用來提出建議，與後面的 Come on 呼應。(B) may well「很可能」，表示推測而非建議 (C) used to「過去常常」，表示過去的習慣，與眼前的情況不合 (D) needn't「不必」，與後面催促出發的 Come on 矛盾。故選 (A)。", "level": "C2", "topic": "may as well vs may well"}, {"id": "M407", "type": "vocab", "q": "Drivers who openly ______ the speed limit outside schools put children at risk and should face much heavier fines.", "options": ["flaunt", "tout", "flout", "vaunt"], "answer": 2, "explain": "句意：在學校附近公然無視速限的駕駛人，會讓孩童身陷危險，應該處以更重的罰款。flout「公然違抗；藐視（法律、規定）」。(A) flaunt「炫耀；賣弄」，常被誤用來代替 flout，但意思完全不同 (B) tout「吹捧；兜售」(D) vaunt「誇耀」，皆無法與 the speed limit 搭配表示違規。故選 (C)。", "level": "C2", "topic": "traffic enforcement"}, {"id": "M408", "type": "dialogue", "q": "A: Do you really think Eric would copy someone else's homework and hand it in as his own?\nB: ______ He's been caught doing exactly that twice before.\nA: Wow. I had no idea.", "options": ["He wouldn't dream of it.", "I wouldn't put it past him.", "It's completely out of character for him.", "Let's give him the benefit of the doubt."], "answer": 1, "explain": "句意：A 問 B 是否真的認為 Eric 會抄別人的作業，當成自己的交出去；B 回答「他做得出這種事」，因為他之前就有兩次被抓到這麼做；A 說「哇，我完全不知道」。I wouldn't put it past sb (to do sth). 意為「我認為某人做得出這種（不好的）事」。(A) He wouldn't dream of it.「他想都不會想去做」(C) It's completely out of character for him.「這完全不像他的作風」(D) Let's give him the benefit of the doubt.「我們姑且相信他吧」，三者都在替 Eric 說話，與他曾兩度被抓的事實矛盾。故選 (B)。", "level": "C2", "topic": "judging character"}, {"id": "M409", "type": "grammar", "q": "The former coach is widely reported ______ the decision to drop the team captain from the starting lineup at a closed-door meeting last month, although he has never commented on it in public.", "options": ["to oppose", "having opposed", "that he opposed", "to have opposed"], "answer": 3, "explain": "句意：據多方報導，前任教練曾在上個月的一場閉門會議中反對把隊長撤出先發陣容的決定，不過他從未公開評論此事。「S + be reported + to V」是被動的報導句型（＝ It is reported that S...）；「報導」是現在的事，而「反對」發生在過去（last month），須用完成式不定詞 to have + p.p.。(A) to oppose 表示與報導同時或現在的情況，與 last month 不合 (B) having opposed 動名詞不能接在 be reported 之後 (C) that he opposed 須用 It is reported that he opposed... 的句型，不能以 the former coach 當主詞。故選 (D)。", "level": "C2", "topic": "passive reporting verb + perfect infinitive"}, {"id": "M410", "type": "vocab", "q": "The speaker's flat, monotonous voice, combined with the warm and stuffy hall, proved so ______ that several people in the audience were nodding off within minutes.", "options": ["soporific", "exhilarating", "incendiary", "abrasive"], "answer": 0, "explain": "句意：講者平淡單調的聲音，加上又熱又悶的會場，令人昏昏欲睡，台下好幾個人不到幾分鐘就打起瞌睡。soporific「催眠的；令人昏昏欲睡的」，與 nodding off 相呼應。(B) exhilarating「令人振奮的」，與打瞌睡相反 (C) incendiary「煽動性的」(D) abrasive「粗魯的；刺耳的」，都不會使人想睡。故選 (A)。", "level": "C2", "topic": "public speaking"}, {"id": "M411", "type": "dialogue", "q": "A: Oh, how nice of you to finally show up. The movie started forty minutes ago.\nB: ______ My bus broke down halfway here, and my phone died, so I couldn't even call you.\nA: Fine. Let's just go in and catch the rest of it.", "options": ["Thanks! It's great to be here.", "Relax — I'm actually early for once.", "I know, I know — I'm really sorry.", "No need to thank me."], "answer": 2, "explain": "句意：A 說「你終於肯出現了，真是感謝喔」，電影四十分鐘前就開演了；B 回答「我知道、我知道，真的很對不起」，並解釋公車半路拋錨、手機又沒電，所以連電話都沒辦法打；A 說「算了，我們進去看剩下的吧」。A 的 How nice of you to finally show up 是反話，其實是在抱怨 B 遲到；B 聽出言外之意，先道歉再說明原因最恰當。(A) Thanks! It's great to be here. 把反話當成真心的歡迎，與後面解釋遲到原因不搭 (B) Relax — I'm actually early for once. 說自己難得早到，與電影已開演四十分鐘矛盾 (D) No need to thank me. 誤以為 A 在向自己道謝。故選 (C)。", "level": "C2", "topic": "sarcasm"}, {"id": "M412", "type": "grammar", "q": "______ not for the generous donations of local residents, the animal shelter would have to close its doors.", "options": ["Had it", "Were it", "If it", "Was it"], "answer": 1, "explain": "句意：要不是有當地居民的慷慨捐款，這間動物收容所就得關門了。與現在事實相反的假設可寫成 If it were not for...，省略 if 後倒裝為 Were it not for...，主要子句用 would + 原形動詞（would have to close）。(A) Had it 填入後成為 Had it not for，缺少 been；須寫成 Had it not been for，通常用於與過去事實相反，不合本句結構 (C) If it 後面缺少動詞 were，用 if 時不能省略 were (D) Was it 不合假設語氣倒裝的用法，倒裝時須用 were。故選 (B)。", "level": "C2", "topic": "inverted conditional (were it not for)"}, {"id": "M413", "type": "vocab", "q": "No one had ever said so out loud, but there was a ______ understanding among the staff that the failed project was never to be mentioned again.", "options": ["formal", "verbal", "written", "tacit"], "answer": 3, "explain": "句意：雖然從來沒有人說出口，但員工之間有種心照不宣的默契：那個失敗的專案絕不能再被提起。tacit「心照不宣的；默許的」，與 No one had ever said so out loud 相呼應；tacit understanding「默契」是常見搭配。(A) formal「正式的」(B) verbal「口頭的」(C) written「書面的」，三者都表示曾以某種方式明確表達，與「沒有人說出口」矛盾。故選 (D)。", "level": "C2", "topic": "office culture"}, {"id": "M414", "type": "dialogue", "q": "A: You've been glued to your phone all through dinner. Grandma has asked you the same question twice.\nB: ______ I'll put it away now. Sorry, Grandma — what were you saying?", "options": ["Point taken.", "Mind your own business.", "Suit yourself.", "That makes two of us."], "answer": 0, "explain": "句意：A 說 B 整頓晚餐都盯著手機，奶奶同一個問題已經問了兩次；B 回答「好，我明白了」，說馬上把手機收起來，並向奶奶道歉、問她剛剛說了什麼。Point taken. 意為「你說得有道理，我接受（你的意見）」，與 B 隨即改正的行為一致。(B) Mind your own business.「少管閒事」，態度無禮，與隨後的道歉矛盾 (C) Suit yourself.「隨便你」，用於對別人的決定表示不在乎，但 A 並沒有做什麼決定 (D) That makes two of us.「我也一樣」，用於表示同感，與 A 的批評接不上。故選 (A)。", "level": "C2", "topic": "accepting criticism"}, {"id": "M415", "type": "grammar", "q": "______ as she might, the young climber could not find a safe route to the summit and was forced to turn back.", "options": ["Tried", "Trying", "Try", "To try"], "answer": 2, "explain": "句意：那位年輕的登山者無論再怎麼努力，都找不到通往山頂的安全路線，只好被迫折返。「V + as + S + might/may」是表示讓步的慣用倒裝句型，意為「無論 S 如何…」，句首動詞一律用原形，Try as she might ＝ However hard she tried。(A) Tried (B) Trying (D) To try 都不符合此固定句型須用原形動詞的規定。故選 (C)。", "level": "C2", "topic": "concession (try as one might)"}, {"id": "M416", "type": "vocab", "q": "The exhibition ______ black-and-white photographs of Taipei streets in the 1960s with color images of the same corners today, inviting visitors to see for themselves how much has changed.", "options": ["supersedes", "juxtaposes", "extrapolates", "conflates"], "answer": 1, "explain": "句意：這場展覽把 1960 年代台北街頭的黑白照片，與同一個街角今日的彩色影像並列展出，讓參觀者親眼看看變化有多大。juxtapose A with B「把 A 與 B 並置（以便對照）」。(A) supersedes「取代」，沒有 supersede A with B 的用法，展覽也不是要用新照片取代舊照片 (C) extrapolates「推斷；推論」，不合語意 (D) conflates「把（兩者）混為一談」，與展覽要讓人看出差異的目的相反。故選 (B)。", "level": "C2", "topic": "museum exhibitions"}, {"id": "M417", "type": "dialogue", "q": "A: You really need to be more organized. Your desk is an absolute mess.\nB: ______ Your side of the room looks as if a typhoon just went through it.", "options": ["Fair enough — I'll tidy it up right away.", "I'll hold you to that.", "Sorry, I didn't quite catch that.", "That's a bit rich coming from you."], "answer": 3, "explain": "句意：A 說 B 真的該更有條理一點，書桌亂得一塌糊塗；B 回答「這話由你來說也太好笑了吧」，並反擊說 A 那半邊房間看起來像剛被颱風掃過一樣。That's a bit rich coming from you. 意為「這話從你嘴裡說出來未免太可笑了」，用來指出對方自己也有同樣的毛病（五十步笑百步）。(A) Fair enough — I'll tidy it up right away.「說得對，我馬上整理」，是接受批評，與隨後的反擊矛盾 (B) I'll hold you to that.「我會要你說到做到」，但 A 並沒有做出任何承諾 (C) Sorry, I didn't quite catch that.「抱歉，我沒聽清楚」，但 B 顯然聽到了，而且立刻反擊。故選 (D)。", "level": "C2", "topic": "hypocrisy"}, {"id": "M418", "type": "grammar", "q": "______ it to say that the class trip did not go entirely according to plan: we missed our train, lost a suitcase and spent a night on a station bench.", "options": ["Suffice", "Sufficed", "Sufficient", "Suffices"], "answer": 0, "explain": "句意：只能說，這次班遊並沒有完全照計畫進行：我們錯過了火車、弄丟一個行李箱，還在車站的長椅上過了一夜。Suffice it to say (that)... 是保留古老假設語氣用法（動詞用原形）的固定用語，意為「只需說…就夠了」，常用來簡短帶過不想細說的事。(B) Sufficed (D) Suffices 不符合此固定用語須用原形動詞的形式 (C) Sufficient 是形容詞，無法構成句子。故選 (A)。", "level": "C2", "topic": "formulaic subjunctive (suffice it to say)"}, {"id": "M419", "type": "vocab", "q": "Rather than sticking rigidly to any one theory, the new mayor took a ______ approach, adopting whatever solutions actually worked, wherever they came from.", "options": ["dogmatic", "doctrinaire", "pragmatic", "quixotic"], "answer": 2, "explain": "句意：新市長不死守任何一套理論，而是採取務實的做法，只要是真正行得通的辦法，不論出自何處都願意採用。pragmatic「務實的；講求實效的」，與 adopting whatever solutions actually worked 相呼應。(A) dogmatic「教條的；武斷的」(B) doctrinaire「死守教條的」，兩者正是 sticking rigidly to any one theory 的意思，與 Rather than 所表示的對比相反 (D) quixotic「不切實際的；空想的」，與「只採用行得通的辦法」矛盾。故選 (C)。", "level": "C2", "topic": "local government"}, {"id": "M420", "type": "dialogue", "q": "A: According to this article, a new study proves that drinking coffee helps people live longer.\nB: ______ The study only found a link between the two; it didn't show that coffee itself is the reason.\nA: Good point. I guess headlines often exaggerate.", "options": ["That's an understatement.", "I couldn't have put it better myself.", "Let's agree to disagree.", "I wouldn't go that far."], "answer": 3, "explain": "句意：A 說根據這篇文章，有一項新研究證明喝咖啡能讓人活得更久；B 回答「我可不會說得那麼肯定」，因為該研究只發現兩者有關聯，並沒有證明咖啡本身就是原因；A 說「有道理，我想標題常常太誇大」。I wouldn't go that far. 意為「我不會說得那麼絕對」，用來委婉表示對方的說法過頭了；B 指出「相關」不等於「因果」，正是在質疑 proves 一詞。(A) That's an understatement.「這還說得太保守了」，表示實際情況更甚，與 B 的質疑方向相反 (B) I couldn't have put it better myself.「你說得再好不過了」，表示完全贊同 (C) Let's agree to disagree.「我們各自保留意見吧」，用於結束雙方已僵持不下的爭論，但兩人尚未爭論，B 接著也還在提出論點。故選 (D)。", "level": "C2", "topic": "interpreting research"}, {"id": "M421", "type": "vocab", "q": "Invasive species such as the red imported fire ant can ______ a serious threat to both farming and public health: the ants damage crops, and their stings can trigger severe allergic reactions in some people.", "options": ["impose", "expose", "pose", "propose"], "answer": 2, "explain": "句意：入侵種如入侵紅火蟻，可能對農業與公共衛生都構成嚴重威脅：這種螞蟻會危害農作物，牠們的螫傷還可能使部分民眾產生嚴重的過敏反應。pose a threat to sth「對…構成威脅」為固定搭配，pose 在此意為「造成；引起（問題、危險）」。(A) impose 強加；課徵，常用 impose sth on sb（如 impose a tax on imports），不與 a threat to 搭配 (B) expose 使暴露，常用 expose sb to sth（如 expose children to danger），語意不合 (D) propose 提議，主詞須為人或機構，入侵種不可能「提議」威脅。故選 (C)。", "level": "C1", "topic": "invasive species"}, {"id": "M422", "type": "grammar", "q": "______ often the case with first novels, the book draws heavily on the author's own childhood in a small fishing village in Penghu.", "options": ["As it is", "As is", "Which is", "It is"], "answer": 1, "explain": "句意：正如作家的第一部小說常有的情形，這本書大量取材自作者在澎湖一個小漁村度過的童年。As is often the case (with...)「（正如）…常有的情形」中的 as 為準關係代名詞，代替主要子句所說的整件事（這本書取材自作者的童年），並在 as 子句中擔任主詞，所以後面直接接動詞 is，不可再加主詞 it。(A) As it is 多了主詞 it，使 as 子句出現兩個主詞，是常見的錯誤寫法 (C) Which is 的 which 若要指整個主要子句，須置於該子句之後（如 ..., which is often the case with first novels），不能放在句首 (D) It is 會使兩個獨立子句之間只以逗號連接，形成逗號連接句（comma splice）。故選 (B)。", "level": "C1", "topic": "pseudo-relative as (as is often the case)"}, {"id": "M423", "type": "dialogue", "q": "A: You have to try the stinky tofu at this stall. Trust me, it's the best in all of Taipei.\nB: ______ I've never been able to get past the smell, so I'll stick with the grilled corn.\nA: Your loss! More for me, then.", "options": ["I'll take your word for it.", "You can say that again.", "Don't mind if I do.", "It's on the house."], "answer": 0, "explain": "句意：A 說 B 一定要嚐嚐這攤的臭豆腐，保證是全台北最好吃的；B 回答「我就相信你的話吧」，接著說自己一直受不了那股味道，所以還是吃烤玉米就好；A 說那是 B 的損失，自己正好可以多吃一點。I'll take your word for it. 意為「我相信你說的（但不打算親自驗證）」，常用來婉拒對方的推薦，與 B 不想吃臭豆腐的態度一致。(B) You can say that again.「我完全同意」，但 B 連味道都受不了，從未吃過，無從認同那是全台北最好吃的臭豆腐 (C) Don't mind if I do.「那我就不客氣了」，用於接受對方提供的食物或飲料，與 B 改吃烤玉米矛盾 (D) It's on the house.「這由本店招待」，是店家請客時說的話，不合 B 的身分。故選 (A)。", "level": "C1", "topic": "food recommendations"}, {"id": "M424", "type": "vocab", "q": "A series of product recalls has gradually ______ customers' confidence in the brand, and its sales have now fallen for the third year in a row.", "options": ["restored", "boosted", "dominated", "eroded"], "answer": 3, "explain": "句意：一連串的產品召回事件逐漸削弱了消費者對這個品牌的信心，該品牌的銷售量至今已連續三年下滑。erode 原指「侵蝕；腐蝕」，引申為「（信任、信心、支持等）逐漸削弱」，常用 erode trust / confidence / support；句中的 gradually 也與 erode 逐步消磨的意思相呼應。(A) restored 恢復 (B) boosted 提升，兩者都與銷售量連年下滑矛盾 (C) dominated 支配；主宰，不與 confidence 搭配，語意也不通。故選 (D)。", "level": "C1", "topic": "brand reputation"}, {"id": "M425", "type": "grammar", "q": "Mei-ling has been taking evening classes in accounting with a view to ______ her own bakery once she has saved enough money.", "options": ["opening", "open", "opened", "have opened"], "answer": 0, "explain": "句意：美玲一直在上會計夜間課程，目的是等存夠錢之後開一家自己的麵包店。with a view to + N／V-ing「為了…；以…為目的」，其中的 to 是介系詞，後面須接名詞或動名詞，因此用 opening；同樣以介系詞 to 接 V-ing 的還有 look forward to、be committed to、when it comes to 等。(B) open 誤把介系詞 to 當成不定詞符號，是常見錯誤 (C) opened 是過去式或過去分詞，不能作介系詞的受詞 (D) have opened 同樣把 to 誤當成不定詞，而且開店是尚未實現的目標，用完成式也不合語意。故選 (A)。", "level": "C1", "topic": "with a view to + V-ing"}, {"id": "M426", "type": "dialogue", "q": "A: I think I've finally figured out how we can raise enough money for the class trip.\nB: ______ We've already tried bake sales and car washes, and we're still NT$20,000 short.\nA: OK, here's the idea: we could sell advertising space on our class T-shirts to shops near the school.", "options": ["Spare me the details.", "I'll sleep on it.", "I'm all ears.", "That rings a bell."], "answer": 2, "explain": "句意：A 說他終於想到能為校外教學籌足經費的辦法了；B 回答「我洗耳恭聽」，並說大家已經辦過點心義賣和洗車募款，卻還差新台幣兩萬元；A 接著提出把班服上的廣告版面賣給學校附近商家的點子。I'm all ears. 意為「我洗耳恭聽；我很想聽聽看」，表示急著想聽對方說明，與 B 說明經費仍有缺口、A 隨即說出辦法相呼應。(A) Spare me the details.「細節就不必說了」，與 B 急於聽到辦法矛盾 (B) I'll sleep on it.「讓我考慮一晚再決定」，但 A 還沒說出辦法，B 無從考慮 (D) That rings a bell.「聽起來有點耳熟」，用於似乎聽過某事，與語境不符。故選 (C)。", "level": "C1", "topic": "fundraising ideas"}, {"id": "M427", "type": "vocab", "q": "All food stalls at the night market must ______ with the city's new hygiene regulations by the end of the month, or they will be fined and may lose their licenses.", "options": ["interfere", "collide", "sympathize", "comply"], "answer": 3, "explain": "句意：夜市所有的小吃攤都必須在月底前遵守市政府新的衛生法規，否則將被罰款，甚至可能被吊銷執照。comply with + 規定／法律「遵守；遵從」，與後文違規的罰則相呼應。四個選項都可接 with，須依語意判斷：(A) interfere with 干擾；妨礙 (B) collide with 與…相撞；與…衝突 (C) sympathize with 同情；支持，皆無法與「否則將被罰款」連貫。故選 (D)。", "level": "C1", "topic": "food safety regulations"}, {"id": "M428", "type": "grammar", "q": "______ how little rain has fallen this spring, it is hardly surprising that several reservoirs in central Taiwan are almost empty.", "options": ["Giving", "Given", "To give", "Having given"], "answer": 1, "explain": "句意：考慮到今年春天的雨量如此稀少，中部有幾座水庫幾乎見底也就不足為奇了。Given 在此作介系詞用，意為「考慮到；有鑑於」（＝ considering），後面可接名詞、名詞子句（如本句的 how little rain has fallen）或 that 子句，是正式文章中常用來提出前提或理由的說法。(A) Giving 是主動的分詞構句，表示「給予」，而主要子句的主詞是虛主詞 it，語意與結構都不通 (C) To give 表示目的「為了給予」(D) Having given 表示「已經給予」，皆無法表達「考慮到」的意思。故選 (B)。", "level": "C1", "topic": "given (= considering)"}, {"id": "M429", "type": "grammar", "q": "The hikers spent five hours climbing to the summit, ______ that thick fog was hiding the view they had come all that way to see.", "options": ["only to find", "only finding", "so as to find", "in order to find"], "answer": 0, "explain": "句意：登山客花了五個小時攀登到山頂，結果卻發現濃霧遮住了他們大老遠前來想看的景色。only to + V 置於句尾，表示出乎意料、通常令人失望的結果，意為「結果卻…」。(B) only finding 並非慣用說法，表達「結果卻…」須用 only to + V (C) so as to find 與 (D) in order to find 都表示目的「為了發現…」，但登山客辛苦攀登並不是為了看到濃霧。故選 (A)。", "level": "C1", "topic": "only to + V (unexpected result)"}, {"id": "M430", "type": "dialogue", "q": "A: The museum probably won't let us film inside for our history project. Should we even bother asking?\nB: ______ The worst they can say is no.\nA: True. I'll email them tonight and explain what the project is about.", "options": ["Don't push your luck.", "It's worth a shot.", "That's beside the point.", "It's out of the question."], "answer": 1, "explain": "句意：A 說博物館大概不會讓他們為歷史專題在館內拍攝，問 B 還有沒有必要去問；B 回答「值得一試」，最糟也不過是被拒絕；A 說也對，今晚就寄電子郵件說明專題內容。It's worth a shot. 意為「值得一試」，shot 在此作「嘗試」解，與後句 The worst they can say is no. 鼓勵對方提出請求相呼應。(A) Don't push your luck.「別得寸進尺；見好就收」，用於勸人不要冒險要求更多，但 A 根本還沒獲得任何許可 (C) That's beside the point.「那不是重點」，但 A 問的「要不要去問」正是兩人討論的重點 (D) It's out of the question.「那是不可能的；免談」，與 B 鼓勵 A 去詢問的態度矛盾。故選 (B)。", "level": "C1", "topic": "encouragement"}, {"id": "M431", "type": "vocab", "q": "At first, the student's excuse for being late sounded ______ enough — the bus had broken down in the heavy rain — until his teacher remembered that he lived only a five-minute walk from school.", "options": ["meticulous", "reluctant", "obsolete", "plausible"], "answer": 3, "explain": "句意：起初，這名學生遲到的藉口聽起來還算合理：公車在大雨中拋錨了；直到老師想起他家離學校只要走路五分鐘。plausible「（說法、解釋）似乎合理的；可信的」，常與 explanation、excuse、theory 搭配；until 子句顯示藉口後來被識破，正說明它「起初聽起來合理」。(A) meticulous 一絲不苟的，形容人或工作 (B) reluctant 不情願的，用來形容人的態度 (C) obsolete 過時的；被淘汰的，三者都不能用來形容藉口聽起來可信。故選 (D)。", "level": "C1", "topic": "excuses"}, {"id": "M432", "type": "grammar", "q": "It was not until Alexander Fleming returned to his laboratory from a summer vacation in 1928 ______ he noticed that a mold growing in one of his culture dishes had killed the bacteria around it.", "options": ["when", "that", "which", "since"], "answer": 1, "explain": "句意：直到 1928 年亞歷山大．弗萊明（Alexander Fleming）度完暑假回到實驗室，他才注意到某個培養皿中長出的黴菌殺死了周圍的細菌。It was not until + 時間 + that + 子句 是「直到…才…」的分裂句（強調句）句型，被強調的部分（not until...）之後固定以 that 連接。(A) when 雖可引導時間子句，但不能在分裂句中取代 that (C) which 是關係代名詞，須修飾前面的名詞，而本句被強調的是表示時間的 until 子句 (D) since 意為「自從；因為」，語意不合，也不能用於分裂句。故選 (B)。", "level": "C1", "topic": "cleft sentence (it was not until ... that)"}, {"id": "M433", "type": "dialogue", "q": "A: The client just called. The brochure we sent them still has last year's prices on it.\nB: ______ I must have attached the old file by mistake. I'll send them the correct version right away and apologize.\nA: Thanks. And from now on, let's double-check everything before it goes out.", "options": ["That's entirely my fault.", "Don't blame me — I just work here.", "It's none of my business.", "So far, so good."], "answer": 0, "explain": "句意：A 說客戶剛打電話來，表示我們寄給他們的簡介上還是去年的價格；B 回答「這完全是我的錯」，說自己一定是不小心附上了舊檔案，會立刻把正確版本寄給客戶並致歉；A 道謝，並說從今以後所有東西寄出前都要再檢查一遍。That's entirely my fault. 直接承擔責任，與後句說明疏失並提出補救措施一致。(B) Don't blame me — I just work here.「別怪我，我只是個員工」，推卸責任，與 B 承認自己附錯檔案矛盾 (C) It's none of my business.「這不關我的事」，同樣是撇清責任 (D) So far, so good.「到目前為止一切順利」，與出錯的情況相反。故選 (A)。", "level": "C1", "topic": "taking responsibility at work"}, {"id": "M434", "type": "vocab", "q": "The school has ______ most of this year's budget to upgrading its computer labs, which leaves very little money for new library books.", "options": ["attributed", "accumulated", "allocated", "abolished"], "answer": 2, "explain": "句意：學校把今年大部分的預算撥給電腦教室的更新，因此能用來購買圖書館新書的經費所剩無幾。allocate sth to sth「把（資金、資源、時間）分配給…」，常與 budget、funds、resources 搭配。(A) attributed 常用 attribute A to B「把 A 歸因於 B」，不能表示撥款 (B) accumulated 累積，不能接 to + 用途表示分配 (D) abolished 廢除（制度、法律），不能用於預算。故選 (C)。", "level": "C1", "topic": "school budgets"}, {"id": "M435", "type": "grammar", "q": "The former manager denied ______ any money from the company, insisting that every payment had been approved by the board.", "options": ["to have taken", "having been taken", "to take", "having taken"], "answer": 3, "explain": "句意：前任經理否認曾從公司拿走任何錢，堅稱每一筆款項都經過董事會核准。deny（否認）後面須接動名詞作受詞，不能接不定詞；因為「拿錢」發生在「否認」之前，用完成式動名詞 having + p.p. 強調該動作較早發生（也可說 denied taking）。(A) to have taken 與 (C) to take 都是不定詞，deny 不接不定詞 (B) having been taken 是被動語態，變成經理「被拿走」，語意不通，後面也不能再接受詞 any money。故選 (D)。", "level": "C1", "topic": "perfect gerund (deny having p.p.)"}, {"id": "M436", "type": "vocab", "q": "There is now a broad scientific ______ that human activities, especially the burning of fossil fuels, are the main cause of the global warming observed since the mid-20th century.", "options": ["controversy", "consensus", "coincidence", "contradiction"], "answer": 1, "explain": "句意：目前科學界已有廣泛的共識，認為人類活動，尤其是燃燒化石燃料，是二十世紀中葉以來所觀測到的全球暖化的主要原因。consensus「共識」，常用 a broad / general consensus that + 子句，broad 也提示「多數人一致同意」。(A) controversy 爭議，與 broad 所表達的普遍認同相反，且通常用 controversy over / about (C) coincidence 巧合 (D) contradiction 矛盾，兩者都不能接 that 子句表示大家認同的觀點。故選 (B)。", "level": "C1", "topic": "climate science"}, {"id": "M437", "type": "dialogue", "q": "A: Working from home obviously makes everyone more productive. There's no commute and no office chatter.\nB: ______ It probably depends a lot on the type of job and the person doing it.\nA: Fair enough. I suppose my own experience might not be typical.", "options": ["I couldn't agree with you more.", "Now you're talking — that's exactly it.", "I see where you're coming from, but I'm not entirely convinced.", "Well, in that case I stand corrected."], "answer": 2, "explain": "句意：A 說在家工作顯然讓每個人都更有效率，既不用通勤，也沒有辦公室裡的閒聊；B 回答「我明白你的出發點，但我並不完全認同」，並指出這大概很取決於工作性質和個人；A 說有道理，自己的經驗也許並不具代表性。I see where you're coming from, but... 先肯定對方的想法，再委婉表達不同意見，是禮貌提出異議的常用說法，與後句「要看工作類型和個人而定」相符。(A) I couldn't agree with you more.「我再同意不過了」(B) Now you're talking.「這才對嘛；說得好」，兩者都表示贊同，與 B 接著提出保留意見矛盾 (D) I stand corrected.「我承認我說錯了」，用於自己的說法被糾正時，但 B 先前並未發表任何看法。故選 (C)。", "level": "C1", "topic": "polite disagreement"}, {"id": "M438", "type": "grammar", "q": "Researchers are still debating the extent ______ heavy social media use affects teenagers' sleep and mood.", "options": ["to which", "which", "to what", "in which"], "answer": 0, "explain": "句意：研究人員對於大量使用社群媒體會在多大程度上影響青少年的睡眠與情緒，仍在爭論之中。the extent to which + 子句「…的程度」是學術寫作常見的結構，介系詞 to 來自 to an extent（到某種程度），移到關係代名詞 which 之前。(B) which 缺少介系詞：heavy social media use affects teenagers' sleep and mood 已是完整的子句，which 在子句中沒有可擔任的主詞或受詞位置 (C) to what 不能接在名詞 the extent 之後，只能說 to what extent + 子句 (D) in which 介系詞錯誤，extent 固定與 to 搭配。故選 (A)。", "level": "C1", "topic": "relative clause (the extent to which)"}, {"id": "M439", "type": "vocab", "q": "For most healthy adults, the benefits of regular moderate exercise far ______ the small risk of injury, so fear of getting hurt is rarely a good reason to avoid it altogether.", "options": ["outnumber", "outlive", "outgrow", "outweigh"], "answer": 3, "explain": "句意：對大多數健康的成年人來說，規律適度運動的好處遠遠超過受傷的小小風險，因此害怕受傷很少能成為完全不運動的好理由。outweigh「（重要性、價值）超過；勝過」，常用 the benefits outweigh the risks，far 用來加強語氣。(A) outnumber 在數量上超過，用於比較人或物的數目，而本句比較的是好處與風險的輕重 (B) outlive 比…活得久 (C) outgrow 因長大而穿不下；因長大而不再喜歡，皆不合語意。故選 (D)。", "level": "C1", "topic": "exercise and health"}, {"id": "M440", "type": "dialogue", "q": "A: Kevin didn't reply to any of my messages yesterday. I bet he's still angry about what I said at lunch.\nB: ______ Maybe his phone just died. You know how often he forgets to charge it.\nA: I suppose you're right. I'll talk to him in class tomorrow.", "options": ["It serves you right.", "I couldn't have put it better myself.", "Let's give him the benefit of the doubt.", "He's got a lot of nerve."], "answer": 2, "explain": "句意：A 說凱文昨天完全沒回他的訊息，認定凱文還在為自己午餐時說的話生氣；B 回答「我們還是姑且往好處想吧」，並說也許凱文的手機只是沒電了，畢竟他常忘記充電；A 說大概是吧，明天上課時再跟凱文談。give sb the benefit of the doubt 意為「（在沒有確切證據時）姑且相信某人；往好的方面設想」，與 B 接著替凱文找出合理的解釋相符。(A) It serves you right.「你活該」，等於認定凱文確實在生氣 (B) I couldn't have put it better myself.「你說得再好不過了」，表示完全同意 A 的推測 (D) He's got a lot of nerve.「他膽子真大；他真厚臉皮」，是在指責凱文，三者都與 B 接著推測「手機可能只是沒電」矛盾。故選 (C)。", "level": "C1", "topic": "misunderstandings between friends"}, {"id": "M441", "type": "vocab", "q": "Clearing the coastal mangroves to make way for shrimp farms only ______ the flooding that nearby villages suffered every typhoon season, since the trees had acted as a natural barrier against storm surges.", "options": ["alleviated", "exacerbated", "validated", "insulated"], "answer": 1, "explain": "句意：為了開闢養蝦場而砍伐海岸的紅樹林，只是讓附近村莊每逢颱風季節的淹水情況更加惡化，因為這些樹原本是抵擋暴潮的天然屏障。exacerbate「使（問題、情況）惡化；加劇」，受詞多為 problem、situation、flooding 等負面名詞；since 子句說明紅樹林原本具有屏障作用，砍伐後淹水自然更嚴重，only 也暗示事與願違的結果。(A) alleviated 減輕；緩和，與失去天然屏障的因果關係相反 (C) validated 證實；使生效，受詞通常是理論、說法或文件，不能接 the flooding (D) insulated 使隔熱；使隔絕，語意不合。故選 (B)。", "level": "C1", "topic": "coastal ecosystems"}, {"id": "M442", "type": "grammar", "q": "The team's victory in the national final was all the ______ because, only a year earlier, the school had almost shut the club down for lack of funding.", "options": ["sweetest", "sweet", "more sweetly", "sweeter"], "answer": 3, "explain": "句意：這支球隊在全國決賽中奪冠，勝利顯得格外甜美，因為就在一年前，學校還差點因為經費不足而把這個社團停掉。「all the + 比較級 + because／for…」意為「因為…而更加…」，此處的 the 是副詞，表示「因此；越發」，because 子句說明勝利更加甜美的原因，故用比較級 sweeter。(A) sweetest 為最高級，all the 之後須接比較級 (B) sweet 為原級，無法表達「更加」的意思 (C) more sweetly 為副詞，be 動詞 was 之後須接形容詞作主詞補語。故選 (D)。", "level": "C1", "topic": "all the + comparative (because)"}, {"id": "M443", "type": "dialogue", "q": "A: A few of us are trying that new hot-pot place on Friday night. Want to join us?\nB: ______ My grandparents are visiting that weekend. Could we go the Friday after?\nA: Sure. I'll let the others know.", "options": ["I'd love to, but can I take a rain check?", "Count me in! What time are we meeting?", "Sorry, it completely slipped my mind.", "Thanks, but hot pot isn't really my thing."], "answer": 0, "explain": "句意：A 說他們幾個人星期五晚上要去試那家新開的火鍋店，問 B 要不要一起去；B 回答「我很想去，但可以改天再約嗎？」並說明祖父母那個週末要來，提議改到下一個星期五；A 說沒問題，會轉告其他人。take a rain check 原指球賽因雨延期時拿到的補看憑證，引申為「婉拒這次邀約，但表示改天再約」，與 B 提議改期的內容相符。(B) Count me in! 意為「算我一份」，表示欣然答應，與祖父母來訪、提議改期矛盾 (C)「抱歉，我完全忘了」，用於忘記先前的約定，但 A 是現在才提出邀約 (D)「謝謝，但我不太喜歡吃火鍋」，表示對活動本身沒興趣，卻又提議改天再去，前後矛盾。故選 (A)。", "level": "C1", "topic": "declining invitations"}, {"id": "M444", "type": "vocab", "q": "The charity's finances came under close ______ after reporters revealed that only a small share of the donations had actually reached the families it claimed to help.", "options": ["custody", "tribute", "scrutiny", "momentum"], "answer": 2, "explain": "句意：記者揭露捐款只有一小部分真正送到該慈善機構聲稱要幫助的家庭手中之後，它的財務狀況便受到嚴密的檢視。come under (close) scrutiny「受到（嚴密的）審查、檢視」是新聞報導常見的搭配，多用於疑點或醜聞曝光之後。(A) custody 拘留；監護權，常用 be taken into custody，不與 come under 搭配，財務也不能被拘留 (B) tribute 致敬；讚頌，常用 pay tribute to，與醜聞的語境相反 (D) momentum 動力；氣勢，常用 gain／lose momentum，皆不合語意與搭配。故選 (C)。", "level": "C1", "topic": "investigative journalism"}, {"id": "M445", "type": "grammar", "q": "At no time ______ that the free trial would automatically turn into a paid subscription, which is why so many users were shocked when the first charge appeared.", "options": ["customers were told", "were customers told", "had customers told", "did customers tell"], "answer": 1, "explain": "句意：顧客自始至終都沒有被告知免費試用期會自動轉為付費訂閱，這就是為什麼許多使用者看到第一筆扣款時大吃一驚。否定副詞片語 At no time（從未；在任何時候都不）置於句首時，主要子句必須倒裝；顧客是「被告知」的一方，用被動語態 were told，倒裝後為「were + 主詞 + told」。(A) customers were told 沒有倒裝 (C) had customers told、(D) did customers tell 雖已倒裝，但為主動語態，表示顧客去告知別人，與語意不符，而且 tell 後面缺少表示告知對象的受詞。故選 (B)。", "level": "C1", "topic": "inversion (at no time)"}, {"id": "M446", "type": "dialogue", "q": "A: I'm so sorry I forgot to send you the lecture notes last night. I know you needed them for the quiz.\nB: ______ Mei-ling lent me hers, and the quiz went fine.\nA: That's a relief. I still owe you one, though.", "options": ["That's the last straw.", "You can say that again.", "Don't give it another thought.", "It's about time you said sorry."], "answer": 2, "explain": "句意：A 為昨晚忘了把課堂筆記傳給 B 而道歉，因為知道 B 要準備小考；B 回答「別放在心上」，並說美玲把她的筆記借給了自己，小考也考得不錯；A 鬆了一口氣，但仍表示欠 B 一次人情。Don't give it another thought. 意為「別再放在心上了」，用來大方地接受道歉，與 B 後面輕鬆的說明一致。(A) That's the last straw. 意為「這是最後一根稻草；我忍無可忍了」，語氣憤怒 (B) You can say that again. 意為「你說得一點也沒錯」，用來回應道歉等於附和對方確實做錯了，帶有諷刺意味 (D)「你也早該道歉了」，帶有責怪，三者都與 B 毫不在意的語氣矛盾。故選 (C)。", "level": "C1", "topic": "apologies"}, {"id": "M447", "type": "vocab", "q": "Supporters of the herbal remedy point to dozens of personal success stories, but such ______ evidence cannot replace properly controlled clinical trials.", "options": ["anecdotal", "conclusive", "statistical", "forensic"], "answer": 0, "explain": "句意：這種草藥療法的支持者舉出數十個個人治癒的故事，但這類傳聞式的證據無法取代經過嚴謹對照的臨床試驗。anecdotal「傳聞的；（證據）來自個人經驗或故事，而非系統性研究的」，anecdotal evidence 常與 controlled trials 等科學證據對比，正對應句中的 personal success stories。(B) conclusive 確鑿的；決定性的，若證據確鑿，就不會說它無法取代臨床試驗 (C) statistical 統計的，個人故事並非統計數據 (D) forensic 法醫的；鑑識的，用於刑案調查，與療效無關。故選 (A)。", "level": "C1", "topic": "health claims"}, {"id": "M448", "type": "grammar", "q": "When Leo admitted he had known for a week that the concert had been canceled, his roommate snapped, \"You ______ me! I've spent the whole afternoon getting ready.\"", "options": ["must have told", "needn't have told", "can't have told", "might have told"], "answer": 3, "explain": "句意：里歐承認他一個星期前就知道演唱會已經取消了，他的室友厲聲說：「你大可早點告訴我的！我花了一整個下午做準備。」might have + p.p. 除了表示對過去的推測，也可用來責備對方「本來可以…卻沒有做」（意近 could have p.p.、should have p.p.），常帶有不滿的語氣。里歐明知演唱會取消卻沒說，室友正在抱怨，故用 might have told。(A) must have told 表示「你一定告訴過我」的肯定推測，與里歐沒說的事實矛盾 (B) needn't have told 表示「你本來不必告訴我（卻說了）」，與事實及抱怨的語氣皆不符 (C) can't have told 表示「你不可能告訴過我」的推測，但里歐沒說是雙方都清楚的事實，無須推測，也無法表達責備。故選 (D)。", "level": "C1", "topic": "might have p.p. (reproach)"}, {"id": "M449", "type": "vocab", "q": "By posting a photo of the crowd without blurring any faces, the reporter ______ revealed the identity of a witness whom the police had promised to protect, and she was horrified when she realized her mistake.", "options": ["deliberately", "reluctantly", "meticulously", "inadvertently"], "answer": 3, "explain": "句意：那位記者張貼了一張群眾照片，卻沒有把任何人的臉做模糊處理，無意間洩露了警方承諾保護的一名證人的身分；當她發現自己的錯誤時驚恐不已。inadvertently「不經意地；無意中」，與句末「發現自己的錯誤時驚恐不已」相呼應。(A) deliberately 故意地，與事後才發現錯誤矛盾 (B) reluctantly 不情願地，表示她明知會洩露身分仍勉強去做，也與事後才發現錯誤不符 (C) meticulously 一絲不苟地，與「沒有模糊任何臉部」的疏失矛盾。故選 (D)。", "level": "C1", "topic": "journalism ethics"}, {"id": "M450", "type": "dialogue", "q": "A: ...so if we move sports day to November, we'll also need to rebook the stadium, change the shuttle bus schedule, and—\nB: ______ but I think the stadium is already booked for a concert that month.\nA: Oh, really? Then we'd better check before we go any further.", "options": ["Let me sleep on it,", "Sorry to cut in,", "Please go on,", "Don't mention it,"], "answer": 1, "explain": "句意：A 正在說明若把運動會改到十一月，就必須重新預約體育場、更改接駁車時刻表等等；B 說「抱歉打個岔」，並指出體育場那個月似乎已被一場演唱會預約；A 回應那最好先確認清楚再繼續討論。Sorry to cut in 意為「抱歉打斷一下」，是會議中禮貌插話的常用說法；A 的話以破折號中斷，顯示 B 是在對方說到一半時插話。(A) Let me sleep on it 意為「讓我考慮一晚再決定」，但 B 並非要做決定，而是立即提供資訊 (C) Please go on 意為「請繼續說」，卻又打斷對方提出意見，前後矛盾 (D) Don't mention it 意為「不客氣；別客氣」，用來回應對方的道謝，但 A 並沒有向 B 道謝。故選 (B)。", "level": "C1", "topic": "interrupting politely"}, {"id": "M451", "type": "grammar", "q": "Instead of punishing the students who kept arriving late, what the principal did was ______ with each of them individually to find out why.", "options": ["meeting", "met", "meet", "to have met"], "answer": 2, "explain": "句意：校長沒有處罰那些經常遲到的學生，而是和他們逐一個別面談，了解遲到的原因。此為 wh- 分裂句（又稱準分裂句）「What + 主詞 + do／did + be 動詞 + (to) 原形動詞」，用來強調所做的事；what 子句用 did 時，be 動詞後接原形動詞或不定詞，故選 meet。(A) meeting：只有在 what 子句用進行式 doing 時（如 What he is doing is meeting…），補語才用 V-ing (B) met 為過去式，不能直接放在 be 動詞之後當補語，若視為被動語態「被會見」也不合語意 (D) to have met 為完成式不定詞，表示比 did 更早發生的動作，與「取代處罰的做法」在時間上不合。故選 (C)。", "level": "C1", "topic": "pseudo-cleft (what … did was)"}, {"id": "M452", "type": "vocab", "q": "Although the prototype performed well in the laboratory, the company eventually dropped the project because mass-producing it would not have been commercially ______.", "options": ["viable", "volatile", "visible", "vulnerable"], "answer": 0, "explain": "句意：雖然原型在實驗室裡表現良好，公司最後仍放棄了這項計畫，因為大量生產在商業上並不可行。viable 意為「可行的；能成功運作的」，commercially viable 即「在商業上可行的；能獲利的」，說明公司放棄計畫的原因。(B) volatile 易變的；不穩定的，多形容價格、市場或情緒，「量產在商業上不會不穩定」無法解釋為何放棄 (C) visible 看得見的 (D) vulnerable 易受傷害的，皆不合語意。故選 (A)。", "level": "C1", "topic": "product development"}, {"id": "M453", "type": "dialogue", "q": "A: This bike's in great condition. I can let you have it for NT$6,000.\nB: ______ I've seen the same model on other second-hand sites for around NT$4,500.\nA: All right, how about NT$5,000? That's as low as I can go.", "options": ["That's a steal! I'll take it.", "That's a bit steep for me.", "Keep the change.", "It's on the house."], "answer": 1, "explain": "句意：A 說這輛腳踏車狀況很好，願意以新臺幣六千元賣給 B；B 回答「這價錢對我來說有點高」，並說在其他二手網站看過同款大約四千五百元；A 讓步提出五千元，表示這已是最低價。steep 在口語中可指「（價格）過高的」，That's a bit steep for me. 委婉地表示太貴，再以其他網站的較低價格作為議價理由。(A)「真是撿到便宜了！我買了」，與後面嫌貴、議價的內容矛盾 (C) Keep the change. 意為「不用找零了」，是付款後對收款人說的話，此時尚未成交 (D) It's on the house. 意為「這是招待的；免費」，應由店家或賣方說出，不是買方的回應。故選 (B)。", "level": "C1", "topic": "bargaining"}, {"id": "M454", "type": "grammar", "q": "The two plans for the old train station are alike ______ both would turn it into a public library, but one would cost nearly twice as much as the other.", "options": ["in that", "so that", "even though", "unless"], "answer": 0, "explain": "句意：舊火車站的這兩個改建計畫相似之處在於都會把車站改成公共圖書館，但其中一個的花費幾乎是另一個的兩倍。in that 為連接詞，意為「在於；因為」，用來說明前面的判斷在哪一方面成立，常接在 alike、similar、different 等形容詞之後；兩個計畫「都要改成圖書館」正是它們相似之處。(B) so that「以便；因此」，表目的或結果，不合邏輯 (C) even though「即使」，表讓步，但兩案用途相同是相似的原因，並非與相似相反的情況 (D) unless「除非」，表條件，語意不合。故選 (A)。", "level": "C1", "topic": "conjunction in that"}, {"id": "M455", "type": "vocab", "q": "The monks' decision to open the monastery library to the public was ______: never before in its 800-year history had outsiders been allowed to handle its manuscripts.", "options": ["customary", "unanimous", "redundant", "unprecedented"], "answer": 3, "explain": "句意：修士們決定將修道院的圖書館開放給大眾，此舉史無前例：在修道院八百年的歷史中，從未有外人獲准翻閱館內的手抄本。unprecedented「前所未有的；史無前例的」，冒號後的 never before … had outsiders been allowed 正是對它的具體說明。(A) customary 慣例的；習慣上的，與「從未有過」相反 (B) unanimous 全體一致的，用於形容表決或意見，冒號後的說明並未提到任何人表決或意見一致 (C) redundant 多餘的，與冒號後的說明無關。故選 (D)。", "level": "C1", "topic": "cultural heritage"}, {"id": "M456", "type": "dialogue", "q": "A: To renew your parking permit online, upload the form, wait for the confirmation code, and then enter it on the second page—not the first—before you pay.\nB: ______ Could you go through it again, a bit more slowly?\nA: Of course. Let's take it one step at a time.", "options": ["That goes without saying.", "Sorry, you've lost me.", "Got it—crystal clear.", "You read my mind."], "answer": 1, "explain": "句意：A 說明線上更新停車證的步驟：上傳表格、等待確認碼，然後在付款前於第二頁（而不是第一頁）輸入確認碼；B 回答「抱歉，我跟不上了」，並請 A 再慢慢說一次；A 答應一步一步說明。Sorry, you've lost me. 意為「抱歉，我聽不懂了；我跟不上你說的內容」，用來禮貌地表示沒聽懂，正好引出請對方再說一遍的要求。(A) That goes without saying. 意為「那是不用說的；理所當然」，表示內容再明顯不過，與要求重講矛盾 (C)「懂了，非常清楚」，同樣與要求重講矛盾 (D) You read my mind. 意為「你說中了我的心思」，用於對方說出自己正想說或想要的東西，不合語境。故選 (B)。", "level": "C1", "topic": "asking for clarification"}, {"id": "M457", "type": "grammar", "q": "Nearly a decade after the tunnel project was approved, its final route has yet ______, as engineers and local residents still cannot agree on where it should go.", "options": ["decided", "been decided", "to be decided", "to decide"], "answer": 2, "explain": "句意：這項隧道工程獲准將近十年後，最終路線仍有待決定，因為工程師與當地居民對於路線該怎麼走仍無法達成共識。have／has yet to + 原形動詞 意為「尚未…；仍有待…」，形式上是肯定句，語意卻是否定；主詞 its final route（最終路線）是「被決定」的一方，須用被動式不定詞 to be + p.p.，故為 has yet to be decided（≈ has not been decided yet）。(A) decided、(B) been decided：表示「尚未」的 has yet 之後須接不定詞 to V，不能直接接過去分詞；若要用完成式，須改為否定句 has not yet been decided (D) to decide 為主動語態，表示路線去決定某事，不合邏輯。故選 (C)。", "level": "C1", "topic": "have yet to + passive infinitive"}, {"id": "M458", "type": "vocab", "q": "To encourage companies to move their headquarters out of the crowded capital, the government is offering tax breaks as ______.", "options": ["an obstacle", "a penalty", "an incentive", "a deterrent"], "answer": 2, "explain": "句意：為了鼓勵企業將總部遷出擁擠的首都，政府提供減稅優惠作為誘因。an incentive「誘因；激勵」，句首的 To encourage 與 tax breaks（減稅優惠）都說明政府是用好處吸引企業。(A) an obstacle 障礙 (B) a penalty 罰則；罰款 (D) a deterrent 嚇阻因素，三者都是阻止或懲罰的手段，與 encourage 及減稅優惠的性質矛盾。故選 (C)。", "level": "C1", "topic": "regional development"}, {"id": "M459", "type": "dialogue", "q": "A: I'm applying for a job at another company, but please don't mention it to anyone at work. My manager doesn't know yet.\nB: ______ I won't breathe a word.\nA: Thanks. I'll tell her myself once I hear back from them.", "options": ["Your secret's safe with me.", "I'll be sure to pass it on.", "Have you told your manager yet?", "Too late—I've already told the whole team."], "answer": 0, "explain": "句意：A 說自己正在應徵另一家公司的工作，請 B 別對同事提起，因為主管還不知道；B 回答「我會替你保守祕密」，並保證一個字也不會透露；A 道謝，表示等對方公司回覆後會親自告訴主管。Your secret's safe with me. 意為「你的祕密在我這裡很安全；我會替你保密」，與後句 I won't breathe a word（我一個字也不會說出去）相呼應。(B)「我一定會替你轉告」，與保密的承諾矛盾 (C)「你告訴主管了嗎？」A 剛說過主管還不知道，此問多餘 (D)「來不及了，我已經告訴整個團隊了」，與後句的保證矛盾。故選 (A)。", "level": "C1", "topic": "keeping confidences"}, {"id": "M460", "type": "grammar", "q": "The new cross-harbor bridge ______ in 2020, but a series of design problems pushed the opening back by four years.", "options": ["has opened", "must have opened", "had been opened", "was to have opened"], "answer": 3, "explain": "句意：這座新的跨港大橋原本預定在 2020 年通車，但一連串設計問題使通車時間延後了四年。「was／were to have + p.p.」表示「原本預定要…（但並未實現）」，與後面 but … pushed the opening back 相呼應。(A) has opened 現在完成式不能與明確的過去時間 in 2020 連用，也與延後通車矛盾 (B) must have opened 表示「當時想必已經通車」的推測，與延後四年矛盾 (C) had been opened 為被動語態的過去完成式，表示「已被開通」，同樣與延後通車矛盾。故選 (D)。", "level": "C1", "topic": "was to have p.p. (unfulfilled plan)"}, {"id": "M461", "type": "vocab", "q": "Vegetable prices in Taiwan tend to ______ considerably over the course of a year, soaring after a typhoon damages crops and dropping again once harvests return to normal.", "options": ["stagnate", "evaporate", "fluctuate", "accumulate"], "answer": 2, "explain": "句意：台灣的蔬菜價格在一年之中往往起伏很大，颱風損害農作物後價格飆漲，等收成恢復正常後又再度下跌。fluctuate「（價格、數量等）波動；起伏不定」，正好對應後文的「飆漲」（soaring）與「下跌」（dropping）兩種變化。(A) stagnate 停滯不前，與價格大幅漲跌矛盾 (B) evaporate 蒸發；消失，價格不會「消失」(D) accumulate 累積；積聚，無法表達忽漲忽跌。故選 (C)。", "level": "C1", "topic": "food prices"}, {"id": "M462", "type": "grammar", "q": "______ the city's free shuttle bus service will continue next year depends largely on how many residents actually use it over the coming months.", "options": ["If", "That", "What", "Whether"], "answer": 3, "explain": "句意：市府的免費接駁公車服務明年是否會繼續提供，主要取決於未來幾個月實際搭乘的居民有多少。名詞子句放在句首作主詞、表示「是否」時，須用 Whether 引導，整個子句視為單數，故後接 depends。(A) If 引導的名詞子句只能放在動詞後面作受詞，不能置於句首作主詞 (B) That 引導的名詞子句陳述確定的事實，但「明年是否繼續」尚未確定，與 depends on 的語意不合 (C) What 須在子句中擔任主詞或受詞等成分，但 the city's free shuttle bus service will continue next year 已是完整的句子，不缺任何成分。故選 (D)。", "level": "C1", "topic": "noun clause (whether as subject)"}, {"id": "M463", "type": "dialogue", "q": "A: I know the listening test has already started, but couldn't you let me in just this once? My bus broke down on the way.\nB: ______ No one is allowed in once the recording has begun — it wouldn't be fair to the others.\nA: I understand. I'll ask the office if there's a make-up session.", "options": ["Sure, just this once.", "I'm sorry, but my hands are tied.", "Don't mention it.", "It's your call."], "answer": 1, "explain": "句意：A 說自己知道聽力測驗已經開始了，但因為公車半路拋錨，請求監考人員破例讓他進場；B 回答「很抱歉，我也無能為力」，並解釋錄音一開始播放就不准任何人進場，否則對其他考生不公平；A 表示理解，會去詢問辦公室是否有補考場次。My hands are tied. 意為「我受規定限制，無能為力」，用於委婉表示不是自己不願意幫忙，而是規定不允許，與後文說明規定的內容相符。(A) Sure, just this once.「好吧，就這麼一次」，表示同意通融，與後文不准任何人進場矛盾 (C) Don't mention it.「不客氣」，用於回應對方的道謝，但 A 並沒有道謝 (D) It's your call.「由你決定」，把決定權交給對方，但能否進場取決於規定，而非 A 本人。故選 (B)。", "level": "C1", "topic": "explaining limits (exam rules)"}, {"id": "M464", "type": "grammar", "q": "Memorizing every word in a vocabulary book ______ makes you a fluent speaker than owning a set of expensive knives makes you a great chef.", "options": ["no more", "no less", "not only", "no sooner"], "answer": 0, "explain": "句意：背下單字書裡的每一個字並不會讓你成為說話流利的人，就如同擁有一套昂貴的刀具並不會讓你成為出色的廚師一樣。A no more ... than B 是「否定的類比」句型，意為「A 不…，就像 B 也不…一樣」，句中雖然沒有 not，兩邊卻都是否定；本句藉由「擁有好刀不等於好廚師」這個顯而易見的道理，說明「背單字不等於會說英語」。(B) no less ... than 意為「與…同樣（肯定）」，句意會變成背單字和擁有好刀都能讓人成為高手，違反常理 (C) not only 須與 but (also) 搭配，不能接 than (D) no sooner ... than 意為「一…就…」，表示兩個動作接連發生，通常搭配過去完成式，與本句的類比語意不合。故選 (A)。", "level": "C1", "topic": "no more ... than (negative comparison)"}, {"id": "M465", "type": "vocab", "q": "Nearsightedness is far more ______ among children in East Asia than in most other parts of the world, and many experts link this to long hours spent reading or looking at screens and too little time outdoors.", "options": ["contagious", "reversible", "prevalent", "obsolete"], "answer": 2, "explain": "句意：近視在東亞兒童之間比在世界上大多數其他地區普遍得多，許多專家認為這與長時間閱讀或盯著螢幕、戶外活動時間太少有關。prevalent「普遍的；盛行的」，常用 be prevalent among + 群體，與 far more ... than in most other parts of the world 的比較相符。(A) contagious「具傳染性的」，近視並非傳染病，後文提到的成因也是用眼習慣與戶外時間，而非傳染 (B) reversible「可逆的；可恢復的」，後文說明的是近視為何如此普遍，而非能否恢復 (D) obsolete「過時的；已廢棄的」，用來形容物品、技術或制度，不能形容疾病。故選 (C)。", "level": "C1", "topic": "eye health"}, {"id": "M466", "type": "dialogue", "q": "A: You don't look well, Kevin. Is everything all right?\nB: I was stuck in bed with the flu for most of the week, so I'm really behind on my history report. ______\nA: Of course. Just bring me a note from your doctor, and you can hand it in next Wednesday.", "options": ["Would there be any chance of an extension?", "You'd better give me a few more days.", "Is it all right if I hand it in early?", "Could you possibly write it for me?"], "answer": 0, "explain": "句意：A（老師）問 Kevin 是否一切安好；B（Kevin）說自己這星期大半時間都因流感臥病在床，歷史報告的進度嚴重落後，接著客氣地詢問「有沒有可能延後繳交期限？」；A 回答當然可以，只要帶醫生開立的證明，下星期三再交即可。Would there be any chance of...? 是向師長或上司提出請求時委婉而禮貌的說法，extension 指「（期限的）延長」，與老師同意延到下星期三相符。(B) You'd better give me a few more days. had better 帶有警告或命令的語氣，學生對老師這樣說顯得無禮 (C) Is it all right if I hand it in early?「我可以提早交嗎？」，與進度落後、老師允許晚交的內容矛盾 (D) Could you possibly write it for me?「您能幫我寫嗎？」是不恰當的要求，也與老師的回答接不上。故選 (A)。", "level": "C1", "topic": "asking for an extension"}, {"id": "M467", "type": "grammar", "q": "By the time the new MRT line finally opens next year, construction ______ for more than eight years, far longer than originally planned.", "options": ["had been going on", "will go on", "has gone on", "will have been going on"], "answer": 3, "explain": "句意：等到新的捷運路線明年終於通車時，工程將已持續進行超過八年，遠比原先規劃的時間長。By the time + 現在式（表未來）的句型中，主要子句用未來完成式或未來完成進行式，表示「到未來某一時間點為止，某動作將已持續了一段時間」，搭配 for more than eight years，故用 will have been going on。(A) had been going on 是過去完成進行式，用於「到過去某時為止」，與 next year 不符 (B) will go on 是單純未來式，無法表達到某一時間點為止已持續的期間 (C) has gone on 是現在完成式，只能表示到現在為止，無法延伸到明年。故選 (D)。", "level": "C1", "topic": "future perfect continuous"}, {"id": "M468", "type": "vocab", "q": "Before buying a new charger, make sure it is ______ with your phone, as the wrong type may charge it very slowly or, in some cases, even damage the battery.", "options": ["comparable", "compatible", "competent", "complacent"], "answer": 1, "explain": "句意：購買新的充電器之前，務必確認它與你的手機相容，因為規格不符的充電器可能充電非常緩慢，在某些情況下甚至會損壞電池。be compatible with「與…相容的；能搭配使用的」，常用於電子產品、軟體與設備。(A) comparable「可比較的；比得上的」，常接 to／with，指程度或品質相當，與能否搭配使用無關 (C) competent「能幹的；勝任的」(D) complacent「自滿的；自鳴得意的」，兩者都用來形容人，皆不合語意。故選 (B)。", "level": "C1", "topic": "consumer electronics"}, {"id": "M469", "type": "dialogue", "q": "A: The school still hasn't told me whether I can get a dorm room next semester. They say they'll let me know by Friday.\nB: ______ If you don't get one, my cousin has a spare room near campus.\nA: Thanks. I'll text you as soon as I hear from them.", "options": ["Keep it up.", "Keep the change.", "Keep me posted.", "Keep out of it."], "answer": 2, "explain": "句意：A 說學校還沒通知他下學期能否分配到宿舍，校方表示星期五前會告知；B 回答「有消息隨時告訴我」，並說如果沒分配到，他的表親在學校附近有一間空房；A 道謝，並說一收到通知就會傳訊息給 B。Keep me posted. 意為「有最新消息請隨時告訴我」，與 A 最後說「一收到消息就傳訊息給你」相呼應。(A) Keep it up.「繼續保持」，用於稱讚對方的好表現，但 A 只是在等候通知 (B) Keep the change.「不用找零了」，是付款時對店員說的話 (D) Keep out of it.「別插手」，要對方別管閒事，語氣不客氣，也與 B 主動表示能幫忙找房間矛盾。故選 (C)。", "level": "C1", "topic": "asking for updates"}, {"id": "M470", "type": "grammar", "q": "Despite the website's photos of a sunny balcony with a sea view, our hotel room turned out to be ______ relaxing: the walls were paper-thin, the air conditioner rattled all night, and construction work next door started at seven every morning.", "options": ["all but", "anything but", "nothing but", "none but"], "answer": 1, "explain": "句意：儘管網站上的照片是一個陽光充足、看得到海景的陽台，我們的飯店房間卻一點也不讓人放鬆：牆壁薄得像紙，冷氣整晚嘎嘎作響，隔壁的工程每天早上七點就開工。anything but + 形容詞意為「一點也不…；絕非…」（= not at all），與冒號後列舉的種種缺點相符。(A) all but 意為「幾乎」（= almost），all but relaxing 變成「幾乎令人放鬆」，與後文的抱怨矛盾 (C) nothing but 意為「只有；不過是」（= only），nothing but relaxing 變成「除了放鬆還是放鬆」，意思正好相反 (D) none but 意為「只有…（才）」，通常接人（如 none but the brave），不能接形容詞。故選 (B)。", "level": "C1", "topic": "anything but (= not at all)"}, {"id": "M471", "type": "vocab", "q": "Every extreme sport involves risks that are ______ in the activity itself: good equipment and proper training can reduce these risks, but they can never eliminate them entirely.", "options": ["immune", "indifferent", "exempt", "inherent"], "answer": 3, "explain": "句意：每一種極限運動都帶有活動本身固有的風險：良好的裝備與適當的訓練可以降低這些風險，卻永遠無法完全消除。be inherent in sth「為某事物所固有的；內在的」，與 in the activity itself 及冒號後「無法完全消除」相呼應。(A) immune「免疫的；不受影響的」，常接 to (B) indifferent「漠不關心的」，常接 to (C) exempt「被免除的」，常接 from，三者的介系詞搭配不同，語意也不合。故選 (D)。", "level": "C1", "topic": "extreme sports"}, {"id": "M472", "type": "dialogue", "q": "A: So after the hiking trip, we're thinking of spending a few days in Tainan, trying all the famous street food, and then maybe —\nB: That sounds amazing. ______ My train leaves in ten minutes.\nA: Oh, of course! Let's catch up properly next week.", "options": ["I hate to rush off, but I really have to get going.", "Sorry, I didn't catch your name.", "Take your time. I'm in no hurry.", "What's the rush?"], "answer": 0, "explain": "句意：A 說健行之後打算到台南待幾天，品嘗有名的小吃；B 回答「聽起來很棒，很抱歉要匆匆離開，但我真的得走了」，因為火車十分鐘後就要開；A 說當然，下星期再好好聊。I hate to rush off, but... 是在對方談興正濃時委婉結束對話的禮貌說法，先表示歉意，再說明理由，與後面的 My train leaves in ten minutes 相呼應。(B) Sorry, I didn't catch your name.「抱歉，我沒聽清楚你的名字」，兩人顯然早已認識，且與趕火車無關 (C) Take your time. I'm in no hurry.「慢慢來，我不趕時間」，與火車即將開走矛盾 (D) What's the rush?「急什麼？」是問對方為何匆忙，但趕時間的是 B 自己。故選 (A)。", "level": "C1", "topic": "ending a conversation"}, {"id": "M473", "type": "grammar", "q": "When it comes to protecting your personal information online, you can't be ______ careful: a single click on a fake link may be all it takes for criminals to get into your bank account.", "options": ["very", "too", "enough", "much"], "answer": 1, "explain": "句意：說到保護網路上的個人資料，再怎麼小心也不為過：只要點一下假連結，就可能讓歹徒入侵你的銀行帳戶。cannot be too + 形容詞是固定句型，意為「再怎麼…也不為過；越…越好」，用來強調某事極為重要；也可說 cannot be careful enough，但 enough 須置於形容詞之後。(A) very：can't be very careful 意為「無法非常小心」，與冒號後強調必須小心的警告矛盾 (C) enough 修飾形容詞時須放在形容詞後面（careful enough），不能放在前面 (D) much 不能直接修飾原級形容詞 careful。故選 (B)。", "level": "C1", "topic": "cannot ... too + adj. (emphasis)"}, {"id": "M474", "type": "vocab", "q": "Many students felt the new dress code was ______: no one could explain why black sneakers were allowed but white ones were not.", "options": ["consistent", "lenient", "arbitrary", "voluntary"], "answer": 2, "explain": "句意：許多學生覺得新的服裝規定很武斷：沒有人能解釋為什麼黑色運動鞋可以穿，白色的卻不行。arbitrary「武斷的；任意的」，指缺乏合理依據、全憑個人決定，與冒號後「沒有人能解釋原因」相呼應。(A) consistent「一致的；前後連貫的」，與規定缺乏道理的內容相反 (B) lenient「寬鬆的；寬大的」，規定連鞋子顏色都要限制，並不寬鬆 (D) voluntary「自願的」，服裝規定須強制遵守，且冒號後的說明重點也不在於是否自願。故選 (C)。", "level": "C1", "topic": "school rules"}, {"id": "M475", "type": "dialogue", "q": "A: We've been working on this poster for six hours straight, and I can hardly keep my eyes open.\nB: ______ We can finish the last few details tomorrow morning when we're fresh.\nA: Good idea. I'll save the file and shut down the computer.", "options": ["Let's call it a day.", "Let's get down to business.", "Let's make a night of it.", "Let's take it from the top."], "answer": 0, "explain": "句意：A 說兩人已經連續做了六個小時的海報，自己累得快睜不開眼睛；B 提議「今天就到此為止吧」，剩下的幾個細節明天早上精神好的時候再完成；A 同意，說會先存檔再關電腦。call it a day 意為「（工作）告一段落；今天就做到這裡」，與後文「明天早上再完成」相呼應。(B) Let's get down to business.「我們開始做正事吧」，用於開始認真工作，與兩人已經做了六個小時、準備休息的情境矛盾 (C) Let's make a night of it.「乾脆整晚盡情做下去吧」，表示要持續一整晚，與明天再做矛盾 (D) Let's take it from the top.「我們從頭再來一遍」，常用於排練，與只剩下幾個細節、準備休息的情境不符。故選 (A)。", "level": "C1", "topic": "ending a work session"}, {"id": "M476", "type": "grammar", "q": "The city has introduced a system ______ residents can report broken streetlights and damaged sidewalks simply by uploading a photo through an app.", "options": ["which", "whereas", "what", "whereby"], "answer": 3, "explain": "句意：市政府推出了一套系統，居民只要透過應用程式上傳照片，就能通報損壞的路燈與人行道。whereby 是正式文體常用的關係副詞，意為「藉此；憑藉該…」（= by which），引導形容詞子句修飾先行詞 a system，而子句 residents can report... 結構完整。(A) which 是關係代名詞，須在子句中擔任主詞或受詞，但後面的子句已經完整，須寫成 by which 或 through which 才正確 (B) whereas「然而；反之」是表對比的連接詞，不能引導形容詞子句修飾 a system (C) what 本身已包含先行詞，不能接在先行詞之後引導形容詞子句。故選 (D)。", "level": "C1", "topic": "relative adverb (whereby)"}, {"id": "M477", "type": "vocab", "q": "Planting more trees along city streets can help ______ the urban heat island effect, since their shade keeps pavements and buildings noticeably cooler.", "options": ["aggravate", "alleviate", "accelerate", "accommodate"], "answer": 1, "explain": "句意：在城市街道旁多種樹有助於緩解都市熱島效應，因為樹蔭能讓路面和建築物明顯涼爽許多。alleviate「減輕；緩和（問題或痛苦）」，與後文樹蔭降溫的說明相符。(A) aggravate「使惡化」，與文意相反 (C) accelerate「加速」，樹蔭降溫不會加速熱島效應 (D) accommodate「容納；提供住宿」，不合語意。故選 (B)。", "level": "C1", "topic": "urban heat"}, {"id": "M478", "type": "dialogue", "q": "A: I failed my driving test again this morning. That's the second time! Maybe I'm just not cut out for driving.\nB: ______ Plenty of good drivers needed three or four attempts. You'll get there.\nA: I hope you're right. I'll book another test for next month.", "options": ["Don't be so hard on yourself.", "I told you so.", "You can say that again.", "Lucky you!"], "answer": 0, "explain": "句意：A 說今天早上駕照路考又沒過，已經是第二次了，也許自己根本不是開車的料；B 回答「別對自己這麼苛刻」，並說很多開車技術很好的人也考了三、四次才通過，A 一定會考過的；A 說希望如此，會預約下個月再考一次。Don't be so hard on yourself. 意為「別對自己太嚴苛」，用來安慰自責的人，與後面的鼓勵相符；be cut out for 意為「天生適合…」。(B) I told you so.「我早就跟你說過了」，帶有責怪的意味，不符合安慰的語境 (C) You can say that again.「你說得一點也沒錯」，表示強烈同意，等於認同 A 不是開車的料，與後面的鼓勵矛盾 (D) Lucky you!「你真幸運！」，用於羨慕或恭喜對方，與考試失敗的情境相反。故選 (A)。", "level": "C1", "topic": "reassurance"}, {"id": "M479", "type": "grammar", "q": "For many first-year university students, the biggest challenge is not so much the difficulty of the courses ______ the sudden freedom to manage their own time.", "options": ["but", "than", "rather", "as"], "answer": 3, "explain": "句意：對許多大一新生來說，最大的挑戰與其說是課程的難度，不如說是突然可以自行安排時間的自由。not so much A as B 是固定句型，意為「與其說是 A，不如說是 B」。(A) but 用於 not A but B「不是 A 而是 B」，前面不加 so much (B) than 用於比較級（如 more...than），不能與 not so much 搭配 (C) rather 須與 than 連用（A rather than B），單獨使用無法連接兩個名詞片語。故選 (D)。", "level": "C1", "topic": "not so much ... as"}, {"id": "M480", "type": "vocab", "q": "To win back the public's trust, the city government has promised to be more ______ about how taxpayers' money is spent, publishing every major contract online for anyone to read.", "options": ["reluctant", "extravagant", "transparent", "ambiguous"], "answer": 2, "explain": "句意：為了贏回民眾的信任，市政府承諾在稅金的使用上會更加透明，將每一份重大合約公布在網路上供大眾查閱。transparent「透明的；公開的」，be transparent about sth 指公開說明、毫不隱瞞，與 publishing every major contract online 相符。(A) reluctant「不情願的」，與主動公開合約的做法矛盾 (B) extravagant「奢侈浪費的」，無法贏回民眾的信任 (D) ambiguous「模稜兩可的」，與公開透明的做法相反。故選 (C)。", "level": "C1", "topic": "public finance"}, {"id": "M481", "type": "vocab", "q": "Velcro grew out of a ______ discovery: the Swiss engineer George de Mestral was not looking for a new way to fasten things at all, but after a walk with his dog, he grew curious about why burrs clung so stubbornly to its fur and examined them under a microscope.", "options": ["gratuitous", "calamitous", "fortuitous", "ubiquitous"], "answer": 2, "explain": "句意：魔鬼氈源自一次偶然的發現：瑞士工程師喬治．德梅斯特拉爾（George de Mestral）原本根本不是在尋找新的黏扣方法，而是在一次遛狗之後，好奇植物的刺果為何會牢牢黏在狗毛上，便把刺果放在顯微鏡下觀察。fortuitous 意為「偶然發生的；碰巧的（且往往帶來好結果）」，冒號後的說明（他並非刻意研究，而是遛狗後偶然產生了好奇）正好解釋了「偶然」。(A) gratuitous「無端的；不必要的」，常用 gratuitous violence（不必要的暴力情節）(B) calamitous「災難性的」(D) ubiquitous「無所不在的」，三者都與冒號後所描述的偶然發現無關。故選 (C)。", "level": "C2", "topic": "history of invention"}, {"id": "M482", "type": "grammar", "q": "The prize will go to ______ submits the most original design for the new school logo, regardless of which grade they are in.", "options": ["whoever", "whomever", "who", "whose"], "answer": 0, "explain": "句意：不論就讀哪個年級，獎項都將頒給為學校新標誌提出最具原創性設計的人。複合關係代名詞 whoever 意為「任何…的人」（= anyone who），整個 whoever submits... 名詞子句作介系詞 to 的受詞；但在子句內部，whoever 是動詞 submits 的主詞，因此必須用主格。(B) whomever 是受格，雖然緊接在介系詞 to 之後，但它在子句中擔任的是主詞，誤用受格是常見的「矯枉過正」錯誤 (C) who 在現代英語中須有先行詞（如 the student who submits...），不能單獨表示「任何…的人」(D) whose 是所有格，後面必須接名詞（如 whose design is chosen），不能直接接動詞。故選 (A)。", "level": "C2", "topic": "nominal relative clause (whoever)"}, {"id": "M483", "type": "dialogue", "q": "A: How did your job interview at the design studio go?\nB: ______ They asked me to walk them through a piece of software I'd never even opened.\nA: Oh dear. Well, at least you'll know what to prepare for next time.", "options": ["Couldn't have gone better.", "It went off without a hitch.", "I've got it in the bag.", "It could have gone better."], "answer": 3, "explain": "句意：A 問 B 在設計工作室的求職面試結果如何；B 委婉地說「本來可以更順利一些」，接著說對方要他逐步講解一套他連打開都沒打開過的軟體；A 說「真糟糕。不過至少下次你就知道該準備什麼了」。It could have gone better. 字面意思是「本來可以更好」，是英語常見的低調陳述（understatement），實際上是委婉地表示「進行得不太順利」，與後文被問倒的經驗以及 A 的安慰相符。(A) Couldn't have gone better.「再順利不過了」(B) It went off without a hitch.「進行得十分順利，毫無差錯」(C) I've got it in the bag.「我已經穩操勝券」，三者都表示面試非常成功，與後文被問倒的經驗以及 A 的安慰矛盾。故選 (D)。", "level": "C2", "topic": "job interviews"}, {"id": "M484", "type": "vocab", "q": "A good referee must be entirely ______: she should have nothing to gain whichever team wins and should care only that the rules are applied fairly to both sides.", "options": ["uninterested", "disinterested", "disaffected", "disenchanted"], "answer": 1, "explain": "句意：一位好裁判必須完全公正無私：無論哪一隊獲勝，她都不會因此得到任何好處，她在意的只是規則是否公平地適用於雙方。disinterested 意為「無私心的；公正的；與結果沒有利害關係的」，正好對應冒號後「勝負與己無關」的說明。(A) uninterested 意為「不感興趣的；漠不關心的」，是常與 disinterested 混淆的近形詞；裁判若對比賽漠不關心，就無法專注執法，也與「在意規則是否公平」矛盾 (C) disaffected「（對組織、政府等）心懷不滿的；疏離的」(D) disenchanted「不再抱有幻想的；感到幻滅的」，兩者都與「公正」無關。故選 (B)。", "level": "C2", "topic": "sports officiating"}, {"id": "M485", "type": "grammar", "q": "It was ______ I have ever seen on a school stage: by the final scene, half the audience was in tears.", "options": ["as a moving performance as", "so moving performance as", "as moving a performance as", "such moving a performance as"], "answer": 2, "explain": "句意：那是我在學校舞台上看過最感人的演出：到了最後一幕，半數觀眾都已淚流滿面。as moving a performance as I have ever seen 字面意思是「和我看過的任何演出一樣感人」，也就是「我看過最感人的演出」。當 as、so、too、how 修飾「形容詞 + 單數可數名詞」時，語序必須是「as + 形容詞 + a/an + 名詞」，因此要說 as moving a performance as。(A) as a moving performance as 把冠詞 a 錯置在 as 與形容詞之間 (B) so moving performance as 缺少冠詞，而且比較同等程度時，so...as 一般只用於否定句（如 not so moving as）(D) such 的正確語序是「such + a/an + 形容詞 + 名詞」（such a moving performance），such moving a performance 語序錯誤。故選 (C)。", "level": "C2", "topic": "as + adj. + a + noun"}, {"id": "M486", "type": "dialogue", "q": "A: Kevin says he's going to get up at six every morning this summer to go jogging.\nB: ______ He can barely get out of bed by noon on weekends.\nA: Ha! I suppose we'll find out soon enough.", "options": ["And pigs might fly.", "I wouldn't put it past him.", "Good for him.", "That figures."], "answer": 0, "explain": "句意：A 說 Kevin 宣稱今年暑假每天早上六點都要起床去慢跑；B 說「那太陽都要打西邊出來了」，接著指出他週末連中午都很難起得了床；A 笑說「哈！我想很快就會見分曉」。And pigs might fly. 字面意思是「豬也許會飛」，是英語中用來諷刺某事「根本不可能發生」的慣用語（此為英式說法，美式英語多說 When pigs fly.），相當於中文的「太陽打西邊出來」，與後文 Kevin 平日賴床的習慣相呼應。(B) I wouldn't put it past him.「他還真做得出這種事」，表示相信某人有可能做出某事（多指令人意外或不好的事），等於認為 Kevin 真的會早起，與後文矛盾 (C) Good for him.「他真了不起；替他高興」，是真心讚許，與 B 懷疑的語氣不符 (D) That figures.「難怪；果然如此」，用於某事符合預期時，但早起慢跑並不符合 Kevin 一向的作風。故選 (A)。", "level": "C2", "topic": "summer resolutions"}, {"id": "M487", "type": "grammar", "q": "All visitors to the national park, ______ local residents or foreign tourists, must stay on the marked trails and take their trash home with them.", "options": ["were they", "being they", "are they", "be they"], "answer": 3, "explain": "句意：所有到國家公園的遊客，無論是當地居民還是外國觀光客，都必須走在標示的步道上，並把自己的垃圾帶回家。be they A or B 是保留原形動詞 be 的假設語氣倒裝句型，意為「無論他們是 A 還是 B」，等於 whether they are A or B，屬於正式的書面用法。(A) were they 是省略 if 的倒裝條件句（= if they were），表示與現在事實相反的假設，不能表示「無論…或…」的讓步 (B) being they 不合文法；分詞構句若要保留主詞，應寫成 they being... (C) are they 是疑問句的語序，不能放在句中表示讓步。故選 (D)。", "level": "C2", "topic": "subjunctive concession (be they ... or ...)"}, {"id": "M488", "type": "vocab", "q": "Some students argue that silently watching a classmate being bullied is ______ to taking part in it, since a bully is often encouraged by an audience that does nothing.", "options": ["paramount", "tantamount", "commensurate", "incumbent"], "answer": 1, "explain": "句意：有些學生認為，眼睜睜看著同學被霸凌卻保持沉默，就等同於參與霸凌，因為旁觀者的袖手旁觀往往會讓霸凌者更加肆無忌憚。tantamount to + N／V-ing 意為「等同於…；無異於…」，通常用於負面的事。(A) paramount 意為「至高無上的；最重要的」（如 of paramount importance），沒有「等同於」的意思 (C) commensurate「相稱的；相當的」，固定搭配是 commensurate with（如 a salary commensurate with experience），介系詞不合 (D) incumbent「有責任的；有義務的」，固定用法為 it is incumbent on／upon sb to V，語意與結構皆不合。故選 (B)。", "level": "C2", "topic": "bullying"}, {"id": "M489", "type": "dialogue", "q": "A: I've just realized something. If we leave all our studying until the night before the exam, we won't have time to cover everything.\nB: ______ That's exactly what I've been telling you for the past month.\nA: All right, all right. Let's make a study schedule tonight.", "options": ["Come again?", "Says who?", "You don't say.", "That's news to me."], "answer": 2, "explain": "句意：A 說自己剛發現一件事：如果把所有的讀書進度都拖到考前一晚，就不可能讀完全部範圍；B 用反諷的語氣說「這還用說」，接著表示「這一個月來我一直都是這麼跟你說的」；A 說「好吧，好吧。我們今晚就來訂讀書計畫」。You don't say. 字面上是表示驚訝的「真的嗎」，但在此語境中是反諷，暗示對方說的是早就顯而易見的事，正好與後文「我一直這麼跟你說」相呼應。(A) Come again?「你說什麼？請再說一次」，用於沒聽清楚或難以置信，與後文接不上 (B) Says who?「誰說的？」，用來質疑對方的說法，但 B 其實完全同意 A (D) That's news to me.「這我倒是第一次聽說」，與 B 已經講了一個月的事實矛盾。故選 (C)。", "level": "C2", "topic": "exam preparation"}, {"id": "M490", "type": "grammar", "q": "When a young bookbinder's apprentice named Michael Faraday attended a series of lectures by the chemist Humphry Davy in 1812, few could have guessed that he ______ one of the greatest experimental scientists of the nineteenth century.", "options": ["was to become", "was to have become", "had become", "has become"], "answer": 0, "explain": "句意：1812 年，一位名叫麥可．法拉第的年輕書籍裝訂學徒去聽了化學家漢弗里．戴維的一系列演講，當時幾乎沒有人猜得到，他日後會成為十九世紀最偉大的實驗科學家之一。was／were to + V 表示「（從過去的角度看）日後將會…；注定會…」，用來敘述在過去某個時間點之後確實發生的事，屬於「過去未來」（future in the past）的正式用法；本句也可改用 would become，但不能用表示與過去事實相反的 would have become。(B) was to have become 是「was to have + p.p.」，表示「原本預定要…，結果卻沒有實現」，但法拉第確實成為了偉大的科學家，語意矛盾 (C) had become 過去完成式表示在 1812 年之前就已經成為，時間順序錯誤 (D) has become 現在完成式，與主要子句的過去時態及 1812 年不一致。故選 (A)。", "level": "C2", "topic": "future in the past (was to + V)"}, {"id": "M491", "type": "vocab", "q": "The factory's brief statement did little to ______ the fears of nearby residents, who had watched thick black smoke pour from its chimneys for three days without any explanation.", "options": ["ally", "allege", "alloy", "allay"], "answer": 3, "explain": "句意：工廠發表的簡短聲明，幾乎無法消除附近居民的恐懼，因為他們已經連續三天看著濃濃的黑煙從煙囪冒出，卻得不到任何解釋。allay 意為「減輕；消除（恐懼、疑慮、憂慮）」，常見搭配有 allay fears／concerns／suspicions；do little to V 則意為「對…幾乎沒有幫助」。(A) ally「使結盟」，常用 ally oneself with sb (B) allege「（未經證實地）聲稱；指控」(C) alloy「把（金屬）熔合成合金」，三者都不能以 fears 為受詞表示「消除恐懼」。故選 (D)。", "level": "C2", "topic": "industrial pollution"}, {"id": "M492", "type": "dialogue", "q": "A: I can't believe you didn't enjoy the beef noodles at that shop. It won a citywide beef noodle competition a few years ago!\nB: ______ What matters is that the broth has been bland ever since the new owners took over.\nA: Hmm, maybe I should try it again and see for myself.", "options": ["That's the whole point.", "That's neither here nor there.", "There are no two ways about it.", "Here's hoping."], "answer": 1, "explain": "句意：A 不敢相信 B 竟然不喜歡那家店的牛肉麵，因為它幾年前還在全市牛肉麵比賽中得過獎；B 說「那無關緊要」，重點是自從新老闆接手後，湯頭就一直淡而無味；A 說也許該再去吃一次，親自確認看看。That's neither here nor there. 意為「那無關緊要；那與現在討論的事無關」，B 用來表示過去的得獎紀錄不能代表現在的品質，與後面的 What matters is... 相呼應。(A) That's the whole point.「那正是重點所在」，與 B 接著說「真正重要的是…」矛盾 (C) There are no two ways about it.「那是毫無疑問的」，是強烈同意的說法，與 B 反駁的語氣不符 (D) Here's hoping.「但願如此」，用於表達對未來的期望，但 A 說的是過去已經發生的事實。故選 (B)。", "level": "C2", "topic": "restaurant reviews"}, {"id": "M493", "type": "grammar", "q": "______ the final exams next week and the band's farewell concert on Saturday, I've barely had time to eat, let alone sleep.", "options": ["What with", "As for", "Except for", "Given that"], "answer": 0, "explain": "句意：一方面下週要期末考，另一方面樂團週六又要舉行告別演出，我連吃飯的時間都快沒有了，更別說睡覺了。what with A and B 意為「由於 A 再加上 B（等種種原因）」，用來列舉造成某種狀況（多半是忙碌、困擾等負面情況）的幾個原因，後面接名詞片語。(B) As for「至於…」，用於轉換話題 (C) Except for「除了…之外」，兩者語意皆不合 (D) Given that「有鑑於…；考慮到…」，後面必須接完整子句（that + S + V），不能直接接名詞片語。故選 (A)。", "level": "C2", "topic": "what with (listing causes)"}, {"id": "M494", "type": "vocab", "q": "The company won its long court battle against a small rival, but it was a ______ victory: the legal fees and the damage to its public image cost it far more than it ever gained from the ruling.", "options": ["Herculean", "Spartan", "Pyrrhic", "Platonic"], "answer": 2, "explain": "句意：這家公司在與一家小型競爭對手的長期訴訟中勝訴，但這是一場得不償失的勝利：龐大的律師費和公眾形象受損所付出的代價，遠遠超過它從判決中得到的好處。Pyrrhic victory 意為「代價慘重的勝利；得不償失的勝利」，源自古希臘伊庇魯斯國王皮洛士（Pyrrhus），他雖然在戰役中擊敗羅馬軍隊，自己卻也傷亡慘重。(A) Herculean「需要極大力氣的；極其艱鉅的」，常用 a Herculean task／effort，形容任務本身而非得不償失的結果 (B) Spartan「簡樸的；刻苦的」，常用 spartan conditions／lifestyle (D) Platonic「柏拉圖式的；純精神層面的」，常用 a platonic friendship，三者都與冒號後「代價大於收穫」的說明無關。故選 (C)。", "level": "C2", "topic": "lawsuits"}, {"id": "M495", "type": "grammar", "q": "After three weeks of silence, the company finally replied to my complaint — ______ its reply told me anything I didn't already know.", "options": ["except that", "not as", "nor that", "not that"], "answer": 3, "explain": "句意：沉寂了三個星期之後，那家公司終於回覆了我的投訴——倒不是說他們的回覆告訴了我什麼我原本不知道的事。Not that + 子句 意為「倒不是說…；並不是…」，用來補充說明，以免前句造成誤解或過高的期待；子句中的 anything 通常只用於否定或疑問的語境，正好由 not 提供否定意義。(A) except that「只不過…；除了…之外」，後接肯定陳述，與 anything 不搭配，語意也自相矛盾 (B) not as 無法引導子句表示「並不是說」，結構不完整 (C) nor 之前必須有否定句，其後還須倒裝（如 nor did its reply...），nor that 不成結構。故選 (D)。", "level": "C2", "topic": "not that (disclaimer clause)"}, {"id": "M496", "type": "dialogue", "q": "A: I lent Ray my laptop for a day, and he gave it back with a sticky keyboard and a cracked screen. Then he told everyone it was already broken when he borrowed it!\nB: ______\nA: Exactly. I'm never lending him anything again.", "options": ["No harm done, then.", "With friends like that, who needs enemies?", "It's the thought that counts.", "Every cloud has a silver lining."], "answer": 1, "explain": "句意：A 說他把筆電借給 Ray 一天，結果還回來時鍵盤黏膩、螢幕也裂了，Ray 還四處跟別人說筆電借來時就已經壞了；B 說「有這種朋友，誰還需要敵人？」；A 說「沒錯。我再也不會借他任何東西了」。With friends like that, who needs enemies? 是帶有反諷意味的慣用語，表示某位「朋友」的所作所為比敵人還糟，正好回應 Ray 弄壞電腦又推卸責任的行為，A 也以 Exactly 表示贊同。(A) No harm done, then.「那就沒造成什麼損害」，與鍵盤黏膩、螢幕破裂的事實矛盾 (C) It's the thought that counts.「心意最重要」，通常用於收到不盡理想的禮物或幫忙時 (D) Every cloud has a silver lining.「黑暗中總有一線光明」，用來安慰人看事情好的一面，但此事沒有任何好的一面可言，也與 A 憤怒的反應不符。故選 (B)。", "level": "C2", "topic": "unreliable friends"}, {"id": "M497", "type": "vocab", "q": "The feedback I got from the online writing course was so ______ — just 'Nice work!' typed under every assignment — that I doubted anyone had actually read my essays.", "options": ["perfunctory", "peremptory", "pernicious", "precocious"], "answer": 0, "explain": "句意：我從線上寫作課程得到的回饋實在太敷衍了——每份作業下面都只打了一句「做得好！」——以致我懷疑根本沒有人真正讀過我的文章。perfunctory 意為「敷衍了事的；草率的；例行公事般的」，常形容未經用心、只為應付而做的動作或回應，如 a perfunctory glance／reply。(B) peremptory「專橫的；不容分說的」，常形容命令或語氣，如 a peremptory tone，與一句簡短的稱讚不符 (C) pernicious「有害的；逐漸造成嚴重傷害的」(D) precocious「早熟的」，多形容兒童，兩者皆不能形容敷衍的評語。故選 (A)。", "level": "C2", "topic": "feedback on writing"}, {"id": "M498", "type": "grammar", "q": "The fastest high-speed trains now travel between Taipei and Kaohsiung in under two hours, far more quickly than ______ the steam trains of a century ago.", "options": ["were", "had", "did", "have"], "answer": 2, "explain": "句意：如今最快的高鐵列車行駛於台北與高雄之間只需不到兩小時，遠比一百年前的蒸汽火車快得多。在 than 或 as 引導的比較子句中，為了避免重複，可用助動詞代替前面的動詞；在正式文體中，助動詞還可以移到主詞之前形成倒裝，即 than did the steam trains（= than the steam trains did）。主要子句的動詞 travel 是一般動詞，而蒸汽火車是一百年前的事，故用過去式助動詞 did。(A) were 是 be 動詞，不能代替一般動詞 travel (B) had 是過去完成式的助動詞，須有另一個過去時間點作為基準，與 a century ago 單純描述過去的情況不合 (D) have 是現在完成式的助動詞，不能與 a century ago 這類明確的過去時間連用。故選 (C)。", "level": "C2", "topic": "comparative clause inversion (than did)"}, {"id": "M499", "type": "dialogue", "q": "A: Durian ice cream? That sounds absolutely disgusting.\nB: ______ I used to think so too, but one spoonful changed my mind — it's rich and creamy, and it tastes nothing like it smells.\nA: Fine, I'll try a little. But if I hate it, you're finishing the rest.", "options": ["I couldn't agree more.", "Your guess is as good as mine.", "That's the spirit!", "Don't knock it till you've tried it."], "answer": 3, "explain": "句意：A 說榴槤冰淇淋聽起來實在很噁心；B 說「沒吃過就先別急著批評」，自己以前也這麼認為，但吃了一口就改觀了——口感濃郁滑順，吃起來和聞起來完全不同；A 勉強同意吃一點，但表示如果不喜歡，剩下的就要 B 吃完。Don't knock it till you've tried it. 意為「沒試過就別急著批評」，knock 在此為口語用法，指「批評、貶低」，用於勸對方先親身嘗試再下評論；B 接著以自身經驗現身說法，A 最後也答應試吃，前後文完全一致。(A) I couldn't agree more.「我完全同意」，等於附和 A「很噁心」的看法，與 B 接著說自己已經改觀相矛盾 (B) Your guess is as good as mine.「我也不知道」，用於雙方都不清楚答案時，但 A 是在表達反感而非提問，且 B 隨即具體描述了味道，顯然並非不知道 (C) That's the spirit!「就是要有這種精神」，用於稱讚對方積極、願意嘗試的態度，而 A 此時正排斥嘗試，用法不合。故選 (D)。", "level": "C2", "topic": "trying new foods"}, {"id": "M500", "type": "vocab", "q": "The three-day trip to Osaka was ______ a study tour of robotics companies, yet the itinerary included just one two-hour factory visit and several long afternoons of shopping.", "options": ["ostentatiously", "ostensibly", "obstinately", "obsequiously"], "answer": 1, "explain": "句意：這趟為期三天的大阪之旅名義上是參訪機器人公司的研習之旅，但行程中卻只安排了一場兩小時的工廠參觀，以及好幾個漫長的購物下午。ostensibly 意為「表面上；名義上」，暗示實際情況並非如此，正好與 yet 後面所描述的實際行程形成對比。(A) ostentatiously「炫耀地；招搖地」，與 ostensibly 字形相近但語意完全不同 (C) obstinately「固執地；頑強地」(D) obsequiously「諂媚地；奉承地」，三者都無法表達「名義上…，實際上…」的對比。故選 (B)。", "level": "C2", "topic": "school trips"}, {"id": "M501", "type": "vocab", "q": "After years of living right next to the railway line, the family had become so ______ to the rumble of passing trains that they slept soundly through it every night.", "options": ["averse", "susceptible", "inured", "attentive"], "answer": 2, "explain": "句意：在鐵道旁住了多年之後，那一家人對火車經過的隆隆聲已經習以為常，每天晚上都能安然入睡。be/become inured to sth 意為「對（不愉快、艱苦的事物）習以為常而不再受其影響」，多用於噪音、批評、痛苦、艱困環境等負面事物；so...that 說明正因為已經習慣，他們才能一覺到天亮。(A) averse 厭惡的；反對的（be averse to sth），若厭惡這種噪音，便無法說明為何能安然入睡 (B) susceptible 易受影響的（be susceptible to sth），表示容易被噪音干擾，與 slept soundly 矛盾 (D) attentive 留心的；注意的（be attentive to sth），表示特別留意火車聲，同樣與安然入睡相反。故選 (C)。", "level": "C2", "topic": "living environment"}, {"id": "M502", "type": "dialogue", "q": "A: So how was that new superhero movie everyone's been talking about?\nB: ______\nA: That bad, huh? I'll wait until it's on a streaming service, then.", "options": ["Let's just say the popcorn was good.", "I'd see it again in a heartbeat.", "It lived up to all the hype.", "I can't wait for the sequel."], "answer": 0, "explain": "句意：A 問 B 那部大家都在討論的新超級英雄電影好不好看；B 回答「這麼說吧，爆米花倒是挺好吃的」；A 回應「有那麼糟啊？那我等它上了串流平台再看好了」。Let's just say... 意為「這麼說吧…」，常用來暗示不便明說的意思；評論電影時只稱讚與電影本身無關的爆米花，正是以「明褒實貶」（damning with faint praise）的方式暗示電影乏善可陳，所以 A 才會說 That bad, huh?。(B) I'd see it again in a heartbeat.「我會毫不猶豫地再看一次」(C) It lived up to all the hype.「它完全不負眾望；名副其實」(D) I can't wait for the sequel.「我等不及要看續集了」，三者都是正面評價，與 A 的反應 That bad 互相矛盾。故選 (A)。", "level": "C2", "topic": "implicature (faint praise)"}, {"id": "M503", "type": "grammar", "q": "After the operation, the surgeon recommended that my grandfather ______ anything heavier than a small bag of rice for at least six weeks.", "options": ["doesn't lift", "not to lift", "not lifting", "not lift"], "answer": 3, "explain": "句意：手術後，外科醫師建議我祖父至少六週內不要提任何比一小袋米還重的東西。recommend、suggest、insist、demand、require 等表示「建議、要求」的動詞，其後的 that 子句須用原形動詞（假設語氣，美式英語常見）或 should + 原形動詞（英式英語常見）；否定時直接把 not 置於原形動詞之前，不加助動詞 do，即 that + S + not + V，本句 that my grandfather not lift ＝ that my grandfather should not lift。(A) doesn't lift 是直述語氣的現在式，既不符合假設語氣，也與過去式 recommended 的時態不一致 (B) not to lift 為不定詞，that 子句須有限定動詞，不能以不定詞充當 (C) not lifting 為動名詞，同樣不能作 that 子句的動詞。故選 (D)。", "level": "C2", "topic": "mandative subjunctive (negative)"}, {"id": "M504", "type": "vocab", "q": "Many countries now ______ the use of plastic microbeads in rinse-off products such as face scrubs and toothpaste, because many of the tiny particles slip through wastewater treatment plants and end up in rivers and the sea.", "options": ["prescribe", "proscribe", "ascribe", "subscribe"], "answer": 1, "explain": "句意：如今許多國家都明令禁止在洗面乳、牙膏等用後須沖洗的產品中使用塑膠柔珠，因為許多微小的顆粒會穿過污水處理廠，最後流入河川與海洋。proscribe「（以法令）禁止」，為正式用語，相當於 ban、prohibit；because 子句說明柔珠造成污染，可知各國採取的做法是禁止使用。(A) prescribe 規定；開（藥方），prescribe the use of... 意為「規定須使用…」，與後文說明污染的理由正好相反；prescribe 與 proscribe 只差一個字母，是常見的混淆 (C) ascribe 把…歸因於，常用 ascribe A to B (D) subscribe 訂閱；贊同，表示「贊同」時須接 to（如 subscribe to a view），兩者皆不合語意。故選 (B)。", "level": "C2", "topic": "environmental regulation"}, {"id": "M505", "type": "grammar", "q": "That summer, the village was hit by a flood ______ even the oldest villagers had never seen.", "options": ["the like of which", "the like of it", "which the like of", "the likes of whom"], "answer": 0, "explain": "句意：那年夏天，村子遭受了一場洪水，其規模之大，連村裡最年長的居民都前所未見。the like 在此作名詞，意為「與之相似的人或事物」；the like of which 引導形容詞子句修飾先行詞 a flood，which 指這場洪水，本句相當於 ...a flood, and even the oldest villagers had never seen the like of it。這是 the like of which had never been seen 一類的正式說法，用來強調某事前所未有。(B) the like of it：it 是人稱代名詞，不能引導子句，兩個子句之間缺少連接詞 (C) which the like of 詞序錯誤：which 是介系詞 of 的受詞，必須連同 the like of 整個名詞片語一起移到子句開頭，寫成 the like of which (D) the likes of whom：whom 只能指人，不能用來指洪水（非正式用法中也有人說 the likes of which，但關係代名詞仍須用 which）。故選 (A)。", "level": "C2", "topic": "relative clause (the like of which)"}, {"id": "M506", "type": "dialogue", "q": "A: Are you taking the overnight bus to Kaohsiung again for the long weekend?\nB: ______ Last time the driver kept the bus so cold that I couldn't sleep a wink.\nA: Then you'd better book a high-speed rail ticket before they sell out.", "options": ["I wouldn't miss it for the world.", "By all means.", "Not if I can help it.", "You can count on it."], "answer": 2, "explain": "句意：A 問 B 連假是不是又要搭夜班客運去高雄；B 回答「能不搭就不搭」，並說上次司機把車內冷氣開得太強，冷得他整晚都沒睡著；A 說那最好趁票還沒賣完趕快訂高鐵車票。Not if I can help it. 意為「只要能避免，我就絕不（這麼做）」，can help 在此作「避免；克制」解，相當於 not if I can avoid it；B 接著說明上次搭夜車的痛苦經驗，A 也順勢建議改搭高鐵，可知 B 並不想再搭夜班客運。(A) I wouldn't miss it for the world.「我說什麼都不會錯過」，表示非常期待 (B) By all means.「當然可以；請便」，用於答應對方的請求或允許對方做某事，但 A 並非徵求許可，而是詢問 B 的打算 (D) You can count on it.「放心，我一定會」，表示一定會去做；(A)(D) 都與 B 接著抱怨上次搭夜車的經驗矛盾。故選 (C)。", "level": "C2", "topic": "avoiding an unpleasant trip"}, {"id": "M507", "type": "vocab", "q": "When I asked my usually chatty brother how his university interview had gone, he gave a ______ reply — 'Fine.' — and went straight to his room.", "options": ["verbose", "effusive", "loquacious", "laconic"], "answer": 3, "explain": "句意：我問平常很愛聊天的哥哥大學面試的情況如何，他只簡短地回了一句「還好。」就直接回房間了。laconic「（說話、文字）簡短的；言簡意賅的；寡言的」，破折號之間只有一個字的回答 'Fine.' 正是 laconic reply 的具體例子，usually chatty（平常愛聊天）則凸顯他這次反常的寡言。(A) verbose 冗長的；用字累贅的 (B) effusive（感情）洋溢的；熱情奔放的，常形容讚美或感謝（如 effusive praise）(C) loquacious 健談的；話多的，三者都與只回答一個字的冷淡反應相反。故選 (D)。", "level": "C2", "topic": "family communication"}, {"id": "M508", "type": "grammar", "q": "When my sister asked whether the swimming pool would stay open during the typhoon, I said I thought ______, since it had closed during every storm the previous summer.", "options": ["so", "not", "no", "it"], "answer": 1, "explain": "句意：妹妹問我颱風期間游泳池會不會照常開放，我說我認為不會，因為前一年夏天每次颱風來襲時它都關閉了。think、hope、expect、suppose、be afraid 等動詞之後，可用 so 代替前文提過的肯定子句、用 not 代替否定子句，以避免重複；I thought not ＝ I thought (that) the pool would not stay open（較口語的說法是 I didn't think so）。since 子句指出泳池過去遇到颱風都會關閉，可知說話者的判斷是否定的。(A) so 代替肯定子句，表示「我認為會開放」，與 since 子句的理由矛盾 (C) no 是限定詞或用於回答的副詞，不能用來代替子句 (D) it 不能代替 that 子句作 think 的受詞，英文不說 I thought it 來表示「我認為如此」。故選 (B)。", "level": "C2", "topic": "substitution (think so / think not)"}, {"id": "M509", "type": "dialogue", "q": "A: You won't believe this — my brother cleaned the whole kitchen this morning without anyone asking him to.\nB: ______ What's the occasion?\nA: No idea. Maybe he wants to borrow some money.", "options": ["Well, that's a first!", "That's par for the course.", "Old habits die hard.", "That's just like him."], "answer": 0, "explain": "句意：A 說「你一定不敢相信——我弟弟今天早上沒人叫他，就自己把整個廚房打掃乾淨了」；B 回應「這可真是破天荒頭一遭！」並問有什麼特別的原因；A 說不知道，也許他想借錢。that's a first 意為「這還是第一次；真是破天荒」，常帶有幽默或揶揄的意味，暗示對方平常從不這麼做，與 B 接著追問 What's the occasion?（有什麼特別的理由嗎？）相呼應。(B) That's par for the course.「這是意料中的事；司空見慣」，與 A 的 You won't believe this 及 B 的驚訝追問不符 (C) Old habits die hard.「積習難改」，用於說明人難以改掉舊習慣，但弟弟此次正是一反常態 (D) That's just like him.「這很像他會做的事」，表示此舉符合弟弟一貫的作風，同樣與驚訝的語氣矛盾。故選 (A)。", "level": "C2", "topic": "irony (expressing surprise)"}, {"id": "M510", "type": "vocab", "q": "The second-hand shop offered me a ______ NT$300 for my three-year-old laptop, which still worked perfectly, so I decided to sell it online instead.", "options": ["decorous", "desultory", "derisory", "deleterious"], "answer": 2, "explain": "句意：二手店只願意出少得可笑的新台幣三百元收購我那台用了三年、仍然完全正常運作的筆電，所以我決定改在網路上賣。derisory「（金額、數量）少得可笑的；微不足道的」，常與 offer、sum、amount 等搭配；一台運作正常的筆電只值三百元，出價低得荒謬，說話者才會改到網路上賣。(A) decorous 端莊得體的；合乎禮儀的，形容人的舉止 (B) desultory 漫無目的的；敷衍零散的，形容行為或談話（如 a desultory conversation）(D) deleterious 有害的（＝ harmful），形容對健康或環境的影響，三者皆不能形容出價過低。另須注意 derisory 不要與 derisive「嘲弄的」（如 derisive laughter）混淆。故選 (C)。", "level": "C2", "topic": "second-hand market"}, {"id": "M511", "type": "grammar", "q": "The new night market quickly became a hit with tourists — ______ that the city had to add extra bus services on weekend evenings.", "options": ["such as", "so much so", "so much as", "as much as"], "answer": 1, "explain": "句意：這座新夜市很快就大受觀光客歡迎——受歡迎的程度甚至讓市政府不得不在週末晚上加開公車班次。so much so that... 為固定用法，意為「到了…的程度，以致於…」，用來補充說明前述情況（became a hit with tourists）的程度之深，並引出其結果，相當於 to such an extent that...。(A) such as 意為「例如」，後接舉例的名詞，不能接 that 子句表示結果 (C) so much as 多用於否定句，意為「甚至（連…都不）」，如 He left without so much as a goodbye.，不能引出結果子句 (D) as much as 用於比較，意為「和…一樣多」，也不能接 that 子句表示結果。故選 (B)。", "level": "C2", "topic": "so much so that"}, {"id": "M512", "type": "vocab", "q": "The popular story that Albert Einstein failed mathematics at school is ______: his school records show that he was in fact an excellent mathematics student.", "options": ["archetypal", "anachronistic", "apoplectic", "apocryphal"], "answer": 3, "explain": "句意：「愛因斯坦求學時數學不及格」這個廣為流傳的故事其實是杜撰的：他在校的成績紀錄顯示，他的數學事實上非常優秀。apocryphal「（故事、軼事）出處可疑的；杜撰的；不足採信的」，指廣為流傳卻未必屬實的說法；冒號之後以成績紀錄加以反駁，正說明這個故事並不可信。(A) archetypal 典型的；原型的，與「故事不實」無關 (B) anachronistic 時代錯置的；不合時宜的，此故事並沒有把事物放錯時代的問題 (C) apoplectic 暴怒的；中風的，用來形容人，不能形容故事。故選 (D)。", "level": "C2", "topic": "myths about famous scientists"}, {"id": "M513", "type": "dialogue", "q": "A: My cousin just paid NT$6,000 for a pair of brand-new sneakers designed to look old and muddy.\nB: ______ I'd never pay that much for shoes that look as if they've been through a swamp.\nA: Me neither, but apparently they sold out in a single day.", "options": ["Great minds think alike.", "Beauty is only skin deep.", "There's no accounting for taste.", "It takes one to know one."], "answer": 2, "explain": "句意：A 說表哥花了新台幣六千元，買了一雙全新卻刻意做得又舊又髒、像沾滿泥巴的運動鞋；B 回答「人各有所好，真是沒道理可講」，並說自己絕不會花那麼多錢買一雙看起來像在沼澤裡走過的鞋；A 說自己也不會，但聽說這款鞋一天就賣光了。There's no accounting for taste. 意為「人的喜好無從解釋；各人口味不同」，常用來委婉地表示自己無法理解別人的品味，帶有不以為然的意味，與 B 接著說自己絕不會買這種鞋相呼應。(A) Great minds think alike.「英雄所見略同」，用於雙方想法一致時，但 B 並不認同表哥的選擇 (B) Beauty is only skin deep.「美貌只是外表（內在更重要）」，用於評論人的外貌與品格，與鞋子的款式無關 (D) It takes one to know one.「彼此彼此；你自己還不是一樣」，用於反唇相譏，回擊別人對自己的批評，但 A 並沒有批評 B。故選 (C)。", "level": "C2", "topic": "fashion tastes"}, {"id": "M514", "type": "grammar", "q": "When the typhoon cut off the mountain road for three days, the family shared ______ food they had left with the elderly couple next door.", "options": ["what little", "how little", "so little", "which little"], "answer": 0, "explain": "句意：颱風使山區道路中斷了三天，那一家人把僅剩的一點食物分給了隔壁的老夫婦。what little + 不可數名詞（可數名詞則用 what few + 複數名詞）意為「僅有的那一點點…（全部）」，what 在此為關係限定詞，相當於 all the (little) food that，整個名詞子句 what little food they had left 作 shared 的受詞，what little food 則在子句中作 had left 的受詞。(B) how little 引導感嘆句或間接問句，表示「多麼少」，不能作 share 的受詞來指「那些食物」(C) so little 須與 that 子句搭配表示結果（如 They had so little food that...），無法連接 they had left 這個子句 (D) which 作關係詞時須有先行詞，不能放在句中直接修飾 little food，which little food 不成立。故選 (A)。", "level": "C2", "topic": "relative determiner (what little)"}, {"id": "M515", "type": "vocab", "q": "Before writing her history report, Mei-ling spent an entire weekend ______ over old newspapers in the library archive, searching for first-hand accounts of the 1999 Chi-Chi earthquake.", "options": ["pouring", "poring", "paring", "purring"], "answer": 1, "explain": "句意：在撰寫歷史報告之前，美玲花了一整個週末在圖書館的檔案室裡仔細翻閱舊報紙，尋找 1999 年九二一（集集）大地震的第一手記述。pore over sth 意為「專心研讀；仔細鑽研（文件、書籍、地圖等）」，spend + 時間 + V-ing，故用 poring。(A) pouring：pour 意為「倒；傾瀉」，pour over 是 pore over 常見的拼寫誤用，字面意思是「倒在…上面」(C) paring：pare 意為「削（皮）；削減」，常用 pare down (D) purring：purr 意為「（貓）發出呼嚕聲」，皆不合語意。故選 (B)。", "level": "C2", "topic": "historical research"}, {"id": "M516", "type": "grammar", "q": "Contrary to what the advertisements claim, the new model of the phone is no faster than the old one; if ______, it is slightly slower.", "options": ["something", "nothing", "everything", "anything"], "answer": 3, "explain": "句意：與廣告的宣傳相反，新款手機並沒有比舊款快；要說有什麼差別的話，反而還慢了一點。if anything 為固定用法，意為「如果要說有什麼不同的話；甚至反而」，常接在否定敘述之後，提出與預期相反的修正說法；本句先說 no faster，再以 if anything 補充 slightly slower。if 子句屬於非肯定的語境，因此用 anything 而不用 something。(A) if something 與 (C) if everything 都不是慣用說法，無法表達「反而」的意思 (B) if nothing 也不成立；相近的慣用語是 if nothing else「至少」，須加 else，語意也與「反而更慢」不合。故選 (D)。", "level": "C2", "topic": "if anything"}, {"id": "M517", "type": "dialogue", "q": "A: I'm not the least bit nervous about my speech this afternoon.\nB: ______ You've checked your notes about twenty times in the last five minutes.\nA: OK, maybe I'm a little nervous.", "options": ["That makes two of us.", "You could have fooled me.", "Now you're talking.", "I'll hold you to that."], "answer": 1, "explain": "句意：A 說自己對今天下午的演講一點也不緊張；B 回答「我可完全看不出來」，並指出 A 在過去五分鐘裡已經看了講稿大約二十次；A 只好承認或許有一點緊張。You could have fooled me. 字面意思是「你差點就騙過我了」，實為反諷，表示「我才不信；看起來完全不是這樣」，B 接著舉出 A 頻頻查看講稿的證據，A 也隨即承認。(A) That makes two of us.「我也一樣」，表示 B 也不緊張，與後面指出 A 很緊張的證據接不上 (C) Now you're talking.「這才像話；這主意好多了」，用於贊同對方提出的好建議 (D) I'll hold you to that.「我會要你說到做到」，用於對方作出承諾時，兩者皆不合語境。故選 (B)。", "level": "C2", "topic": "irony (disbelief)"}, {"id": "M518", "type": "vocab", "q": "Losing our first match of the season 7-0 was painful, but it proved a ______ lesson: it showed us exactly where our defense needed work.", "options": ["salubrious", "solitary", "salutary", "sanitary"], "answer": 2, "explain": "句意：本季首戰以零比七落敗令人難受，但事後證明這是一次有益的教訓：它讓我們清楚看見防守有哪些地方需要加強。salutary「（雖不愉快但）有益的；有教育意義的」，常與 lesson、reminder、experience、warning 搭配；painful, but... 的轉折說明慘敗雖然痛苦卻帶來益處。(A) salubrious（氣候、環境）有益健康的；（地區）乾淨宜人的，用來形容地方或空氣，不形容教訓 (B) solitary 單獨的；孤獨的 (D) sanitary 衛生的，兩者皆不合語意。故選 (C)。", "level": "C2", "topic": "learning from defeat"}, {"id": "M519", "type": "grammar", "q": "Kai-wen is the class representative, and ______ he is expected to pass on his classmates' concerns to the school administration.", "options": ["such as", "so as", "such that", "as such"], "answer": 3, "explain": "句意：凱文是班代，既然身負這個職務，他理應把同學們關切的問題轉達給學校行政單位。as such 意為「以這種身分（或性質）；就其本身而言」，such 代替前文提過的名詞 the class representative，表示「身為班代」，常用於正式文體。(A) such as 意為「例如」，後面須接所舉的例子 (B) so as 須接不定詞，寫成 so as to V 表示目的，不能單獨使用 (C) such that 意為「達到…的程度；以致於」，通常接在 be 動詞或名詞之後表示結果（如 The damage was such that...），在此結構與語意皆不合。故選 (D)。", "level": "C2", "topic": "substitution (as such)"}, {"id": "M520", "type": "dialogue", "q": "A: Do you think the new bike-sharing stations near the night market will actually cut down on traffic?\nB: ______ They've only been open for a month, so it's too early to tell.\nA: Fair enough. Let's see how things look by the end of the year.", "options": ["The jury's still out on that.", "It's a foregone conclusion.", "Hands down.", "It's an open-and-shut case."], "answer": 0, "explain": "句意：A 問 B 是否認為夜市附近新設的共享單車站真的能減少車流；B 回答「這一點還沒有定論」，因為才啟用一個月，現在下判斷還太早；A 說也對，看看到年底情況如何再說。The jury is still out (on sth). 字面意思是「陪審團仍在審議」，引申為「（某事）尚無定論；仍有待觀察」，與 B 接著說的 it's too early to tell 相符。(B) It's a foregone conclusion.「結果早已注定；必然如此」(C) Hands down.「毫無疑問；輕而易舉地」(D) It's an open-and-shut case.「這是一目了然、毫無爭議的事」，三者都表示答案十分明確，與「現在下判斷還太早」互相矛盾。故選 (A)。", "level": "C2", "topic": "hedging (no conclusion yet)"}, {"id": "M521", "type": "vocab", "q": "As the final seconds of the championship game ticked away with the score still tied, the tension in the packed gym was almost ______.", "options": ["palatable", "potable", "palpable", "portable"], "answer": 2, "explain": "句意：冠軍賽只剩最後幾秒，時間一點一滴地流逝，比數仍然平手，擠滿觀眾的體育館裡，緊張的氣氛幾乎摸得到。palpable「（感覺、氣氛）強烈到幾乎可以觸摸得到的；明顯可感的」，the tension was palpable 為常見搭配，almost palpable 即「緊張得幾乎摸得到」。(A) palatable「美味可口的；（想法、方案）可以接受的」(B) potable「（水）可飲用的」(D) portable「可攜帶的」，四個字拼法相近，但只有 palpable 能形容強烈的緊張氣氛。故選 (C)。", "level": "C2", "topic": "sports finals"}, {"id": "M522", "type": "grammar", "q": "The survey had only forty participants, which is admittedly a very small sample. ______, its results closely match those of several much larger studies, so they should not simply be dismissed.", "options": ["Be that as it may", "So be it", "As it may be", "Come what may"], "answer": 0, "explain": "句意：這項調查只有四十位受訪者，必須承認樣本非常小。儘管如此，其結果與好幾項規模大得多的研究十分吻合，因此不應輕易否定。Be that as it may「儘管如此；話雖如此」是保留原形 be 的假設語氣並採倒裝語序的慣用語，用來先承認前述事實，再提出相反的論點，等於 Even so 或 Nevertheless。(B) So be it「那就這樣吧」，表示無奈地接受某個結果，不能用來引導轉折 (C) As it may be 並非慣用說法（相近的慣用語是 as the case may be「視情況而定」）(D) Come what may「無論發生什麼事」，指未來可能發生的情況，與先承認樣本小、再轉而肯定結果的語意不合。故選 (A)。", "level": "C2", "topic": "formulaic subjunctive (be that as it may)"}, {"id": "M523", "type": "dialogue", "q": "A: The coach wants us to win all five of our remaining games — and they're against the top five teams in the league.\nB: ______ We haven't beaten any of those teams in two years.\nA: I know, but he says aiming high is half the battle.", "options": ["That's a given.", "That's the spirit!", "That's a weight off my mind.", "That's a tall order."], "answer": 3, "explain": "句意：A 說教練要求他們贏下剩下的五場比賽，而且對手都是聯盟排名前五的球隊；B 回答「這要求也太難達成了」，接著說他們兩年來從未贏過這幾支球隊；A 說他知道，但教練說目標定得高就已成功一半。a tall order「難以達成的要求；苛求」，以委婉的方式表達懷疑，與 B 接著舉出的戰績相呼應。(A) That's a given.「那是理所當然的」，等於認為贏球十拿九穩 (B) That's the spirit!「這才對嘛！」，用來鼓勵對方的積極態度 (C) That's a weight off my mind.「這下我放心了」，三者都表示樂觀或安心，與 B 兩年未曾獲勝的悲觀說法矛盾。故選 (D)。", "level": "C2", "topic": "unrealistic goals"}, {"id": "M524", "type": "vocab", "q": "With their red-brick arcades and old tea merchants' shops, the narrow streets of Dadaocheng are ______ of the Taipei of a century ago.", "options": ["reticent", "redolent", "replete", "resplendent"], "answer": 1, "explain": "句意：大稻埕狹窄的街道兩旁有紅磚騎樓和老茶行，令人強烈聯想起一百年前的台北。redolent of「令人聯想起…的；充滿…氣息的」，屬文雅用字，常形容事物喚起對某個時代或地方的回憶。(A) reticent「沉默寡言的；不願透露的」，用來形容人，常接 about (C) replete「充滿的；飽足的」，須接 with（be replete with），且只表示「裝滿」，沒有「令人回想起」的意思 (D) resplendent「華麗燦爛的」，常接 in（如 resplendent in red silk），不接 of，語意也不合。故選 (B)。", "level": "C2", "topic": "historic districts"}, {"id": "M525", "type": "grammar", "q": "Just as a building needs a solid foundation, ______ a language learner needs a firm grasp of basic grammar before tackling complex texts.", "options": ["such", "as", "so", "that"], "answer": 2, "explain": "句意：正如一棟建築需要穩固的地基，語言學習者在挑戰艱深的文章之前，也需要牢牢掌握基礎文法。Just as ..., so ...「正如…，…也同樣…」是表示類比的關聯結構：just as 引導從屬子句提出比喻，後半的主要子句以 so 開頭呼應（so 之後也可倒裝，如 so does a language learner need ...）。(A) such 是限定詞或代名詞，不能用來引導主要子句與 just as 呼應 (B) as 會使後半句也變成從屬子句，整句缺少主要子句 (D) that 會使後半句變成名詞子句，同樣缺少主要子句。故選 (C)。", "level": "C2", "topic": "correlative comparison (just as ... so ...)"}, {"id": "M526", "type": "dialogue", "q": "A: I've been wondering — why is the sea salty when most of the rivers that flow into it aren't?\nB: ______ I've never really thought about it. Shall we look it up?\nA: Good idea. I'll search for it on my phone.", "options": ["You've got me there.", "You're on.", "You've lost me.", "You can't miss it."], "answer": 0, "explain": "句意：A 說自己一直在想，為什麼流入大海的河流大多不鹹，海水卻是鹹的；B 回答「這可考倒我了」，並說自己從沒想過這個問題，提議查查看；A 說好主意，他用手機搜尋。You've got me there.「你問倒我了；這我答不出來」，用於坦承無法回答對方的問題，也可用於承認對方的論點有理。(B) You're on.「一言為定；奉陪到底」，用於接受對方的打賭或挑戰，但 A 只是提出疑問 (C) You've lost me.「我聽不懂你在說什麼」，但 B 接著說自己從沒想過這個問題，顯然聽懂了問題，只是不知道答案 (D) You can't miss it.「你一定找得到」，用於為人指路。故選 (A)。", "level": "C2", "topic": "everyday science questions"}, {"id": "M527", "type": "grammar", "q": "'Look — the rain has finally stopped,' said Amy, peering out of the classroom window. '______!' replied Ben, already reaching for his basketball.", "options": ["So has it", "So it has", "So it is", "It has so"], "answer": 1, "explain": "句意：艾咪望著教室窗外說：「你看，雨終於停了。」班回答：「還真的停了！」一邊已經伸手去拿他的籃球。「So + 主詞 + 助動詞」用來表示（驚訝或欣喜地）確認對方所說的事屬實，助動詞須與前句的動詞一致：前句為現在完成式 has stopped，故用 So it has。(A) So has it 為「So + 助動詞 + 主詞」的倒裝句型，表示「另一個主詞也是如此」（如 Amy has finished, and so has Ben.），但此處並沒有另一件同樣停了的事物 (C) So it is 的助動詞 is 與前句的 has stopped 不一致 (D) It has so 是美式口語（多見於孩童爭辯）中用來反駁對方否定說法的句型（如 \"It hasn't stopped.\" \"It has so!\"「明明就停了！」），但艾咪說的是肯定句，班是表示同意而非反駁。故選 (B)。", "level": "C2", "topic": "emphatic so + subject + auxiliary"}, {"id": "M528", "type": "vocab", "q": "Plum blossoms, which open in the coldest weeks of winter, have long been regarded in Chinese culture as a ______ of spring.", "options": ["vestige", "pinnacle", "misnomer", "harbinger"], "answer": 3, "explain": "句意：梅花在冬季最寒冷的幾週綻放，在華人文化中長久以來被視為春天的先兆。harbinger「預兆；先驅」，指預示某事即將到來的人或事物，a harbinger of spring 為常見搭配，與梅花在寒冬開花、預告春天將至相符。(A) vestige「殘留的痕跡；遺跡」，指已經消失的事物所留下的部分，方向與「預告即將到來」正好相反 (B) pinnacle「頂峰；巔峰」(C) misnomer「名稱不當；用詞不當」，皆不合語意。故選 (D)。", "level": "C2", "topic": "traditional symbolism"}, {"id": "M529", "type": "dialogue", "q": "A: My aunt brought over far too many pineapple cakes. There's a whole box left in the kitchen if anyone's interested.\nB: ______ I had to skip lunch because of the club meeting.\nA: Help yourself, then. Take as many as you like.", "options": ["I wouldn't say no.", "I'd rather not, thanks.", "Suit yourself.", "I couldn't eat another bite."], "answer": 0, "explain": "句意：A 說阿姨帶來太多鳳梨酥，廚房裡還剩一整盒，問有沒有人想吃；B 回答「那我就不客氣了」，接著說自己因為社團開會沒吃午餐；A 說那就自己拿吧，想拿幾個就拿幾個。I wouldn't say no. 字面意思是「我不會說不」，是以否定的方式委婉表達肯定（曲言法，litotes），意思是「好啊，我很樂意」，常用於接受食物或邀請。(B) I'd rather not, thanks.「謝了，我還是不要好了」(D) I couldn't eat another bite.「我一口都吃不下了」，兩者都表示拒絕，與 B 沒吃午餐以及 A 請他自己拿的回應矛盾 (C) Suit yourself.「隨你便」，用於對方不接受自己的建議時，帶有些許不悅，不能用來回應別人的分享。故選 (A)。", "level": "C2", "topic": "accepting offers"}, {"id": "M530", "type": "grammar", "q": "______ its flaws — the pacing is uneven and the ending feels rushed — the documentary offers a rare and moving glimpse into the daily lives of the lighthouse keepers on Taiwan's outlying islands.", "options": ["However", "Whereas", "Whatever", "Whether"], "answer": 2, "explain": "句意：無論這部紀錄片有什麼缺點（節奏不夠平均，結尾也顯得倉促），它仍讓觀眾難得而動人地一窺台灣離島燈塔看守人的日常生活。「Whatever + 名詞（片語）」是省略動詞的讓步結構，等於 Whatever its flaws may be（無論它有什麼缺點），用來先承認缺點、再強調優點。(A) However 表示「無論多麼…」時須接形容詞或副詞（如 However long it is），不能直接接名詞片語 its flaws (B) Whereas「然而；鑑於」為連接詞，後面須接完整子句 (D) Whether 表示讓步時須搭配 or（whether ... or ...），後面也須接子句。故選 (C)。", "level": "C2", "topic": "verbless concessive clause (whatever + noun)"}, {"id": "M531", "type": "vocab", "q": "Having dabbled in pottery, jazz piano and landscape painting without sticking with any of them for more than a few months, Victor cheerfully admits that he is something of a ______.", "options": ["connoisseur", "virtuoso", "philistine", "dilettante"], "answer": 3, "explain": "句意：維克多涉獵過陶藝、爵士鋼琴和風景畫，卻沒有一樣持續超過幾個月，他也爽快地承認自己有幾分像個淺嘗輒止的業餘玩家。dilettante「（對藝術、學問）淺嘗輒止的業餘愛好者」，略帶貶意，與 dabbled in（涉獵）及 without sticking with any of them 相呼應；something of a + 名詞 意為「有幾分像…」。(A) connoisseur「鑑賞家；行家」，指在藝術、美食等方面具專業眼光的人 (B) virtuoso「（尤指音樂的）大師；技藝精湛的人」，兩者都須長期鑽研，與每樣只學幾個月矛盾 (C) philistine「對藝術文化不感興趣甚至加以輕視的人」，與他熱衷嘗試各種藝術活動不符。故選 (D)。", "level": "C2", "topic": "hobbies"}, {"id": "M532", "type": "dialogue", "q": "A: Admit it — the atmosphere at the old baseball stadium was far better than at this new one.\nB: ______ But at least this one has a roof, so games don't get canceled every time it rains.\nA: True. I suppose you can't have everything.", "options": ["I'll hold you to that.", "I'll take that as a compliment.", "I'll give you that.", "I'll pass on that."], "answer": 2, "explain": "句意：A 要 B 承認舊棒球場的氣氛比這座新球場好得多；B 回答「這點我承認」，但接著說至少這座有屋頂，比賽不會每逢下雨就取消；A 說也是，總不能什麼都要。I'll give you that.「這一點我承認」，用於討論中先讓步、承認對方的某個論點，後面常接 But 再提出自己的看法。(A) I'll hold you to that.「我會要你說到做到」，用於對方作出承諾時 (B) I'll take that as a compliment.「我就當你是在稱讚我」，用於回應語意模糊或帶刺的評語 (D) I'll pass on that.「這個我就不要了」，用於婉拒提議，三者都無法回應 A 要 B 承認的論點，也接不上後面以 But 提出的反面理由。故選 (C)。", "level": "C2", "topic": "conceding a point"}, {"id": "M533", "type": "grammar", "q": "Most of the children from the small village in southern Taiwan had never even seen snow, ______ tried skiing on it, so the school trip to Hokkaido was the adventure of a lifetime.", "options": ["much less", "much more", "still more", "no less"], "answer": 0, "explain": "句意：這個台灣南部小村莊的孩子大多連雪都沒見過，更別說在雪上滑雪了，所以這趟北海道校外教學是他們一生難得的冒險。much less「更不用說；何況」，用於否定句之後，引出比前面更不可能的事，等於 let alone 或 still less；本句前面有 never，再用 much less 引出更不可能的「滑雪」，tried 與 had never even seen 的 seen 同為過去分詞，形成平行結構。(B) much more (C) still more 雖然也有「更不用說」的意思，但只能接在肯定句之後，且屬較舊式的用法，不能接在否定句之後 (D) no less「（強調）竟然；不亞於」，用來凸顯某事出人意料地了不起（如 He was congratulated by the mayor, no less.），語意不合。故選 (A)。", "level": "C2", "topic": "much less (after a negative)"}, {"id": "M534", "type": "vocab", "q": "By the time Iris reached the dormitory office, only one bed was left, in a cramped room right next to the noisy laundry room. It was ______: take it or find somewhere else to sleep.", "options": ["a Catch-22", "Hobson's choice", "a red herring", "a moot point"], "answer": 1, "explain": "句意：等艾瑞絲趕到宿舍辦公室時，只剩下一個床位，在一間緊鄰吵雜洗衣間的狹小房間裡。她根本沒得選：要嘛接受，要嘛另覓住處。Hobson's choice「沒有選擇的選擇；要嘛接受、要嘛放棄」，源自英國劍橋出租馬匹的 Thomas Hobson（約 1544–1631）：他只讓顧客牽走最靠近馬廄門口的那一匹，否則就一匹也別牽，正好對應冒號後的 take it or find somewhere else to sleep。(A) a Catch-22「進退兩難的困境」，指因規則或條件互相矛盾而無法脫身的情況（如沒有工作經驗就找不到工作，找不到工作又無法累積經驗），此處並沒有互相矛盾的條件 (C) a red herring「轉移注意力的事物」(D) a moot point「有爭議而無定論的問題；已無實際意義的問題」，皆不合語意。故選 (B)。", "level": "C2", "topic": "university dormitories"}, {"id": "M535", "type": "grammar", "q": "______ no further questions from the floor, the chairperson thanked the speakers and declared the meeting closed.", "options": ["There being", "There were", "Being", "It being"], "answer": 0, "explain": "句意：由於台下沒有人再提問，主席向講者致謝，並宣布會議結束。這是獨立分詞構句（absolute construction）：分詞構句的主詞若與主要子句不同，就必須保留自己的主詞。原句為 Because there were no further questions ...，改為分詞構句時保留虛主詞 there，be 動詞改為 being，成為 There being no further questions。(B) There were 會使兩個獨立子句只以逗點相連，形成逗點誤接（comma splice） (C) Being 省略了主詞，其邏輯主詞會變成主要子句的 the chairperson，造成懸垂分詞的錯誤 (D) It being 可用於 It being Sunday（因為是星期天）這類以 it 表示時間、天氣的結構，但要表示「有／沒有某物」須用 there，不能用 it。故選 (A)。", "level": "C2", "topic": "absolute construction (there being)"}, {"id": "M536", "type": "dialogue", "q": "A: Didn't the guidebook describe this trail as 'an easy two-hour walk'?\nB: ______ We've been climbing for four hours, and the summit still isn't in sight.\nA: Next time, let's read some recent reviews online as well.", "options": ["So far, so good.", "So much for the guidebook.", "Better late than never.", "The sky's the limit."], "answer": 1, "explain": "句意：A 問旅遊指南不是說這條步道是「輕鬆的兩小時健行」嗎；B 回答「旅遊指南說的果然靠不住」，接著說他們已經爬了四個小時，卻還看不到山頂；A 說下次也要上網看看最近的評論。「So much for + 名詞」表示原本期待或相信的事物結果令人失望、根本不可靠，帶有反諷的語氣；此處指旅遊指南的描述與事實不符，也呼應 A 下次改看網路評論的建議。(A) So far, so good.「到目前為止一切順利」，與爬了四小時還看不到山頂矛盾 (C) Better late than never.「遲到總比不到好」，用於事情終於完成或終於抵達時，但他們尚未登頂 (D) The sky's the limit.「沒有極限；前途無量」，與語境無關。故選 (B)。", "level": "C2", "topic": "travel guidebooks"}, {"id": "M537", "type": "vocab", "q": "Many residents of the fishing village feel deeply ______ about the proposed resort: they welcome the jobs it would bring, yet fear it would change the character of their quiet harbor forever.", "options": ["ambiguous", "apathetic", "adamant", "ambivalent"], "answer": 3, "explain": "句意：這個漁村的許多居民對興建度假村的提案感到非常矛盾：他們歡迎度假村可能帶來的工作機會，卻又擔心它會永遠改變寧靜港口的風貌。ambivalent「（情感上）矛盾的；愛憎交織的」，形容人對同一件事同時抱持兩種相反的感受，與冒號後的 welcome ... yet fear ... 相呼應。(A) ambiguous「模稜兩可的；有歧義的」，形容字詞、說法或情況可作多種解釋，不用來形容人的感受，feel ambiguous 是常見的誤用 (B) apathetic「冷漠的；漠不關心的」，與居民既歡迎又擔心的反應不符 (C) adamant「堅決的；堅定不移的」，與內心矛盾正好相反。故選 (D)。", "level": "C2", "topic": "tourism development"}, {"id": "M538", "type": "grammar", "q": "______ the little wooden temple survived the earthquake at all is remarkable, given that almost every other building on the same street collapsed.", "options": ["What", "It", "That", "Which"], "answer": 2, "explain": "句意：這座小小的木造廟宇竟然能在地震中倖存，實在了不起，因為同一條街上幾乎所有其他建築都倒塌了。名詞子句可以當主詞：「That + 完整子句」作主詞，後接單數動詞，等於 It is remarkable that ...。本句的主要動詞是 is，前面的 the little wooden temple survived the earthquake at all 是一個完整子句，須用 that 引導成名詞子句作主詞；at all 在此加強語氣，表示「竟然能」。(A) What 引導名詞子句時，本身須在子句中擔任主詞、受詞或補語，但 survived 已有受詞 the earthquake，子句結構完整，不能用 what (B) It 會造成 It 與 the little wooden temple 兩個主詞並列，不合文法；若要用 it，須改為 It is remarkable that ... (D) Which 引導形容詞子句時須有先行詞，作疑問詞時也須在子句中擔任成分，此處兩者皆不成立。故選 (C)。", "level": "C2", "topic": "noun clause (that-clause as subject)"}, {"id": "M539", "type": "dialogue", "q": "A: Is it true that the school cafeteria is closing for renovations next semester?\nB: ______ but I overheard two teachers saying something about new kitchen equipment arriving in January.\nA: Hmm. I'll wait for the official announcement, then.", "options": ["Mark my words,", "Take it from me,", "Rest assured,", "Don't quote me on this,"], "answer": 3, "explain": "句意：A 問學校餐廳下學期是不是真的要關閉整修；B 回答「我說的不一定準，別當真」，但他無意間聽到兩位老師提到一月會有新的廚房設備進來；A 說那他還是等正式公告好了。Don't quote me on this「別引用我的話；我說的不見得準確」是一種模糊限制語（hedging），用來表示消息未經證實，與後面的 but、overheard ... saying something about ... 以及 A 決定等正式公告相呼應。(A) Mark my words「記住我的話（將來一定會應驗）」(B) Take it from me「相信我（我很清楚）」(C) Rest assured「請放心；儘管放心」，三者都表示說話者十分有把握，與道聽塗說的不確定語氣以及 but 所表示的轉折不符。故選 (D)。", "level": "C2", "topic": "hedging (unconfirmed news)"}, {"id": "M540", "type": "vocab", "q": "Determined to stay true to her grandmother's recipes, the chef ______ ready-made sauces, preparing every one of them from scratch each morning.", "options": ["espouses", "eschews", "exudes", "extols"], "answer": 1, "explain": "句意：這位主廚決心忠於祖母的食譜，因此刻意不用現成的醬料，每天早上都從頭親手調製每一種醬料。eschew「刻意避開；戒絕」，屬正式用字，常指出於原則而不使用某物或不做某事，與 preparing every one of them from scratch 相呼應。(A) espouses「擁護；信奉（主張、信念）」，受詞通常是理念，且語意與自製醬料的做法相反 (C) exudes「散發出（氣味、自信等）」，語意不合 (D) extols「讚揚；頌揚」，與她堅持不用現成醬料矛盾。故選 (B)。", "level": "C2", "topic": "cooking"}];
